// ---------- MetricComponents.js ----------
// 通用指標展示元件：SimpleLineChart / MultiLineChart / SimpleMetricCard（外觀委派 window.UI.StatCell）

const SimpleLineChart = ({ data, dataKey, color = "#12A150", xLabels = null, valueGetter = null }) => {
    if (!data || data.length < 2) return <div className="h-40 flex items-center justify-center text-slate-500 text-xs">數據不足，無法繪製趨勢圖</div>;
    const height = 150; const width = 500; const padding = 20; const paddingLeft = 40;
    const values = data.map(d => parseFloat(valueGetter ? valueGetter(d) : (d.stat?.[dataKey] ?? d.tracking?.[dataKey] ?? 0)));
    const min = Math.min(...values); const max = Math.max(...values);
    const range = max - min || 1; const buffer = range * 0.1;
    const domainMin = min - buffer; const domainMax = max + buffer; const domainRange = domainMax - domainMin;
    const points = values.map((val, index) => { const x = paddingLeft + (index / (values.length - 1)) * (width - paddingLeft - padding); const y = height - padding - ((val - domainMin) / domainRange) * (height - 2 * padding); return `${x},${y}`; }).join(' ');
    const ticks = []; const numTicks = 5; for (let i = 0; i < numTicks; i++) { const val = domainMin + (domainRange * i) / (numTicks - 1); const y = height - padding - (i / (numTicks - 1)) * (height - 2 * padding); ticks.push({ val, y }); }
    return (<div className="w-full overflow-hidden mb-2 border border-white/10 p-2"><svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full">{ticks.map((tick, i) => (<g key={i}><line x1={paddingLeft} y1={tick.y} x2={width - padding} y2={tick.y} stroke="rgba(255,255,255,0.07)" strokeWidth="1" strokeDasharray="4" opacity="0.6" /><text x={paddingLeft - 5} y={tick.y + 3} textAnchor="end" fill="#64748b" fontSize="10" fontFamily="monospace">{tick.val?.toFixed(2) || 0}</text></g>))}<polyline fill="none" stroke={color} strokeWidth="3" points={points} />{values.map((val, index) => { const x = paddingLeft + (index / (values.length - 1)) * (width - paddingLeft - padding); const y = height - padding - ((val - domainMin) / domainRange) * (height - 2 * padding); return (<g key={index} className="group"><circle cx={x} cy={y} r="4" fill="#0C1A2E" stroke={color} strokeWidth="2" className="chart-dot transition-all duration-200" /><rect x={x - 15} y={y - 25} width="30" height="16" rx="4" fill="#000" className="opacity-0 group-hover:opacity-100 transition-opacity" /><text x={x} y={y - 13} textAnchor="middle" fill="white" fontSize="10" className="opacity-0 group-hover:opacity-100 transition-opacity font-mono font-bold pointer-events-none">{val}</text><text x={x} y={height - 5} textAnchor="middle" fill="#64748b" fontSize="9">{xLabels ? xLabels[index] : data[index].date.slice(5).replace('-', '/')}</text></g>); })}</svg></div>);
};

// naReason：該指標對此球員「語意上不適用」（例：新援在別隊那季，最近防守者資料綁 TeamID 抓不到）。
// 三態必須分清楚，判定一律用 == null 而非 falsy，否則真的是 0 的欄位會被吃掉顯示成「—」：
//   未載入 → 由呼叫端的 skeleton 處理（本元件不參與）
//   不適用 → value == null 且有 naReason → 灰色「—」+ tooltip
//   真的是 0 → typeof value === 'number' → 照常顯示 0
const SimpleMetricCard = ({ title, englishLabel, value, prevValue, unit = "", betterIsLarger = true, naReason = null }) => (
    <window.UI.StatCell label={title} en={englishLabel} value={value} prevValue={prevValue}
        unit={unit} betterIsLarger={betterIsLarger} naReason={naReason} />
);

// 多指標折線圖：每個指標獨立歸一到 0–100，呈現相對走勢
const MultiLineChart = ({ data, metrics, xLabels = null }) => {
    if (!data || data.length < 2 || !metrics || metrics.length === 0) {
        return <div className="h-40 flex items-center justify-center text-slate-500 text-xs">資料不足</div>;
    }
    const height = 180, width = 500, padding = 20, paddingLeft = 40;
    const COLORS = ['#12A150', '#60a5fa', '#f59e0b', '#ec4899', '#a78bfa'];
    const seriesList = metrics.map((m, i) => {
        const values = data.map(d => parseFloat(d.stat?.[m.key] ?? d.tracking?.[m.key] ?? 0));
        const min = Math.min(...values), max = Math.max(...values);
        const range = max - min || 1;
        return {
            ...m,
            color: m.color || COLORS[i % COLORS.length],
            values, min, max,
            normalized: values.map(v => ((v - min) / range) * 100),
        };
    });
    const pts = (norm) => norm.map((v, i) => {
        const x = paddingLeft + (i / (norm.length - 1)) * (width - paddingLeft - padding);
        const y = height - padding - (v / 100) * (height - 2 * padding);
        return `${x},${y}`;
    }).join(' ');
    return (
        <div className="w-full overflow-hidden mb-2 border border-white/10 p-2">
            <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full">
                {[0, 25, 50, 75, 100].map(v => {
                    const y = height - padding - (v / 100) * (height - 2 * padding);
                    return <line key={v} x1={paddingLeft} y1={y} x2={width - padding} y2={y} stroke="rgba(255,255,255,0.07)" strokeWidth="1" strokeDasharray="4" opacity="0.6" />;
                })}
                {seriesList.map(s => (
                    <g key={s.key}>
                        <polyline fill="none" stroke={s.color} strokeWidth="2" points={pts(s.normalized)} />
                        {s.values.map((val, i) => {
                            const x = paddingLeft + (i / (s.values.length - 1)) * (width - paddingLeft - padding);
                            const y = height - padding - (s.normalized[i] / 100) * (height - 2 * padding);
                            return (
                                <g key={i} className="group">
                                    <circle cx={x} cy={y} r="3" fill="#0C1A2E" stroke={s.color} strokeWidth="2" className="chart-dot" />
                                    <title>{`${s.label}: ${val}`}</title>
                                </g>
                            );
                        })}
                    </g>
                ))}
                {data.map((d, i) => {
                    const x = paddingLeft + (i / (data.length - 1)) * (width - paddingLeft - padding);
                    const label = xLabels ? xLabels[i] : (d.date ? d.date.slice(5).replace('-', '/') : '');
                    return <text key={i} x={x} y={height - 5} textAnchor="middle" fill="#64748b" fontSize="9">{label}</text>;
                })}
            </svg>
            <div className="flex flex-wrap gap-x-4 gap-y-1 mt-1 px-2">
                {seriesList.map(s => (
                    <div key={s.key} className="flex items-center gap-1.5 text-[11px] text-slate-300">
                        <span className="w-3 h-3 rounded-sm inline-block" style={{ backgroundColor: s.color }}></span>
                        <span>{s.label}</span>
                        <span className="text-slate-500 font-mono text-[10px]">({s.min.toFixed(1)}–{s.max.toFixed(1)})</span>
                    </div>
                ))}
            </div>
            <p className="text-[10px] text-slate-500 mt-1 px-2">* 各指標獨立歸一 0–100 呈現相對走勢；括號為實際區間</p>
        </div>
    );
};

window.SimpleLineChart = SimpleLineChart;
window.SimpleMetricCard = SimpleMetricCard;
window.MultiLineChart = MultiLineChart;


// ---------- PlayTypeCard.js ----------
// PlayType 卡片元件：PPP 大字 + 百分位色階條（Synergy PERCENTILE）+ FG% / 使用率 / 每場球權
// 漲跌比對前一份快照；防守面 PPP 與 FG% 越低越好（betterIsLarger=false），百分位一律越高越好
const PlayTypeCard = ({ type, current, prev, onClick, side }) => {
    if (!current) return null;
    const UI = window.UI;
    const isDefensive = side === 'defensive';
    const num = (v) => (typeof v === 'number' ? v : null);
    // NBA 在部分快照（例：2025-26 球員季後賽 06-15）的 POSS_PCT 全回 0。有球權卻 0% 不可能是真值，
    // 視為「未提供」顯示「—」。不自行用 possTotal 推算：NBA 不列低球權類型，總和偏少、推算值會失真
    const freqMissing = current.freq === 0 && (current.possTotal > 0 || current.poss > 0);
    const freq = freqMissing ? null : num(current.freq);
    return (
        <div onClick={() => onClick({ type: 'playtype', id: type })}
            className="group p-4 border border-white/[0.08] bg-white/[0.02] hover:border-white/20 hover:bg-white/[0.04] transition-colors cursor-pointer min-w-0">
            <div className="flex items-baseline justify-between gap-2">
                <h3 className="font-display text-[15px] font-semibold uppercase tracking-wide text-slate-200 truncate" title={type}>{type}</h3>
                <span className="hidden sm:inline shrink-0 font-mono text-[10px] text-slate-500 group-hover:text-[#12A150] transition-colors">走勢 →</span>
            </div>
            <div className="mt-2 flex items-baseline gap-1.5">
                <span className="font-display text-[34px] font-semibold leading-none tabular-nums text-slate-50">{current.ppp}</span>
                <span className="font-mono text-[10px] text-slate-500">PPP</span>
                <span className="ml-auto"><UI.Delta value={current.ppp} prevValue={prev?.ppp} betterIsLarger={!isDefensive} digits={2} /></span>
            </div>
            <UI.PctBar value={num(current.percentile)} label="PR" />
            <dl className="mt-3 grid grid-cols-3 gap-2 border-t border-white/[0.08] pt-2.5">
                <div className="min-w-0">
                    <dt className="font-mono text-[10px] text-slate-500">FG%</dt>
                    <dd className="flex items-baseline gap-1 font-mono text-[12px] tabular-nums text-slate-200">
                        {num(current.fgPct) != null ? current.fgPct + '%' : '—'}
                    </dd>
                    <UI.Delta value={current.fgPct} prevValue={prev?.fgPct} unit="%" betterIsLarger={!isDefensive} />
                </div>
                <div className="min-w-0">
                    <dt className="font-mono text-[10px] text-slate-500" title="此類型佔全部球權的比例">Freq</dt>
                    <dd className={`font-mono text-[12px] tabular-nums ${freq != null ? 'text-slate-200' : 'text-slate-600'}`}
                        title={freqMissing ? 'NBA 未提供此快照的使用率（POSS_PCT 回傳 0）' : undefined}>{freq != null ? freq + '%' : '—'}</dd>
                </div>
                <div className="min-w-0">
                    <dt className="font-mono text-[10px] text-slate-500" title="每場球權數">Poss/G</dt>
                    <dd className="font-mono text-[12px] tabular-nums text-slate-200">{num(current.poss) != null ? current.poss : '—'}</dd>
                </div>
            </dl>
        </div>
    );
};

window.PlayTypeCard = PlayTypeCard;


// ---------- PlaytypeSection.js ----------
// Playtype 章節（Synergy 式）：預設可排序表格，可切回卡片牆；選擇記在 localStorage
// 表格欄：類型｜使用率 Freq｜每場球權 Poss/G｜PPP（含 vs 前一份快照）｜聯盟百分位｜FG%
// 點類型名稱開走勢 Modal（與卡片點擊相同：onOpen({ type:'playtype', id })）
// 防守面：PPP、FG% 越低越好；百分位攻守皆越高越好（已以資料驗證）
const PlaytypeSection = ({ title, stats, prevStats, side, onOpen }) => {
    const { useState } = React;
    const UI = window.UI;
    const PlayTypeCard = window.PlayTypeCard;
    const isDef = side === 'defensive';
    const [view, setView] = useState(() => { try { return localStorage.getItem('wt_pref_playtypeView') || 'table'; } catch (e) { return 'table'; } });
    const changeView = (v) => { setView(v); try { localStorage.setItem('wt_pref_playtypeView', v); } catch (e) { /* ignore */ } };

    const ofSide = (arr) => (arr || []).filter(s => (s.side || 'offensive') === side);
    const prevOf = (type) => ofSide(prevStats).find(s => s.playType === type);
    // NBA 部分快照的 POSS_PCT 全回 0（有球權卻 0% 不可能）→ 視為未提供（同 PlayTypeCard）
    const freqOf = (r) => (r.freq === 0 && (r.possTotal > 0 || r.poss > 0)) ? null : (typeof r.freq === 'number' ? r.freq : null);
    const rows = ofSide(stats).map(r => ({ ...r, _freq: freqOf(r), _prev: prevOf(r.playType) }));
    const freqMissing = rows.some(r => r._freq == null && (r.possTotal > 0 || r.poss > 0));

    const columns = [
        { key: 'playType', label: '類型', en: 'Play Type', align: 'left',
            render: (r) => (
                <button type="button" onClick={() => onOpen({ type: 'playtype', id: r.playType })}
                    className="group inline-flex items-baseline gap-1.5 py-[2px] text-left" title="看當季走勢">
                    <span className="font-display text-[15px] font-semibold uppercase tracking-wide text-slate-100 group-hover:text-[#12A150]">{r.playType}</span>
                    <span data-export-hide className="font-mono text-[10px] text-slate-600 group-hover:text-[#12A150]">↗</span>
                </button>),
            after: (r) => (<>
                <UI.Info k={`PT_${r.playType}`} />
                <UI.CopyBtn className="!opacity-50 hover:!opacity-100"
                    text={() => UI.citeLine({ label: `${r.playType} Playtype（${isDef ? '防守' : '進攻'}）`, gkey: 'PPP',
                        value: `PPP ${typeof r.ppp === 'number' ? r.ppp.toFixed(2) : '—'}、聯盟百分位 ${typeof r.percentile === 'number' ? r.percentile.toFixed(1) : '—'}、使用率 ${r._freq != null ? r._freq.toFixed(1) + '%' : '未提供'}、每場球權 ${typeof r.poss === 'number' ? r.poss.toFixed(1) : '—'}` })} />
            </>) },
        { key: '_freq', label: '使用率', en: 'Freq%', gkey: 'FREQ', render: (r) => r._freq == null ? <span className="text-slate-600" title={freqMissing ? 'NBA 未提供此快照的使用率' : undefined}>—</span> : r._freq.toFixed(1) + '%' },
        { key: 'poss', label: '每場球權', en: 'Poss/G', gkey: 'POSS', render: (r) => typeof r.poss === 'number' ? r.poss.toFixed(1) : '—' },
        { key: 'ppp', label: 'PPP', en: isDef ? '被得分效率' : '每球權得分', gkey: 'PPP',
            render: (r) => (
                <span className="inline-flex items-baseline gap-2">
                    <UI.Delta value={r.ppp} prevValue={r._prev?.ppp} betterIsLarger={!isDef} digits={2} />
                    <span className="text-slate-50">{typeof r.ppp === 'number' ? r.ppp.toFixed(2) : '—'}</span>
                </span>) },
        { key: 'percentile', label: '聯盟百分位', en: 'Percentile', gkey: 'PERCENTILE', sortValue: (r) => r.percentile,
            render: (r) => typeof r.percentile !== 'number' ? '—' : (
                <span className="inline-flex items-center gap-2">
                    <span className="relative inline-block h-[3px] w-16 bg-white/[0.08]" aria-hidden="true">
                        <span className="absolute inset-y-0 left-0" style={{ width: Math.max(0, Math.min(100, r.percentile)) + '%', background: UI.pctColor(r.percentile) }}></span>
                    </span>
                    <span className="w-9 text-right" style={{ color: UI.pctColor(r.percentile) }}>{r.percentile.toFixed(1)}</span>
                </span>) },
        { key: 'fgPct', label: '命中率', en: 'FG%', gkey: 'FG_PCT', render: (r) => typeof r.fgPct === 'number' ? r.fgPct.toFixed(1) + '%' : '—' },
    ];

    return (
        <UI.Section title={title} en="Synergy Playtype" accent={isDef ? 'red' : 'green'}
            sub={`${isDef ? '防守面：PPP 為對手每球權得分，越低越好' : '進攻面：PPP 為每球權得分'} · 聯盟百分位越高越好 · 變化箭頭為 vs 前一份快照`}
            right={<UI.Seg ariaLabel="檢視方式" size="sm" value={view} onChange={changeView}
                options={[{ value: 'table', label: '表格' }, { value: 'cards', label: '卡片' }]} />}>
            {rows.length === 0 ? (
                <UI.Note>此對象沒有{isDef ? '防守' : '進攻'}面的 Playtype 資料</UI.Note>
            ) : view === 'table' ? (
                <UI.DataTable caption={`${title} Synergy Playtype`} rows={rows} rowKey={(r) => r.playType}
                    exportTitle={`Synergy Playtype（${isDef ? '防守' : '進攻'}）`}
                    initialSort={{ key: 'poss', dir: 'desc' }} columns={columns} />
            ) : (
                <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
                    {(window.PlayTypesList || []).map(type => {
                        const stat = rows.find(r => r.playType === type);
                        return <PlayTypeCard key={type} type={type} current={stat} prev={stat?._prev} onClick={onOpen} side={side} />;
                    })}
                </div>
            )}
        </UI.Section>
    );
};

window.PlaytypeSection = PlaytypeSection;


// ---------- TrackingCardRow.js ----------
// Tracking 卡片群組元件：群組標題（中文 + 小字原文）+ 細線數據表（UI.Ledger / StatCell）
// source: 資料在快照文件中的欄位名（'tracking' | 'shooting' | 'clutch' | 'defense'），供 HistoryModal 取數
// clickable=false（單場面板用）：不可點、無「走勢 →」提示
// actionLabel：右上角動作提示文字（Splits 用「點看趨勢」）
// naReason：整組指標對此球員不適用（跨隊）→ 標題掛 badge，每格顯示灰色「—」
// citeAsOf / citeNote：傳給 StatCell 組引用句（Splits 為期間、單場為場次）
const TrackingCardRow = ({ title, category, metrics, current, prev, onClick, source = 'tracking', clickable = true, naReason = null, actionLabel = '走勢', citeAsOf = 'snap', citeNote }) => {
    if (!current) return null;
    const UI = window.UI;
    const [zh, en] = UI.splitTitle(title);
    return (
        <section onClick={clickable ? () => onClick({ type: 'tracking', id: category, source }) : undefined}
            className={`mb-6 last:mb-0 ${clickable ? 'group cursor-pointer' : ''}`}>
            <header className="flex items-baseline justify-between gap-3 mb-2">
                <h3 className="flex items-baseline gap-2 min-w-0">
                    <span className="text-[13px] font-medium text-slate-100 whitespace-nowrap">{zh}</span>
                    {en && <span className="font-mono text-[10px] text-slate-500 truncate">{en}</span>}
                    {naReason && (
                        <span className="px-1.5 py-0.5 text-[10px] font-normal border border-white/15 text-slate-400 cursor-help whitespace-nowrap"
                            title={naReason}>{window.NA_BADGE}</span>
                    )}
                </h3>
                {clickable && (
                    <span className="shrink-0 font-mono text-[10px] text-slate-500 group-hover:text-[#12A150] transition-colors">{actionLabel} →</span>
                )}
            </header>
            <UI.Ledger cols={UI.ledgerCols(metrics.length)}>
                {metrics.map((m, i) => (
                    <UI.StatCell key={i} label={m.label} en={m.englishLabel}
                        value={current[m.key]} prevValue={prev?.[m.key]}
                        unit={m.unit} betterIsLarger={m.betterIsLarger !== false}
                        naReason={naReason} gkey={m.key} citeAsOf={citeAsOf} citeNote={citeNote} />
                ))}
            </UI.Ledger>
        </section>
    );
};

window.TrackingCardRow = TrackingCardRow;


// ---------- ShotChart.js ----------
// 投籃熱圖元件：讀取 wolves_shotcharts/{playerId}_{season}_{type}，以 SVG 半場圖繪出手點
// 座標系：NBA 官方 shotchartdetail（單位 0.1 呎，籃框在原點），SVG y 軸取負值翻轉
// teamMode=true 時讀 wolves_shotcharts/TEAM_{season}_{type}（全隊出手）
const ShotChart = ({ playerId, playerName, teamMode = false, externalShots, periodLabel }) => {
    const { useState, useEffect } = React;
    const [loadedShots, setLoadedShots] = useState(null);   // null=載入中, []=無資料
    const [filter, setFilter] = useState('all'); // 'all' | 'made' | 'missed'
    const chartRef = React.useRef(null);   // 匯出配圖用；hook 須在下方提早 return 之前
    // externalShots 提供時（ShootingTab 傳入已篩選出手），直接用它、不自行載入
    const useExternal = externalShots !== undefined;
    const shots = useExternal ? externalShots : loadedShots;

    const season = window.CURRENT_SEASON;
    const idPart = teamMode ? 'TEAM' : playerId;
    // 依目前賽季階段選 doc；季後賽讀不到時退回例行賽
    const phase = window.getSeasonPhase ? window.getSeasonPhase() : { type: 'regular' };
    const preferredTypes = phase.type === 'playoffs' ? ['playoffs', 'regular'] : ['regular'];

    useEffect(() => {
        if (useExternal) return; // 外部提供出手，不載入
        if ((!playerId && !teamMode) || !window.db || !window.firebaseModules) return;
        let cancelled = false;
        setLoadedShots(null);
        (async () => {
            const cache = (window.__shotchartCache = window.__shotchartCache || {});
            const { doc: docFn, getDoc } = window.firebaseModules;
            for (const typeKey of preferredTypes) {
                const docId = `${idPart}_${season}_${typeKey}`;
                if (cache[docId] !== undefined) {
                    if (cache[docId] && !cancelled) { setLoadedShots(cache[docId]); return; }
                    continue; // 快取記錄此 doc 不存在，試下一個
                }
                try {
                    const snap = await getDoc(docFn(window.db, 'wolves_shotcharts', docId));
                    cache[docId] = snap.exists() ? (snap.data().shots || []) : null;
                    if (cache[docId] && !cancelled) { setLoadedShots(cache[docId]); return; }
                } catch (e) {
                    console.error('shotchart fetch fail', docId, e);
                }
            }
            if (!cancelled) setLoadedShots([]);
        })();
        return () => { cancelled = true; };
    }, [playerId, season, teamMode, useExternal]);

    if (!playerId && !teamMode) return null;

    const made = shots ? shots.filter(s => s.made === 1).length : 0;
    const total = shots ? shots.length : 0;
    const fgPct = total > 0 ? ((made / total) * 100).toFixed(1) : '-';
    const visible = shots ? shots.filter(s =>
        filter === 'all' || (filter === 'made' ? s.made === 1 : s.made !== 1)
    ) : [];

    // 球場線：淡月光銀，先畫（壓在出手點下面），點才看得清楚
    const lineStyle = { stroke: 'rgba(196, 206, 210, 0.28)', strokeWidth: 2, fill: 'none' };
    const UI = window.UI;
    const MADE = '#12A150', MISS = '#EF4444';

    return (
        <UI.Section title="投籃分布" en="Shot Chart" accent="green"
            sub={`${periodLabel ? periodLabel + ' · ' : ''}實心綠點＝命中，空心紅環＝未中 · 逐球座標每週更新`}
            right={<>
                {total > 0 && <span className="font-mono text-[12px] tabular-nums text-slate-400">{made}/{total}（{fgPct}%）</span>}
                {total > 0 && <UI.ExportMenu title={`投籃分布（${periodLabel || '全季'}，${filter === 'made' ? '只看命中' : filter === 'missed' ? '只看未中' : `${made}/${total}，${fgPct}%`}）`} getNode={() => chartRef.current} />}
                <UI.Seg ariaLabel="顯示出手" size="sm" value={filter} onChange={setFilter}
                    options={[{ value: 'all', label: '全部' }, { value: 'made', label: '命中' }, { value: 'missed', label: '未中' }]} />
            </>}>
            {shots === null && (
                <div className="py-16 text-center text-sm text-slate-500 animate-pulse">載入投籃資料中…</div>
            )}
            {shots !== null && total === 0 && (
                <UI.Note>{playerName} 尚無投籃座標資料（每週更新一次）</UI.Note>
            )}
            {shots !== null && total > 0 && (
                <div ref={chartRef} className="flex flex-col items-center">
                    <svg viewBox="-250 -470 500 522" className="w-full max-w-[520px]" role="img" aria-label={`${playerName} 投籃分布：${made} 命中 / ${total} 出手`}>
                        <rect x="-250" y="-470" width="500" height="517.5" fill="rgba(255, 255, 255, 0.015)" />
                        {/* 球場線（NBA 半場，單位 0.1 呎） */}
                        <rect x="-250" y="-470" width="500" height="517.5" {...lineStyle} />
                        <rect x="-80" y="-142.5" width="160" height="190" {...lineStyle} />
                        <circle cx="0" cy="-142.5" r="60" {...lineStyle} />
                        <path d="M -40 0 A 40 40 0 0 1 40 0" {...lineStyle} />
                        <line x1="-30" y1="12.5" x2="30" y2="12.5" stroke="rgba(196, 206, 210, 0.45)" strokeWidth="3" />
                        <circle cx="0" cy="0" r="7.5" stroke="rgba(196, 206, 210, 0.45)" strokeWidth="2.5" fill="none" />
                        <line x1="-220" y1="47.5" x2="-220" y2="-89.5" {...lineStyle} />
                        <line x1="220" y1="47.5" x2="220" y2="-89.5" {...lineStyle} />
                        <path d="M -220 -89.5 A 237.5 237.5 0 0 1 220 -89.5" {...lineStyle} />
                        {/* 出手點：未中先畫、命中後畫（命中壓在上面）；球隊模式點多，縮小尺寸避免糊成一片 */}
                        {visible.filter(s => s.made !== 1).map((s, i) => (
                            <circle key={'m' + i} cx={s.x} cy={-s.y} r={teamMode ? 2.4 : 4.2} fill="none"
                                stroke={MISS} strokeOpacity={teamMode ? 0.35 : 0.6} strokeWidth={teamMode ? 1 : 1.6} />
                        ))}
                        {visible.filter(s => s.made === 1).map((s, i) => (
                            <circle key={'h' + i} cx={s.x} cy={-s.y} r={teamMode ? 2.4 : 4.2}
                                fill={MADE} fillOpacity={teamMode ? 0.5 : 0.8} />
                        ))}
                    </svg>
                    <div className="mt-3 flex gap-5 text-[12px] text-slate-400">
                        <span className="flex items-center gap-1.5"><svg width="10" height="10" aria-hidden="true"><circle cx="5" cy="5" r="4" fill={MADE} /></svg>命中</span>
                        <span className="flex items-center gap-1.5"><svg width="10" height="10" aria-hidden="true"><circle cx="5" cy="5" r="3.5" fill="none" stroke={MISS} strokeWidth="1.5" /></svg>未中</span>
                    </div>
                </div>
            )}
        </UI.Section>
    );
};

window.ShotChart = ShotChart;


// ---------- DefenseHeatmap.js ----------
// 防守熱圖：半場 5 區依「對手命中率 − 該區聯盟約略均值」上色
// 綠 = 守得比平均好、紅 = 較差（用偏差而非絕對命中率，否則合理衝撞區永遠最紅、失去防守意義）
// 座標系同 ShotChart（0.1 呎，籃框在原點，y 取負向上）
const DefenseHeatmap = ({ defense }) => {
    // 各區聯盟約略均值(對手命中率 %)，供偏差著色的基準；隨賽季略有漂移，可微調
    const ZONE_REF = { RA: 63, PAINT: 42, MID: 41, C3: 39, AB3: 36 };

    // 偏差 → 顏色（+ = 對手投更準 = 守得差 = 紅；− = 守得好 = 綠；±1 內視為約略均值＝銀灰）。
    // 必須是「不透明」的最終色：各區色塊由外而內疊畫，若用半透明，內層會混到外層顏色，
    // 顏色就不再只代表該區本身（例：紅色禁區被綠色外圈混成咖啡色）
    const blend = (hex, a) => {   // 把 hex 以透明度 a 疊在底色 #0A1626 上，回傳不透明 rgb
        const c = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)), bg = [10, 22, 38];
        const m = c.map((v, i) => Math.round(bg[i] + (v - bg[i]) * a));
        return `rgb(${m[0]}, ${m[1]}, ${m[2]})`;
    };
    const devFill = (pct, ref) => {
        if (pct == null) return { fill: '#0A1626' };
        const d = pct - ref;
        if (d <= -3) return { fill: blend('#12A150', 0.6) };   // 明顯優於均值
        if (d <= -1) return { fill: blend('#12A150', 0.28) };  // 略優
        if (d < 1) return { fill: blend('#C4CED2', 0.12) };    // 約略均值
        if (d < 3) return { fill: blend('#EF4444', 0.28) };    // 略差
        return { fill: blend('#EF4444', 0.6) };                 // 明顯差
    };

    const zone = (z) => defense[`${z}_OPP_FG_PCT`];
    const fill = (z) => devFill(zone(z), ZONE_REF[z]);
    const lineStyle = { stroke: 'rgba(196, 206, 210, 0.3)', strokeWidth: 2, fill: 'none' };
    const pctLabel = (z) => (zone(z) == null ? '-' : `${zone(z)}%`);

    // 標籤：對手命中率 + 中文區名（zoneKey 對應 ZONE_REF 的 key）
    const Label = ({ x, y, name, zoneKey }) => (
        <g>
            <text x={x} y={y} textAnchor="middle" fill="#F8FAFC" fontSize="17" fontWeight="600" fontFamily="'Barlow Condensed', sans-serif">{pctLabel(zoneKey)}</text>
            <text x={x} y={y + 15} textAnchor="middle" fill="#C4CED2" fontSize="11">{name}</text>
        </g>
    );

    return (
        <window.UI.Section title="防守熱圖" en="Opponent FG% by Zone" accent="red"
            sub={`數字為對手在各區的命中率；顏色為與聯盟約略均值的偏差（綠＝守得較好、紅＝較差、銀＝±1 以內）。基準為寫死的參考值，非官方即時數字：合理衝撞區 ${ZONE_REF.RA}%、禁區（非 RA）${ZONE_REF.PAINT}%、中距離 ${ZONE_REF.MID}%、底角三分 ${ZONE_REF.C3}%、非底角三分 ${ZONE_REF.AB3}%`}>
            <div className="flex flex-col items-center">
                <svg viewBox="-285 -470 570 522" className="w-full max-w-[560px]" role="img" aria-label="防守熱圖：對手分區命中率">
                    {/* 分區色塊（由外而內疊，內層蓋外層） */}
                    <rect x="-250" y="-470" width="500" height="517.5" {...fill('AB3')} />
                    <path d="M -220 47.5 L -220 -89.5 A 237.5 237.5 0 0 1 220 -89.5 L 220 47.5 Z" {...fill('MID')} />
                    <rect x="-250" y="-89.5" width="30" height="137" {...fill('C3')} />
                    <rect x="220" y="-89.5" width="30" height="137" {...fill('C3')} />
                    <rect x="-80" y="-142.5" width="160" height="190" {...fill('PAINT')} />
                    <path d="M -60 0 A 60 60 0 0 1 60 0 L 60 47.5 L -60 47.5 Z" {...fill('RA')} />

                    {/* 球場線 */}
                    <rect x="-250" y="-470" width="500" height="517.5" {...lineStyle} />
                    <rect x="-80" y="-142.5" width="160" height="190" {...lineStyle} />
                    <circle cx="0" cy="-142.5" r="60" {...lineStyle} />
                    <line x1="-30" y1="12.5" x2="30" y2="12.5" stroke="rgba(196, 206, 210, 0.45)" strokeWidth="3" />
                    <circle cx="0" cy="0" r="7.5" stroke="rgba(196, 206, 210, 0.45)" strokeWidth="2.5" fill="none" />
                    <line x1="-220" y1="47.5" x2="-220" y2="-89.5" {...lineStyle} />
                    <line x1="220" y1="47.5" x2="220" y2="-89.5" {...lineStyle} />
                    <path d="M -220 -89.5 A 237.5 237.5 0 0 1 220 -89.5" {...lineStyle} />

                    {/* 標籤 */}
                    <Label x={0} y={-8} name="合理衝撞區" zoneKey="RA" />
                    <Label x={0} y={-95} name="禁區(非RA)" zoneKey="PAINT" />
                    <Label x={0} y={-215} name="中距離" zoneKey="MID" />
                    <Label x={0} y={-370} name="非底角三分" zoneKey="AB3" />
                    <Label x={-235} y={-15} name="底角" zoneKey="C3" />
                </svg>
            </div>
        </window.UI.Section>
    );
};

window.DefenseHeatmap = DefenseHeatmap;


// ---------- gameAggregates.js ----------
// 單場數據聚合層（pure functions）：把逐場 games 算成季平均 / 每月 / 勝敗 / 主客 / 區間 / 趨勢
// 百分比欄位以「Σ分子 / Σ分母」加權重算，非把每場百分比平均（見 RATIO_DEFS）
// 計數欄位輸出場均（Σ / GP）；無法精確重算的比率/效率值退回逐場平均並在 UI 標註近似
window.GameAgg = (function () {
    // key → [分子欄, 分母欄]，輸出 = 100 * Σ分子 / Σ分母
    const RATIO_DEFS = {
        FG_PCT: ['FGM', 'FGA'], FG3_PCT: ['FG3M', 'FG3A'], FT_PCT: ['FTM', 'FTA'],
        DRIVE_FG_PCT: ['DRIVE_FGM', 'DRIVE_FGA'], DRIVE_TOV_PCT: ['DRIVE_TOV', 'DRIVES'],
        DRIVE_PTS_PCT: ['DRIVE_PTS', 'DRIVES'],   // 每百次切入得分（非百分比；×100 是 NBA 原欄位的尺度）
        CATCH_SHOOT_FG3_PCT: ['CATCH_SHOOT_FG3M', 'CATCH_SHOOT_FG3A'],
        PULL_UP_FG3_PCT: ['PULL_UP_FG3M', 'PULL_UP_FG3A'],
        RA_FG_PCT: ['RA_FGM', 'RA_FGA'], PAINT_FG_PCT: ['PAINT_FGM', 'PAINT_FGA'],
        MID_FG_PCT: ['MID_FGM', 'MID_FGA'], C3_FG_PCT: ['C3_FGM', 'C3_FGA'],
        AB3_FG_PCT: ['AB3_FGM', 'AB3_FGA'],
        D_FG_PCT: ['D_FGM', 'D_FGA'], D_FG3_PCT: ['D_FG3M', 'D_FG3A'],
        REB_COL_PCT: ['REB', 'REB_CHANCES'],
    };
    // eFG 特殊公式：100 * (Σ分子 + 0.5*Σ三分分子) / Σ分母
    const EFG_DEFS = {
        CATCH_SHOOT_EFG_PCT: ['CATCH_SHOOT_FGM', 'CATCH_SHOOT_FG3M', 'CATCH_SHOOT_FGA'],
        PULL_UP_EFG_PCT: ['PULL_UP_FGM', 'PULL_UP_FG3M', 'PULL_UP_FGA'],
    };
    // 無法精確重算 → 退回逐場平均（比率/效率/頻率/距離類）
    const isAvgKey = k => /_PCT$|_FREQ$|_RATING$|PLUSMINUS$|PER_TOUCH$|REB_DIST$|TIME_OF_POSS$|PACE/.test(k);

    const round1 = v => Math.round(v * 10) / 10;

    function entityOf(game, entityKey, viewMode) {
        if (viewMode === 'TEAM') return game.stats || null;
        return (game.players || {})[entityKey] || null;
    }

    // 聚合一組 games 內某實體所有欄位；回傳含 GP / W / L 及各欄位聚合值
    function aggregate(games, entityKey, viewMode) {
        const rows = [];
        let W = 0, L = 0;
        for (const g of games) {
            const e = entityOf(g, entityKey, viewMode);
            if (!e) continue;
            rows.push(e);
            if (g.wl === 'W') W++; else if (g.wl === 'L') L++;
        }
        const GP = rows.length;
        const out = { GP, W, L };
        if (!GP) return out;

        const keys = new Set();
        rows.forEach(r => Object.keys(r).forEach(k => { if (typeof r[k] === 'number') keys.add(k); }));
        // 只要分母資料在，就一定算出該比率欄（即使某場未存 _PCT 本身）
        Object.keys(RATIO_DEFS).forEach(k => { if (keys.has(RATIO_DEFS[k][1])) keys.add(k); });
        Object.keys(EFG_DEFS).forEach(k => { if (keys.has(EFG_DEFS[k][2])) keys.add(k); });
        for (const k of keys) {
            if (k === 'playerId') { out[k] = rows[0][k]; continue; }
            // GP/W/L 由場次計算，勿被單場 base 的 per-game 值（每場 GP=1）覆寫
            if (k === 'GP' || k === 'W' || k === 'L') continue;
            out[k] = valueOf(rows, k);
        }
        return out;
    }

    // 單一欄位的聚合值（aggregate 與 metricOf 共用，確保兩條路徑規則一致）
    function valueOf(rows, k) {
        const sum = key => rows.reduce((a, r) => a + (typeof r[key] === 'number' ? r[key] : 0), 0);
        if (RATIO_DEFS[k]) {
            const d = sum(RATIO_DEFS[k][1]);
            return d ? round1(100 * sum(RATIO_DEFS[k][0]) / d) : 0;
        }
        if (EFG_DEFS[k]) {
            const [fgm, fg3m, fga] = EFG_DEFS[k];
            const d = sum(fga);
            return d ? round1(100 * (sum(fgm) + 0.5 * sum(fg3m)) / d) : 0;
        }
        if (isAvgKey(k)) {
            const vals = rows.filter(r => typeof r[k] === 'number').map(r => r[k]);
            return round1(vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0);
        }
        return round1(sum(k) / rows.length); // 場均
    }

    // 只算一個指標（賽季軌跡疊圖要對每個前 N 場重算，整包 aggregate 會多算上百個欄位）。
    // 這組比賽完全沒有該欄位（或比率的分母）→ null，不當成 0
    function metricOf(games, entityKey, viewMode, k) {
        const rows = [];
        for (const g of games) { const e = entityOf(g, entityKey, viewMode); if (e) rows.push(e); }
        if (!rows.length) return null;
        const need = RATIO_DEFS[k] ? RATIO_DEFS[k][1] : EFG_DEFS[k] ? EFG_DEFS[k][2] : k;
        if (!rows.some(r => typeof r[need] === 'number')) return null;
        return valueOf(rows, k);
    }

    // ── 篩選 / 分組 ──
    const byDate = (a, b) => (a.date < b.date ? -1 : 1);

    function seasonToDate(games, untilDate, entityKey, viewMode) {
        const sub = untilDate ? games.filter(g => g.date <= untilDate) : games;
        return aggregate(sub, entityKey, viewMode);
    }
    function splitByMonth(games) {
        const m = {};
        games.forEach(g => { const k = (g.date || '').slice(0, 7); (m[k] = m[k] || []).push(g); });
        return Object.keys(m).sort().map(k => ({ label: k, games: m[k] }));
    }
    function splitByWinLoss(games) {
        return [
            { label: '勝場', games: games.filter(g => g.wl === 'W') },
            { label: '敗場', games: games.filter(g => g.wl === 'L') },
        ].filter(x => x.games.length);
    }
    function splitByHomeAway(games) {
        return [
            { label: '主場', games: games.filter(g => (g.matchup || '').includes('vs.')) },
            { label: '客場', games: games.filter(g => (g.matchup || '').includes('@')) },
        ].filter(x => x.games.length);
    }
    function lastN(games, n) {
        return games.slice().sort(byDate).slice(-n);
    }
    function byDateRange(games, from, to) {
        return games.filter(g => (!from || g.date >= from) && (!to || g.date <= to));
    }
    // 季後賽以「連續同對手」分系列賽
    function splitBySeries(games) {
        const oppOf = m => (m || '').replace(/^.*?(vs\.|@)\s*/, '');
        const series = [];
        let cur = null;
        games.slice().sort(byDate).forEach(g => {
            const opp = oppOf(g.matchup);
            if (!cur || cur.opp !== opp) { cur = { opp, label: `vs ${opp}`, games: [] }; series.push(cur); }
            cur.games.push(g);
        });
        return series.map(s => ({ label: s.label, games: s.games }));
    }

    // 該週週一（趨勢圖每週分組用）
    function weekKey(dateStr) {
        const d = new Date(dateStr + 'T00:00:00');
        const day = (d.getDay() + 6) % 7; // Mon=0
        d.setDate(d.getDate() - day);
        return d.toISOString().slice(0, 10);
    }

    // 趨勢序列：粒度 game | week | month（season 跨季由 Phase 5 呼叫端組）
    // 每點 = 該組聚合後的 metricKey 值（多場加權平均），回傳 [{label, value, gp}]
    function trendSeries(games, entityKey, viewMode, metricKey, granularity) {
        let groups;
        if (granularity === 'week') {
            const m = {};
            games.forEach(g => { const k = weekKey(g.date); (m[k] = m[k] || []).push(g); });
            groups = Object.keys(m).sort().map(k => ({ label: k, games: m[k] }));
        } else if (granularity === 'month') {
            groups = splitByMonth(games);
        } else { // game：每點多帶 wl（走勢勝負底色）
            groups = games.slice().sort(byDate).map(g => ({ label: g.date, games: [g], wl: g.wl }));
        }
        return groups.map(gr => {
            const agg = aggregate(gr.games, entityKey, viewMode);
            return { label: gr.label, value: agg[metricKey], gp: agg.GP, ...(gr.wl ? { wl: gr.wl } : {}) };
        }).filter(p => typeof p.value === 'number');
    }

    return {
        RATIO_DEFS, EFG_DEFS, aggregate, metricOf, seasonToDate,
        splitByMonth, splitByWinLoss, splitByHomeAway, lastN, byDateRange, splitBySeries,
        trendSeries, weekKey,
    };
})();


// ---------- gamesData.js ----------
// games 資料載入層：讀「逐場打包」bundle（單一 getDoc），避免一次讀 90+ 份文件而卡死。
//   球隊：wolves_games_bundle/{season}_{type}
//   球員：wolves_pgames_bundle/{season}_{type}_{playerId}
// bundle 內每場統一為 { date, matchup, wl, stats }（球隊=球隊當場、球員=該員當場），
// 前端一律以 game.stats 為實體交給 GameAgg 算任意期間。記憶體快取一份。
window.__gamesBundle = window.__gamesBundle || {};

// viewMode='TEAM' 免 playerId；'PLAYER' 需傳 playerId
window.loadSeasonGames = async function (season, type, viewMode, playerId) {
    if (!window.db || !window.firebaseModules) return { games: [] };
    const { doc, getDoc } = window.firebaseModules;
    const isTeam = viewMode === 'TEAM';
    const coll = isTeam ? 'wolves_games_bundle' : 'wolves_pgames_bundle';
    const bundleId = isTeam ? `${season}_${type}` : `${season}_${type}_${playerId}`;
    if (!isTeam && !playerId) return { games: [] };
    const cacheKey = `${coll}/${bundleId}`;
    if (window.__gamesBundle[cacheKey]) return { games: window.__gamesBundle[cacheKey] };
    try {
        const snap = await getDoc(doc(window.db, coll, bundleId));
        const games = snap.exists() ? (snap.data().games || []) : [];
        window.__gamesBundle[cacheKey] = games;
        return { games };
    } catch (e) {
        console.error('bundle load fail', cacheKey, e);
        return { games: [] };
    }
};

// 比賽索引 wolves_games_index/{season}_{type}（一份 doc：[{date,matchup,wl,gameId}]，由舊到新）。
// App 的單場面板日期選單、單場頁賽程條共用。localStorage 快取帶 TTL：賽季中每天會重建索引
window.GAMES_INDEX_TTL = 6 * 3600 * 1000;
window.loadGamesIndex = async function (season, type) {
    if (!window.db || !window.firebaseModules) return [];
    const indexId = `${season}_${type}`;
    const cacheKey = `wt_games_index_v2_${indexId}`;
    try {
        const c = JSON.parse(localStorage.getItem(cacheKey) || 'null');
        if (c && Date.now() - c.t < window.GAMES_INDEX_TTL) return c.games;
    } catch (e) { /* fall through */ }
    const { doc, getDoc } = window.firebaseModules;
    const snap = await getDoc(doc(window.db, 'wolves_games_index', indexId));   // 失敗往上拋，呼叫端決定怎麼顯示
    const games = snap.exists() ? (snap.data().games || []) : [];
    try { localStorage.setItem(cacheKey, JSON.stringify({ t: Date.now(), games })); } catch (e) { /* quota */ }
    return games;
};


// ---------- SingleGamePanel.js ----------
// 單場數據面板：選一場比賽，看該場的 Tracking / 投籃 / 防守單場數值
// 資料來源 wolves_player_games/{date} 與 wolves_team_games/{date}（backfill_games.py / 每日順抓）
// 單場只有部分欄位（tracking + 最近防守者 + Hustle + 分區投籃），故只渲染「有資料」的卡片群組
const SingleGamePanel = ({ viewMode, playerName, viewSide, gamesIndex }) => {
    const { useState, useEffect } = React;
    const trackingDefs = window.trackingDefs || [];
    const shootingDefs = window.shootingDefs || [];
    const defenseDefs = window.defenseDefs || [];
    const TrackingCardRow = window.TrackingCardRow;

    const dates = (gamesIndex || []).map(g => g.date);
    const [selectedDate, setSelectedDate] = useState(dates.length ? dates[dates.length - 1] : '');
    const [doc, setDoc] = useState(undefined); // undefined=載入中, null=無, obj=資料

    // 賽別切換後索引換一份：原選的日期不在新清單裡 → 跳到新清單最後一場
    const lastDate = dates.length ? dates[dates.length - 1] : '';
    useEffect(() => {
        if (!dates.includes(selectedDate)) setSelectedDate(lastDate);
    }, [lastDate, dates.length]);

    const coll = viewMode === 'TEAM' ? 'wolves_team_games' : 'wolves_player_games';

    useEffect(() => {
        if (!selectedDate || !window.db || !window.firebaseModules) return;
        let cancelled = false;
        setDoc(undefined);
        const cacheKey = `wt_game_${coll}_${selectedDate}`;
        const cached = localStorage.getItem(cacheKey);
        if (cached) {
            try { setDoc(JSON.parse(cached)); return; } catch (e) { /* fall through */ }
        }
        (async () => {
            const { doc: docFn, getDoc } = window.firebaseModules;
            try {
                const snap = await getDoc(docFn(window.db, coll, selectedDate));
                const data = snap.exists() ? snap.data() : null;
                if (data) localStorage.setItem(cacheKey, JSON.stringify(data));
                if (!cancelled) setDoc(data);
            } catch (e) {
                console.error('single game fetch fail', coll, selectedDate, e);
                if (!cancelled) setDoc(null);
            }
        })();
        return () => { cancelled = true; };
    }, [selectedDate, coll]);

    if (!dates.length) return null;

    // 取當前實體（球員 / 球隊）的單場數值
    const entity = doc == null ? null
        : viewMode === 'TEAM' ? (doc.stats || {})
        : (doc.players || {})[playerName] || {};
    const meta = gamesIndex.find(g => g.date === selectedDate) || {};

    // 依攻守選 defs，只保留「該實體有資料」的群組
    const groups = (viewSide === 'offensive' ? [...trackingDefs, ...shootingDefs] : defenseDefs)
        .filter(def => entity && def.metrics.some(m => entity[m.key] !== undefined));

    return (
        <window.UI.Section title="單場數據" en="Single Game" accent="blue"
            sub="單場僅含 Tracking／最近防守者／Hustle／分區投籃（PlayType 無單場資料）"
            right={<>
                {meta.wl && <span className={`px-2 py-0.5 font-mono text-[11px] ${meta.wl === 'W' ? 'bg-[#12A150]/[0.08] text-[#12A150]' : 'bg-[#EF4444]/[0.08] text-[#EF4444]'}`}>{meta.matchup} {meta.wl}</span>}
                <label className="sr-only" htmlFor="single-game-date">選擇比賽</label>
                <select id="single-game-date" value={selectedDate} onChange={e => setSelectedDate(e.target.value)}
                    className="rounded-full border border-white/15 bg-[#0A1626] px-3 py-1 text-xs text-slate-200 focus:outline-none focus:border-[#12A150]">
                    {gamesIndex.slice().reverse().map(g => (
                        <option key={g.date} value={g.date}>{g.date} {g.matchup} {g.wl}</option>
                    ))}
                </select>
                {selectedDate && window.UrlState && (
                    <a href={window.UrlState.gameHref(selectedDate, viewMode === 'PLAYER' ? playerName : '')}
                        className="inline-flex min-h-[24px] items-center rounded-full border border-[#12A150]/50 px-3 py-1 text-xs text-[#12A150] hover:bg-[#12A150]/10">
                        看完整比賽 →
                    </a>
                )}
            </>}>
            {doc === undefined && <div className="py-6 text-center text-sm text-slate-500 animate-pulse">載入單場資料中…</div>}
            {doc !== undefined && groups.length === 0 && (
                <div className="py-6 text-center text-sm text-slate-500">
                    {viewMode === 'PLAYER' ? `${playerName} 該場無${viewSide === 'offensive' ? '進攻' : '防守'}單場資料` : '該場無此側單場資料'}
                </div>
            )}
            {groups.map(def => (
                <TrackingCardRow
                    key={def.id} title={def.title} category={def.id}
                    metrics={def.metrics} current={entity} prev={null}
                    clickable={false}
                    citeAsOf="none" citeNote={`單場 ${selectedDate}${meta.matchup ? ` ${meta.matchup}` : ''}${meta.wl ? ` ${meta.wl}` : ''}`}
                />
            ))}
        </window.UI.Section>
    );
};

window.SingleGamePanel = SingleGamePanel;


// ---------- GamePage.js ----------
// 單場比賽頁（Game Center）：網址 #game=YYYY-MM-DD[&p=球員]
// 資料：wolves_team_games/{date}（box/stats/opp）＋ wolves_player_games/{date}（players/oppPlayers）
//   季平均：該員逐場 bundle 取「此場之前」的比賽（GameAgg）；投籃點：wolves_shotcharts 以 gdate 篩（每週更新）
// 灰狼球員一律用 box score 的 personId 對應 players 文件的 playerId（名字寫法兩邊可能不同，且早期文件含非當時隊員）
// 舊場次沒有 box（2026-10 以前、未回補者）→ 比分看板／Box Score／焦點／Four Factors 降級隱藏
// props：date、gamePlayer（展開的球員名，網址 p=）、onExpand(name|'')
const GamePage = ({ date, gamePlayer, onExpand }) => {
    const { useState, useEffect, useMemo } = React;
    const UI = window.UI;
    const GA = window.GameAgg;

    const [docs, setDocs] = useState(undefined);      // undefined=載入中, null=查無, {team, player}
    const [loadErr, setLoadErr] = useState(null);
    const [index, setIndex] = useState([]);
    const [boxSide, setBoxSide] = useState('MIN');
    const [avgCache, setAvgCache] = useState({});     // {playerId: aggregate|null}（null=無 bundle）
    const [vsWho, setVsWho] = useState(null);
    const [shotWho, setShotWho] = useState('TEAM');
    const [shots, setShots] = useState(undefined);    // undefined=載入中, null=無文件, []=該場無點位
    const boxRef = React.useRef(null);
    const avgInflight = React.useRef({});
    const dateRef = React.useRef(date);
    dateRef.current = date;

    // ── 載入單場兩份文件（記憶體＋localStorage；未定稿 final=false 不寫 localStorage，免得鎖住半成品）──
    useEffect(() => {
        if (!window.db || !window.firebaseModules) return;
        let cancelled = false;
        setDocs(undefined); setLoadErr(null); setBoxSide('MIN'); setShots(undefined);
        setAvgCache({}); avgInflight.current = {};   // 季平均是「這場之前」，換場次要重算
        const mem = (window.__gameDocCache = window.__gameDocCache || {});
        (async () => {
            if (mem[date]) { setDocs(mem[date]); return; }
            const lsKey = `wt_gc_${date}`;
            try { const c = JSON.parse(localStorage.getItem(lsKey) || 'null'); if (c) { mem[date] = c; if (!cancelled) setDocs(c); return; } } catch (e) { /* ignore */ }
            const { doc, getDoc } = window.firebaseModules;
            try {
                const [t, p] = await Promise.all([
                    getDoc(doc(window.db, 'wolves_team_games', date)),
                    getDoc(doc(window.db, 'wolves_player_games', date)),
                ]);
                const v = (t.exists() || p.exists()) ? { team: t.exists() ? t.data() : null, player: p.exists() ? p.data() : null } : null;
                if (v) {
                    mem[date] = v;
                    const final = (v.team || v.player || {}).final !== false;
                    if (final) { try { localStorage.setItem(lsKey, JSON.stringify(v)); } catch (e) { /* quota */ } }
                }
                if (!cancelled) setDocs(v);
            } catch (e) {
                console.error('game page fetch fail', date, e);
                if (!cancelled) { setLoadErr(String(e.code || e.message || e)); setDocs(null); }
            }
        })();
        return () => { cancelled = true; };
    }, [date]);

    const meta = (docs && (docs.team || docs.player)) || {};
    const typeKey = meta.seasonType === '季後賽' ? 'playoffs' : 'regular';
    const season = window.seasonForDate(new Date(date + 'T12:00:00Z'));
    const box = docs && docs.team && docs.team.box && (docs.team.box.teams || []).length === 2 ? docs.team.box : null;

    // 賽程條：同季同賽別的比賽索引
    useEffect(() => {
        if (!docs || !window.loadGamesIndex) return;
        let cancelled = false;
        window.loadGamesIndex(season, typeKey).then(g => { if (!cancelled) setIndex(g); }).catch(e => console.error('game index fail', e));
        return () => { cancelled = true; };
    }, [season, typeKey, !!docs]);

    // ── 灰狼球員：box 名單（personId）× players 文件（playerId）──
    const playersDoc = (docs && docs.player && docs.player.players) || {};
    const byPid = useMemo(() => {
        const m = {};
        Object.entries(playersDoc).forEach(([name, d]) => { if (d && d.playerId) m[d.playerId] = { name, stats: d }; });
        return m;
    }, [docs]);
    const minBox = box ? box.players.filter(p => p.tricode === 'MIN') : [];
    const oppTeam = box ? box.teams.find(t => t.tricode !== 'MIN') : null;
    const minTeam = box ? box.teams.find(t => t.tricode === 'MIN') : null;
    const oppAbbr = (oppTeam && oppTeam.tricode) || meta.oppAbbr || String(meta.matchup || '').replace(/^.*?(vs\.|@)\s*/, '');
    // 灰狼上場球員清單：[{pid, name(數據 API 寫法，連結用), boxName, stats(單場進階)}]
    const minPlayers = box
        ? minBox.filter(p => p.stats && Object.keys(p.stats).length).map(p => ({ pid: p.personId, name: (byPid[p.personId] || {}).name || p.name, boxName: p.name, adv: (byPid[p.personId] || {}).stats || null, box: p }))
        : Object.entries(playersDoc).map(([name, d]) => ({ pid: d.playerId, name, boxName: name, adv: d, box: null }));

    // 季平均（此場之前）：lazily 讀該員 bundle
    const ensureAvg = (pid) => {
        if (!pid || avgCache[pid] !== undefined || avgInflight.current[`${season}_${typeKey}_${pid}`] || !window.loadSeasonGames) return;
        avgInflight.current[`${season}_${typeKey}_${pid}`] = true;   // 同一人只讀一次（多個區塊會同時要）
        const forDate = date;
        window.loadSeasonGames(season, typeKey, 'PLAYER', pid).then(({ games }) => {
            if (dateRef.current !== forDate) return;   // 已換到別場，丟掉舊結果
            const prior = (games || []).filter(g => g.date < date);
            setAvgCache(c => ({ ...c, [pid]: prior.length ? GA.aggregate(prior, null, 'TEAM') : null }));
        });
    };
    const expanded = minPlayers.find(p => p.name === gamePlayer || p.boxName === gamePlayer) || null;
    const vsPlayer = minPlayers.find(p => p.name === vsWho) || expanded
        || minPlayers.slice().sort((a, b) => ((b.box && b.box.stats.PTS) || (b.adv && b.adv.PTS) || 0) - ((a.box && a.box.stats.PTS) || (a.adv && a.adv.PTS) || 0))[0] || null;
    useEffect(() => { if (expanded) ensureAvg(expanded.pid); }, [expanded && expanded.pid, season, typeKey]);
    useEffect(() => { if (vsPlayer) ensureAvg(vsPlayer.pid); }, [vsPlayer && vsPlayer.pid, season, typeKey]);
    useEffect(() => { if (shotWho !== 'TEAM') ensureAvg(Number(shotWho)); }, [shotWho, season, typeKey]);

    // ── 投籃點：wolves_shotcharts/{TEAM|pid}_{season}_{type}，以 gdate 篩這場 ──
    useEffect(() => {
        if (!docs || !window.db) return;
        let cancelled = false;
        setShots(undefined);
        (async () => {
            const cache = (window.__shootTabCache = window.__shootTabCache || {});
            const docId = `${shotWho}_${season}_${typeKey}`;
            let v = cache[docId];
            if (v === undefined) {
                const { doc, getDoc } = window.firebaseModules;
                try {
                    const snap = await getDoc(doc(window.db, 'wolves_shotcharts', docId));
                    if (snap.exists()) {
                        const d = snap.data(), at = d.actionTypes || [], gd = d.gameDates || [];
                        v = { shots: (d.shots || []).map(s => ({ x: s.x, y: s.y, made: s.made, dist: s.dist, zone: s.zone, action: at[s.a], gdate: gd[s.g] })), assisted: d.assisted || {} };
                    } else v = null;
                    cache[docId] = v;
                } catch (e) { console.error('game shots fail', docId, e); v = null; }
            }
            if (!cancelled) setShots(v ? v.shots.filter(s => s.gdate === date) : null);
        })();
        return () => { cancelled = true; };
    }, [shotWho, season, typeKey, date, !!docs]);

    // ── 指標中繼資料（名稱／原文／方向／中性）一律取 constants.js defs ──
    const ALL_DEFS = [window.SPLITS_BASE_DEF, ...(window.trackingDefs || []), ...(window.shootingDefs || []), ...(window.defenseDefs || [])].filter(Boolean);
    const metaOf = (k) => { for (const d of ALL_DEFS) { const m = d.metrics.find(x => x.key === k); if (m) return m; } return { key: k, label: k }; };
    // 比率類的分母（判斷樣本少、顯示 命中/出手）
    const RATIO = { ...GA.RATIO_DEFS, ...Object.fromEntries(Object.entries(GA.EFG_DEFS).map(([k, [fgm, , fga]]) => [k, [fgm, fga]])), PCT_PLUSMINUS: [null, 'D_FGA'], D_FG3_PLUSMINUS: [null, 'D_FG3A'] };
    const MIN_N = 5;
    const fmtV = (k, v) => {
        if (typeof v !== 'number') return '—';
        const m = metaOf(k);
        const s = m.unit === '%' || /_PCT$|PLUSMINUS$/.test(k) ? v.toFixed(1) : (Number.isInteger(v) ? String(v) : v.toFixed(1));
        return (k === 'PCT_PLUSMINUS' && v > 0 ? '+' : '') + s + (m.unit === '%' ? '%' : '');
    };
    // 本場 vs 季平均：中性→不判；樣本少→不判；否則依 betterIsLarger
    const judge = (k, v, avg, ent) => {
        const m = metaOf(k);
        const r = RATIO[k], den = r && ent ? ent[r[1]] : null;
        const small = r && typeof den === 'number' && den < MIN_N;
        if (m.neutral || small || typeof v !== 'number' || typeof avg !== 'number' || Math.abs(v - avg) < 1e-9) return { good: false, bad: false, small };
        const better = (v > avg) === (m.betterIsLarger !== false);
        return { good: better, bad: !better, small };
    };
    const fracOf = (k, ent) => { const r = RATIO[k]; if (!r || !r[0] || !ent || typeof ent[r[1]] !== 'number') return null; return `${ent[r[0]]}/${ent[r[1]]}`; };

    // 連結：球員頁／Splits 指標走勢（帶 hl 圈出這場）
    const seasonState = season === window.CURRENT_SEASON ? { selectedSeasonKey: 'current', seasonTypeView: typeKey } : { selectedSeasonKey: `${season}_${typeKey}` };
    const playerHref = (name) => '#' + window.UrlState.serialize({ viewMode: 'PLAYER', selectedPlayer: name, activeTab: 'overview', ...seasonState });
    const metricHref = (name, k) => '#' + window.UrlState.serialize({ viewMode: 'PLAYER', selectedPlayer: name, activeTab: 'splits', ...seasonState, focusMetric: k, highlightDate: date });

    // 複製引用情境（StatCell／citeLine 讀）
    window.CiteCtx = { subject: expanded ? expanded.name : 'Minnesota Timberwolves', season: `${season} ${meta.seasonType || ''}`.trim(), asOfSnap: null, asOfAgg: null, isHistory: false };

    if (docs === undefined) return <div className="py-16 text-center text-sm text-slate-500 animate-pulse">載入比賽資料中…</div>;
    if (docs === null) return (
        <UI.Note tone="warn">{loadErr ? `比賽資料讀取失敗：${loadErr}` : `找不到 ${date} 的比賽資料（灰狼當天可能沒有比賽，或這場尚未抓取）`}</UI.Note>
    );

    const final = meta.final !== false;
    const wl = meta.wl;
    const linkCls = 'border-b border-transparent hover:border-[#12A150] hover:text-white transition-colors';

    // ── 賽程條 ──
    const idxPos = index.findIndex(g => g.date === date);
    const prevG = idxPos > 0 ? index[idxPos - 1] : null, nextG = idxPos >= 0 && idxPos < index.length - 1 ? index[idxPos + 1] : null;
    const strip = (
        <nav aria-label="賽程" className="flex items-stretch gap-1.5 border-b border-white/10 pb-3">
            <a href={prevG ? window.UrlState.gameHref(prevG.date) : undefined} aria-label="上一場" aria-disabled={!prevG}
                className={`flex w-8 shrink-0 items-center justify-center rounded border border-white/15 text-slate-400 ${prevG ? 'hover:border-white/40 hover:text-slate-100' : 'opacity-30 pointer-events-none'}`}>‹</a>
            <div className="flex flex-1 gap-1.5 overflow-x-auto [scrollbar-width:none]" ref={el => { if (el) { const on = el.querySelector('[aria-current="page"]'); if (on) el.scrollLeft = on.offsetLeft - el.clientWidth / 2 + on.clientWidth / 2; } }}>
                {index.map(g => (
                    <a key={g.date} href={window.UrlState.gameHref(g.date)} aria-current={g.date === date ? 'page' : undefined}
                        className={`w-[104px] shrink-0 rounded border px-2.5 py-1.5 text-[11px] ${g.date === date ? 'border-[#12A150] bg-[#12A150]/10 text-slate-50' : 'border-white/10 text-slate-400 hover:border-white/25 hover:text-slate-100'}`}>
                        <div className="font-mono text-[10px]">{g.date.slice(5)}</div>
                        <div className="font-medium text-slate-100">{String(g.matchup || '').replace(/^MIN\s*/, '')}</div>
                        <div className={`font-mono ${g.wl === 'W' ? 'text-[#12A150]' : 'text-[#EF4444]'}`}>{g.wl}</div>
                    </a>
                ))}
            </div>
            <a href={nextG ? window.UrlState.gameHref(nextG.date) : undefined} aria-label="下一場" aria-disabled={!nextG}
                className={`flex w-8 shrink-0 items-center justify-center rounded border border-white/15 text-slate-400 ${nextG ? 'hover:border-white/40 hover:text-slate-100' : 'opacity-30 pointer-events-none'}`}>›</a>
        </nav>
    );

    // ── 比分看板 ──
    const logo = (id) => `https://cdn.nba.com/logos/nba/${id}/primary/L/logo.svg`;
    const away = box && box.teams.find(t => !t.home), home = box && box.teams.find(t => t.home);
    const teamBlock = (t, side) => {
        const lose = t.score < (side === 'away' ? home.score : away.score);
        const score = <div className={`font-display text-[56px] sm:text-[80px] font-bold leading-none tabular-nums ${lose ? 'text-slate-50/40' : 'text-slate-50'}`}>{t.score}</div>;
        return (
            <div className={`flex items-center gap-3 sm:gap-4 ${side === 'home' ? 'flex-row-reverse text-right' : ''}`}>
                <img src={logo(t.teamId)} alt="" className="h-12 w-12 sm:h-20 sm:w-20 shrink-0" />
                <div className="min-w-0">
                    <div className="font-display text-[30px] sm:text-[40px] font-bold leading-none">{t.tricode}</div>
                    <div className="truncate text-[12px] text-slate-400">{t.name}</div>
                    <div className="font-mono text-[11px] text-slate-500">{side === 'home' ? '主' : '客'}</div>
                </div>
                <div className={side === 'home' ? 'mr-auto' : 'ml-auto'}>{score}</div>
            </div>
        );
    };
    const periodLabel = (p, i) => p.type === 'OVERTIME' || i >= 4 ? `OT${i - 3 > 1 ? i - 3 : ''}` : `Q${i + 1}`;
    const margin = box ? minTeam.score - oppTeam.score : null;
    const board = box ? (
        <div className="grid grid-cols-2 gap-4 border-b border-white/10 py-6 lg:grid-cols-[1fr_auto_1fr] lg:items-center lg:gap-6">
            <div className="order-2 lg:order-1">{teamBlock(away, 'away')}</div>
            <div className="order-1 col-span-2 text-center lg:order-2 lg:col-span-1">
                <span className="inline-block bg-[#C4CED2] px-2 py-0.5 font-mono text-[10px] font-semibold tracking-[0.14em] text-[#0A1626]">FINAL</span>
                {!final && <span className="ml-2 inline-block border border-amber-500/40 px-2 py-0.5 text-[10px] text-amber-300">數據可能更新</span>}
                <div className="mt-2 text-[13px] text-slate-200">{date}</div>
                {box.arena && <div className="text-[11px] text-slate-400">{box.arena}{box.attendance ? ` · ${box.attendance.toLocaleString()} 人` : ''}</div>}
                <div className={`mt-1.5 font-mono text-[11px] ${margin > 0 ? 'text-[#12A150]' : 'text-[#EF4444]'}`}>灰狼{margin > 0 ? '勝' : '敗'} {margin > 0 ? '+' : ''}{margin}</div>
                {away.periods.length > 0 && (
                    <table className="mx-auto mt-3 border-collapse font-mono text-[12px]" aria-label="每節比分">
                        <thead><tr>
                            <th className="px-2"></th>
                            {away.periods.map((p, i) => <th key={i} className="px-2 py-1 text-[10px] font-normal text-slate-500">{periodLabel(p, i)}</th>)}
                            <th className="border-l border-white/15 px-2 text-[10px] font-normal text-slate-500">T</th>
                        </tr></thead>
                        <tbody>{[away, home].map(t => {
                            const other = t === away ? home : away;
                            return (
                                <tr key={t.tricode} className="border-t border-white/10">
                                    <td className="px-2 py-1 text-left font-display text-[14px] font-bold">{t.tricode}</td>
                                    {t.periods.map((p, i) => <td key={i} className={`px-2 py-1 tabular-nums ${p.pts > ((other.periods[i] || {}).pts || 0) ? 'text-[#12A150]' : 'text-slate-300'}`}>{p.pts}</td>)}
                                    <td className="border-l border-white/15 px-2 py-1 font-semibold text-slate-50 tabular-nums">{t.score}</td>
                                </tr>
                            );
                        })}</tbody>
                    </table>
                )}
            </div>
            <div className="order-3">{teamBlock(home, 'home')}</div>
        </div>
    ) : (
        <div className="border-b border-white/10 py-6">
            <div className="font-display text-[34px] font-bold">{meta.matchup} <span className={wl === 'W' ? 'text-[#12A150]' : 'text-[#EF4444]'}>{wl}</span></div>
            <div className="text-[13px] text-slate-400">{date}{docs.team && docs.team.stats && typeof docs.team.stats.PTS === 'number' ? ` · 灰狼 ${docs.team.stats.PTS} 分` : ''}</div>
            <div className="mt-3"><UI.Note>這場沒有 box score（2026-10 起才每場抓取；更早只回補了 2025-26），所以沒有比分看板、Box Score 與 Four Factors。下方灰狼的單場進階數據照常顯示。</UI.Note></div>
        </div>
    );

    // ── 焦點：兩隊各項最高 ＋ Four Factors ──
    const played = (tri) => box.players.filter(p => p.tricode === tri && p.stats && Object.keys(p.stats).length);
    const leaderOf = (tri, k) => played(tri).reduce((a, b) => (b.stats[k] > (a ? a.stats[k] : -1) ? b : a), null);
    const headshot = (id) => `https://cdn.nba.com/headshots/nba/latest/260x190/${id}.png`;
    const ff = (t, o) => ({
        efg: (t.FGM + 0.5 * t.FG3M) / t.FGA * 100,
        tov: t.TOV / (t.FGA + 0.44 * t.FTA + t.TOV) * 100,
        orb: t.OREB / (t.OREB + o.DREB) * 100,
        ftr: t.FTM / t.FGA * 100,
    });
    const leaders = box && (
        <UI.Section title="本場焦點" en="Game Leaders" accent="green" sub="兩隊各項最高；Four Factors 由兩隊合計計算（有效命中率、失誤率、進攻籃板率、罰球率）">
            <div className="grid grid-cols-1 border-l border-t border-white/[0.08] sm:grid-cols-3">
                {[['PTS', '得分'], ['REB', '籃板'], ['AST', '助攻']].map(([k, zh]) => (
                    <div key={k} className="border-b border-r border-white/[0.08] px-3 py-2.5">
                        <div className="mb-1 font-mono text-[10px] tracking-[0.14em] text-slate-500">{zh} {k}</div>
                        {['MIN', oppAbbr].map(tri => {
                            const p = leaderOf(tri, k); if (!p) return null;
                            const mine = tri === 'MIN';
                            const pName = mine ? ((byPid[p.personId] || {}).name || p.name) : p.name;
                            return (
                                <div key={tri} className="flex items-center gap-2.5 border-t border-white/[0.06] py-1.5 first:border-t-0">
                                    <img src={headshot(p.personId)} alt="" loading="lazy" className="h-8 w-11 shrink-0 rounded bg-white/[0.04] object-cover object-top" onError={e => { e.currentTarget.style.visibility = 'hidden'; }} />
                                    <div className="min-w-0 flex-1 text-[13px]">
                                        {mine ? <a href={playerHref(pName)} className={linkCls}>{p.name}</a> : <span title="對手球員沒有個人頁（只抓灰狼的季資料）">{p.name}</span>}
                                        <div className="font-mono text-[10px] text-slate-500">{tri} · {p.stats.PTS}分 {p.stats.REB}板 {p.stats.AST}助</div>
                                    </div>
                                    <div className={`font-display text-[28px] font-bold leading-none ${mine ? 'text-[#12A150]' : 'text-slate-100'}`}>{p.stats[k]}</div>
                                </div>
                            );
                        })}
                    </div>
                ))}
            </div>
            {(() => {
                const a = ff(minTeam.totals, oppTeam.totals), b = ff(oppTeam.totals, minTeam.totals);
                return (
                    <div className="mt-4 grid grid-cols-2 border-l border-t border-white/[0.08] sm:grid-cols-4">
                        {[['efg', '有效命中率', 'eFG%', false], ['tov', '失誤率', 'TOV%', true], ['orb', '進攻籃板率', 'OREB%', false], ['ftr', '罰球率', 'FTM/FGA', false]].map(([k, zh, en, low]) => {
                            const mWin = low ? a[k] < b[k] : a[k] > b[k];
                            return (
                                <div key={k} className="border-b border-r border-white/[0.08] px-3 py-2.5">
                                    <div className="text-[11px] text-slate-300">{zh}<span className="ml-1.5 font-mono text-[10px] text-slate-500">{en}</span></div>
                                    <div className="mt-1 flex items-baseline justify-between font-display text-[24px] font-semibold tabular-nums">
                                        <span className={mWin ? 'text-[#12A150]' : 'text-slate-200'}>{a[k].toFixed(1)}</span>
                                        <span className={!mWin ? 'text-slate-100' : 'text-slate-500'}>{b[k].toFixed(1)}</span>
                                    </div>
                                    <div className="mt-1.5 flex h-1 gap-0.5"><i className="block bg-[#12A150]" style={{ flex: a[k] }}></i><i className="block bg-[#C4CED2]/40" style={{ flex: b[k] }}></i></div>
                                    <div className="mt-1 flex justify-between font-mono text-[10px] text-slate-500"><span>MIN</span><span>{oppAbbr}</span></div>
                                </div>
                            );
                        })}
                    </div>
                );
            })()}
        </UI.Section>
    );

    // ── 展開列：該員單場進階（Tracking／最近防守者／Hustle）vs 季平均 ──
    const EXP_GROUPS = [...(window.trackingDefs || []).filter(d => ['Touches', 'Drives', 'CatchShoot', 'PullUpShot', 'Passing', 'Rebounding'].includes(d.id)),
        ...(window.defenseDefs || []).filter(d => d.id === 'MatchupDefense' || d.id === 'Hustle')];
    const metricRow = (name, k, v, avg, ent, link = true) => {
        const m = metaOf(k), j = judge(k, v, avg, ent), frac = fracOf(k, ent);
        return (
            <div key={k} title={((window.GLOSSARY || {})[k] || {}).def || undefined}
                className={`-mx-1.5 flex items-baseline justify-between gap-2 border-b border-dotted border-white/10 px-1.5 py-1 text-[12px] ${j.good ? 'bg-[#12A150]/10 shadow-[inset_2px_0_0_#12A150]' : ''}`}>
                <span className="min-w-0">
                    {link ? <a href={metricHref(name, k)} className={`text-slate-200 ${linkCls}`}>{m.label}</a> : <span className="text-slate-200">{m.label}</span>}
                    {m.englishLabel && <span className="block font-mono text-[9px] text-slate-500">{m.englishLabel}</span>}
                </span>
                <span className="shrink-0 text-right">
                    <b className={`font-mono font-semibold ${j.good ? 'text-[#12A150]' : 'text-slate-100'}`}>{fmtV(k, v)}</b>
                    {frac && <span className="ml-1 font-mono text-[10px] text-slate-500">{frac}</span>}
                    {j.small && <span className="ml-1 text-[10px] text-amber-300/80">樣本少</span>}
                    <span className="block font-mono text-[10px] text-slate-500">季均 {avg === undefined ? '…' : fmtV(k, avg)}</span>
                </span>
            </div>
        );
    };
    const expandRow = (p) => {
        const ent = p.adv;
        const avgAgg = avgCache[p.pid];
        if (!ent) return <UI.Note>這位球員本場沒有進階數據</UI.Note>;
        const groups = EXP_GROUPS.map(d => ({ d, ms: d.metrics.filter(m => typeof ent[m.key] === 'number') })).filter(g => g.ms.length);
        return (
            <div className="px-3 pb-3 pt-2 sm:pl-10">
                <div className="grid grid-cols-1 gap-x-5 gap-y-3 sm:grid-cols-2 lg:grid-cols-4">
                    {groups.map(({ d, ms }) => (
                        <div key={d.id}>
                            <h4 className="mb-1 font-mono text-[10px] tracking-[0.1em] text-slate-500">{d.title}</h4>
                            {ms.map(m => metricRow(p.name, m.key, ent[m.key], avgAgg === undefined ? undefined : (avgAgg ? avgAgg[m.key] : null), ent))}
                        </div>
                    ))}
                </div>
                <p className="mt-2 flex flex-wrap items-center gap-x-2 text-[11px] text-slate-500">
                    <span className="inline-block h-3 w-3 bg-[#12A150]/25 shadow-[inset_2px_0_0_#12A150]" aria-hidden="true"></span>
                    優於賽前季平均（失誤率、對手命中率越低越好；觸球、切入次數等次數類不標色）· 比率類出手少於 {MIN_N} 次標「樣本少」· 點指標名稱看逐場走勢 · 滑過看定義
                    {avgAgg === null && <span className="text-amber-300/80">（本季沒有更早的逐場資料，無季平均）</span>}
                </p>
            </div>
        );
    };

    // ── Box Score ──
    const BOX_COLS = [['MIN', 'MIN'], ['PTS', 'PTS'], ['FG', 'FG'], ['FG_PCT', 'FG%'], ['3P', '3P'], ['FG3_PCT', '3P%'], ['FT', 'FT'], ['OREB', 'OREB'], ['DREB', 'DREB'], ['REB', 'REB'], ['AST', 'AST'], ['STL', 'STL'], ['BLK', 'BLK'], ['TOV', 'TOV'], ['PF', 'PF'], ['PLUS_MINUS', '+/-']];
    const TOP_KEYS = ['PTS', 'REB', 'AST', 'STL', 'BLK'];
    const sideTri = boxSide === 'MIN' ? 'MIN' : oppAbbr;
    const sidePlayers = box ? box.players.filter(p => p.tricode === sideTri) : [];
    const sideTeam = box ? box.teams.find(t => t.tricode === sideTri) : null;
    const activeP = sidePlayers.filter(p => p.stats && Object.keys(p.stats).length);
    const topOf = (k) => Math.max(0, ...activeP.map(p => p.stats[k] || 0));
    const cell = (s, k) => {
        if (k === 'FG') return `${s.FGM}-${s.FGA}`;
        if (k === '3P') return `${s.FG3M}-${s.FG3A}`;
        if (k === 'FT') return `${s.FTM}-${s.FTA}`;
        if (k === 'FG_PCT') return s.FGA ? s.FG_PCT.toFixed(1) : '—';
        if (k === 'FG3_PCT') return s.FG3A ? s.FG3_PCT.toFixed(1) : '—';
        if (k === 'PLUS_MINUS') return s.PLUS_MINUS > 0 ? `+${s.PLUS_MINUS}` : String(s.PLUS_MINUS);
        return s[k] == null ? '' : String(s[k]);
    };
    const tdCls = (s, k) => {
        if (k === 'PLUS_MINUS') return s.PLUS_MINUS > 0 ? 'text-[#12A150]' : s.PLUS_MINUS < 0 ? 'text-[#EF4444]' : '';
        if (k === 'PTS') return TOP_KEYS.includes(k) && s[k] > 0 && s[k] === topOf(k) ? 'font-semibold text-[#12A150]' : 'font-semibold text-slate-50';
        return TOP_KEYS.includes(k) && s[k] > 0 && s[k] === topOf(k) ? 'font-semibold text-[#12A150]' : '';
    };
    const boxRow = (p) => {
        const mine = sideTri === 'MIN';
        const mp = mine ? minPlayers.find(x => x.pid === p.personId) : null;
        const open = mine && mp && expanded && expanded.pid === p.personId;
        const dnp = !p.stats || !Object.keys(p.stats).length;
        const toggle = () => { if (mine && mp) onExpand(open ? '' : mp.name); };
        const nameEl = mine && mp
            ? <a href={playerHref(mp.name)} onClick={e => e.stopPropagation()} className={linkCls}>{p.name}</a>
            : <span title={mine ? undefined : '對手球員沒有個人頁（只抓灰狼的季資料）'}>{p.name}</span>;
        return (
            <React.Fragment key={p.personId}>
                <tr onClick={dnp ? undefined : toggle} className={`border-b border-white/[0.05] ${mine && mp && !dnp ? 'cursor-pointer hover:bg-white/[0.03]' : ''} ${open ? 'bg-[#12A150]/[0.07]' : ''}`}>
                    <th scope="row" className="sticky left-0 bg-[#0A1626] px-2 py-1.5 text-left font-normal whitespace-nowrap">
                        <span className="inline-block w-6 font-mono text-[10px] text-slate-500">{p.jersey}</span>
                        {nameEl}
                        {p.position && <span className="ml-1.5 font-mono text-[10px] text-slate-500">{p.position}</span>}
                        {mine && mp && !dnp && <span className="ml-2 font-mono text-[10px] text-slate-500">{open ? '▴ 收合' : '▾ 進階'}</span>}
                    </th>
                    {dnp ? (
                        <td colSpan={BOX_COLS.length} className="px-2 py-1.5 text-left text-[12px] text-slate-500">{p.comment || 'DNP'}</td>
                    ) : BOX_COLS.map(([k]) => (
                        <td key={k} className={`px-2 py-1.5 text-right font-mono tabular-nums whitespace-nowrap ${tdCls(p.stats, k)}`}>{cell(p.stats, k)}</td>
                    ))}
                </tr>
                {open && <tr><td colSpan={BOX_COLS.length + 1} className="bg-[#12A150]/[0.04] p-0">{expandRow(mp)}</td></tr>}
            </React.Fragment>
        );
    };
    const boxCsv = () => ({
        header: ['球隊', '球員', '背號', '先發', ...BOX_COLS.map(c => c[1])],
        rows: box.players.map(p => [p.tricode, p.name, p.jersey, p.starter ? '先發' : '', ...(p.stats && Object.keys(p.stats).length ? BOX_COLS.map(([k]) => cell(p.stats, k)) : BOX_COLS.map((c, i) => i === 0 ? (p.comment || 'DNP') : ''))]),
    });
    const boxSection = box && (
        <UI.Section title="Box Score" en="Traditional" accent="silver"
            sub="點灰狼球員那一列展開本場進階（網址會記住，可分享）；點名字到球員頁 · 綠字＝該欄全隊最高"
            right={<>
                <UI.Seg ariaLabel="Box Score 球隊" size="sm" value={boxSide} onChange={setBoxSide}
                    options={[{ value: 'MIN', label: 'MIN 灰狼' }, { value: 'OPP', label: `${oppAbbr} 對手` }]} />
                <UI.ExportMenu title={`Box Score ${date} ${meta.matchup || ''}`} getNode={() => boxRef.current} csv={boxCsv} />
            </>}>
            <div ref={boxRef} className="overflow-x-auto border-t border-white/[0.08]">
                <table className="w-full min-w-[820px] border-collapse text-[13px]">
                    <caption className="sr-only">{sideTri} Box Score</caption>
                    <thead><tr className="border-b border-white/15">
                        <th scope="col" className="sticky left-0 bg-[#0A1626] px-2 py-2 text-left font-mono text-[10px] font-normal text-slate-500">球員</th>
                        {BOX_COLS.map(([k, l]) => <th key={k} scope="col" className="px-2 py-2 text-right font-mono text-[10px] font-normal text-slate-500">{l}</th>)}
                    </tr></thead>
                    <tbody>
                        <tr><td colSpan={BOX_COLS.length + 1} className="px-2 pt-3 pb-1 font-mono text-[10px] tracking-[0.14em] text-slate-500">先發 STARTERS</td></tr>
                        {sidePlayers.filter(p => p.starter).map(boxRow)}
                        <tr><td colSpan={BOX_COLS.length + 1} className="px-2 pt-3 pb-1 font-mono text-[10px] tracking-[0.14em] text-slate-500">替補 BENCH</td></tr>
                        {sidePlayers.filter(p => !p.starter).map(boxRow)}
                        {sideTeam && (
                            <tr className="border-t border-white/20 font-semibold text-slate-50">
                                <th scope="row" className="sticky left-0 bg-[#0A1626] px-2 py-2 text-left">合計</th>
                                {BOX_COLS.map(([k]) => <td key={k} className="px-2 py-2 text-right font-mono tabular-nums">{k === 'MIN' || k === 'PLUS_MINUS' ? '' : cell(sideTeam.totals, k)}</td>)}
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
            {(box.inactives || []).filter(p => p.tricode === sideTri).length > 0 && (
                <p className="mt-2 text-[12px] text-slate-400"><span className="mr-2 font-mono text-[10px] text-slate-500">INACTIVE</span>
                    {box.inactives.filter(p => p.tricode === sideTri).map(p => `${p.jersey ? '#' + p.jersey + ' ' : ''}${p.name}`).join('　')}</p>
            )}
        </UI.Section>
    );
    // 沒有 box 的舊場次：灰狼球員清單（只有進階）
    const noBoxPlayers = !box && minPlayers.length > 0 && (
        <UI.Section title="灰狼球員本場進階" en="Tracking" accent="silver" sub="點球員展開本場進階；點名字到球員頁">
            <div className="border-t border-white/[0.08]">
                {minPlayers.map(p => {
                    const open = expanded && expanded.pid === p.pid;
                    return (
                        <div key={p.pid || p.name} className={`border-b border-white/[0.06] ${open ? 'bg-[#12A150]/[0.05]' : ''}`}>
                            <button type="button" onClick={() => onExpand(open ? '' : p.name)} className="flex w-full items-center justify-between px-2 py-2 text-left text-[13px] hover:bg-white/[0.03]">
                                <a href={playerHref(p.name)} onClick={e => e.stopPropagation()} className={linkCls}>{p.name}</a>
                                <span className="font-mono text-[11px] text-slate-500">{p.adv && typeof p.adv.PTS === 'number' ? `${p.adv.PTS} 分 · ` : ''}{open ? '▴ 收合' : '▾ 進階'}</span>
                            </button>
                            {open && expandRow(p)}
                        </div>
                    );
                })}
            </div>
        </UI.Section>
    );

    // ── 球隊對比（鏡像長條）──
    const MS = (docs.team && docs.team.stats) || {}, OS = (docs.team && docs.team.opp) || null;
    const T = box ? minTeam.totals : null, O = box ? oppTeam.totals : null;
    const pctOf = (a, b) => (b ? a / b * 100 : null);
    const CMP = [
        ['基本 BOX', box ? [
            ['FG_PCT', pctOf(T.FGM, T.FGA), pctOf(O.FGM, O.FGA)], ['FG3_PCT', pctOf(T.FG3M, T.FG3A), pctOf(O.FG3M, O.FG3A)], ['FT_PCT', pctOf(T.FTM, T.FTA), pctOf(O.FTM, O.FTA)],
            ['REB', T.REB, O.REB], ['OREB', T.OREB, O.OREB], ['AST', T.AST, O.AST], ['STL', T.STL, O.STL], ['BLK', T.BLK, O.BLK], ['TOV', T.TOV, O.TOV], ['PF', T.PF, O.PF],
        ] : []],
        ['TRACKING', ['TOUCHES', 'PASSES_MADE', 'DRIVES', 'POTENTIAL_AST', 'CATCH_SHOOT_EFG_PCT', 'PULL_UP_EFG_PCT'].map(k => [k, MS[k], OS ? OS[k] : null])],
        ['HUSTLE', ['DEFLECTIONS', 'CONTESTED_SHOTS', 'SCREEN_ASSISTS', 'LOOSE_BALLS', 'BOX_OUTS', 'CHARGES_DRAWN'].map(k => [k, MS[k], OS ? OS[k] : null])],
    ].map(([g, rows]) => [g, rows.filter(r => typeof r[1] === 'number')]).filter(([, rows]) => rows.length);
    const LOW_BETTER = new Set(['TOV', 'PF']);
    const cmpLabel = (k) => ({ OREB: ['進攻籃板', 'OREB'], PF: ['犯規', 'PF'] }[k] || [metaOf(k).label, metaOf(k).englishLabel]);
    const cmpSection = CMP.length > 0 && (
        <UI.Section title="球隊對比" en="Team Comparison" accent="blue"
            sub={`左灰狼、右 ${oppAbbr}；條長以兩隊合計為分母，較佳一方粗體（失誤、犯規越少越好）${OS ? '' : ' · 這場沒有抓對手的 Tracking／Hustle（2026-10 起才有），右側顯示「—」'}`}>
            <div className="mb-1 grid grid-cols-[1fr_96px_1fr] items-center font-display text-[18px] font-bold sm:grid-cols-[1fr_150px_1fr]">
                <span className="text-[#12A150]">MIN</span><span className="text-center font-mono text-[10px] font-normal text-slate-500">指標</span><span className="text-right">{oppAbbr}</span>
            </div>
            {CMP.map(([g, rows]) => (
                <div key={g}>
                    <div className="border-b border-white/10 pb-1 pt-3 font-mono text-[10px] tracking-[0.14em] text-slate-500">{g}</div>
                    {rows.map(([k, a, b]) => {
                        const [zh, en] = cmpLabel(k);
                        const has = typeof b === 'number';
                        const sum = (a || 0) + (has ? b : 0) || 1;
                        const low = LOW_BETTER.has(k);
                        const mWin = has && a !== b && (low ? a < b : a > b), oWin = has && a !== b && !mWin;
                        const pct = /_PCT$/.test(k);
                        const f = v => typeof v !== 'number' ? '—' : pct ? v.toFixed(1) : (Number.isInteger(v) ? v : v.toFixed(1));
                        return (
                            <div key={k} className="grid grid-cols-[40px_1fr_96px_1fr_40px] items-center gap-2 border-b border-white/[0.04] py-1.5 sm:grid-cols-[52px_1fr_150px_1fr_52px]">
                                <span className={`font-mono text-[13px] tabular-nums ${mWin ? 'font-bold text-slate-50' : 'text-slate-300'}`}>{f(a)}</span>
                                <div className="relative h-2 bg-white/[0.04]"><i className="absolute inset-y-0 right-0 block bg-[#12A150]" style={{ width: `${(a || 0) / sum * 100}%` }}></i></div>
                                <div className="text-center text-[12px] text-slate-400">{zh}{en && <span className="block font-mono text-[9px] text-slate-500">{en}</span>}</div>
                                <div className="relative h-2 bg-white/[0.04]">{has && <i className="absolute inset-y-0 left-0 block bg-[#C4CED2]/45" style={{ width: `${b / sum * 100}%` }}></i>}</div>
                                <span className={`text-right font-mono text-[13px] tabular-nums ${oWin ? 'font-bold text-slate-50' : 'text-slate-300'}`}>{f(b)}</span>
                            </div>
                        );
                    })}
                </div>
            ))}
        </UI.Section>
    );

    // ── 本場 vs 季平均 ──
    const VS_KEYS = ['PTS', 'REB', 'AST', 'FG_PCT', 'FG3_PCT', 'TOV', 'PLUS_MINUS', 'DRIVES', 'TOUCHES', 'D_FG_PCT', 'CONTESTED_SHOTS', 'DEFLECTIONS'];
    const vsSection = vsPlayer && vsPlayer.adv && (() => {
        const ent = vsPlayer.adv, avgAgg = avgCache[vsPlayer.pid];
        const keys = VS_KEYS.filter(k => typeof ent[k] === 'number');
        return (
            <UI.Section title="本場 vs 季平均" en="Game vs Season" accent="green"
                sub="銀色刻度＝賽前季平均（不含本場）；條＝本場值，綠＝優於平均、紅＝低於平均，次數類（觸球、切入）為中性灰色">
                {/* 球員選擇放內容第一行（可換行）：Section 標題右側不換行，十幾個人會把手機版面撐寬 */}
                <div className="mb-3 flex flex-wrap gap-1.5">{minPlayers.filter(p => p.adv).map(p => (
                    <UI.Chip key={p.pid || p.name} active={p.pid === vsPlayer.pid} onClick={() => setVsWho(p.name)}>{p.boxName}</UI.Chip>
                ))}</div>
                {avgAgg === null && <div className="mb-3"><UI.Note>本季沒有更早的逐場資料，無季平均可比（例如球季第一場）</UI.Note></div>}
                <div className="grid grid-cols-2 border-l border-t border-white/[0.08] sm:grid-cols-3 lg:grid-cols-4">
                    {keys.map(k => {
                        const m = metaOf(k), v = ent[k], avg = avgAgg ? avgAgg[k] : undefined;
                        const j = judge(k, v, avg, ent);
                        const hi = Math.max(Math.abs(v), Math.abs(avg || 0)) * 1.3 || 1;
                        const color = j.good ? 'bg-[#12A150]' : j.bad ? 'bg-[#EF4444]' : 'bg-[#C4CED2]/50';
                        const d = typeof avg === 'number' ? v - avg : null;
                        return (
                            <a key={k} href={metricHref(vsPlayer.name, k)} className="group block border-b border-r border-white/[0.08] px-3 pb-3 pt-2.5 hover:bg-white/[0.03]">
                                <div className="flex justify-between text-[11px] text-slate-300"><span>{m.label}</span><span className="font-mono text-[10px] text-slate-500">{m.englishLabel}</span></div>
                                <div className="mb-2 mt-1 flex items-baseline gap-2">
                                    <span className="font-display text-[26px] font-semibold leading-none tabular-nums text-slate-50">{fmtV(k, v)}</span>
                                    {d != null && <span className={`font-mono text-[11px] ${j.good ? 'text-[#12A150]' : j.bad ? 'text-[#EF4444]' : 'text-slate-500'}`}>{d >= 0 ? '+' : ''}{d.toFixed(1)}</span>}
                                    {j.small && <span className="text-[10px] text-amber-300/80">樣本少</span>}
                                </div>
                                <div className="relative h-2.5 bg-white/[0.05]">
                                    <i className={`absolute inset-y-0.5 left-0 block ${color}`} style={{ width: `${Math.max(0, v) / hi * 100}%` }}></i>
                                    {typeof avg === 'number' && avg >= 0 && <u className="absolute -inset-y-1 block w-0.5 bg-[#C4CED2]" style={{ left: `${avg / hi * 100}%` }}></u>}
                                </div>
                                <div className="mt-1 flex justify-between font-mono text-[10px] text-slate-500"><span>本場</span><span>季均 {avg === undefined ? '…' : fmtV(k, avg)}</span></div>
                            </a>
                        );
                    })}
                </div>
                <p className="mt-2 text-[11px] text-slate-500">點任一格 → 該指標逐場走勢（圈出這場）</p>
            </UI.Section>
        );
    })();

    // ── 本場投籃 ──
    const ZONES = [['RA', '合理衝撞區', 'Restricted Area'], ['PAINT', '禁區（非 RA）', 'In The Paint'], ['MID', '中距離', 'Mid-Range'], ['C3', '底角三分', 'Corner 3'], ['AB3', '非底角三分', 'Above the Break 3']];
    const shotEnt = shotWho === 'TEAM' ? MS : ((minPlayers.find(p => String(p.pid) === String(shotWho)) || {}).adv || {});
    const shotAvg = shotWho === 'TEAM' ? null : avgCache[shotWho];
    const shotPlayers = minPlayers.filter(p => p.adv && p.adv.FGA > 0);
    const ShotChart = window.ShotChart;
    const shotSection = (
        <UI.Section title="本場投籃" en="Shot Chart" accent="green"
            sub="投籃點來自每週抓取的 shotchart，本週的比賽可能要等下次週更才有點位；右表分區命中來自單場文件（每天更新）">
            <div className="mb-3 flex flex-wrap gap-1.5">
                <UI.Chip active={shotWho === 'TEAM'} onClick={() => setShotWho('TEAM')}>全隊</UI.Chip>
                {shotPlayers.map(p => <UI.Chip key={p.pid} active={String(shotWho) === String(p.pid)} onClick={() => setShotWho(String(p.pid))}>{p.boxName}</UI.Chip>)}
            </div>
            <div className="grid gap-6 lg:grid-cols-[minmax(0,1.15fr)_minmax(0,1fr)] lg:items-start">
                <div>
                    {shots === undefined ? <div className="py-10 text-center text-sm text-slate-500 animate-pulse">載入投籃點…</div>
                        : !shots || shots.length === 0 ? <UI.Note>這場還沒有投籃點位（shotchart 每週更新一次）</UI.Note>
                        : ShotChart && <ShotChart playerId={shotWho === 'TEAM' ? 0 : Number(shotWho)} teamMode={shotWho === 'TEAM'}
                            playerName={shotWho === 'TEAM' ? '灰狼全隊' : (shotPlayers.find(p => String(p.pid) === String(shotWho)) || {}).boxName}
                            externalShots={shots} periodLabel={`${date} ${meta.matchup || ''}`} />}
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full border-collapse text-[13px]">
                        <caption className="sr-only">本場分區命中</caption>
                        <thead><tr className="border-b border-white/15">
                            {['分區', 'FGM-FGA', 'FG%', shotAvg ? '季均' : ''].map((h, i) => <th key={i} scope="col" className={`px-2 py-2 font-mono text-[10px] font-normal text-slate-500 ${i ? 'text-right' : 'text-left'}`}>{h}</th>)}
                        </tr></thead>
                        <tbody>{ZONES.map(([z, zh, en]) => {
                            const m = shotEnt[`${z}_FGM`], a = shotEnt[`${z}_FGA`];
                            const pct = a ? m / a * 100 : null, avg = shotAvg ? shotAvg[`${z}_FG_PCT`] : null;
                            const cls = pct == null || avg == null || a < MIN_N ? 'text-slate-200' : pct >= avg ? 'text-[#12A150]' : 'text-[#EF4444]';
                            return (
                                <tr key={z} className="border-b border-white/[0.06]">
                                    <th scope="row" className="px-2 py-1.5 text-left font-normal text-slate-200">{zh}<span className="ml-1.5 font-mono text-[10px] text-slate-500">{en}</span></th>
                                    <td className="px-2 py-1.5 text-right font-mono tabular-nums">{typeof a === 'number' ? `${m}-${a}` : '—'}</td>
                                    <td className={`px-2 py-1.5 text-right font-mono tabular-nums ${cls}`}>{pct == null ? '—' : pct.toFixed(1)}</td>
                                    <td className="px-2 py-1.5 text-right font-mono tabular-nums text-slate-500">{shotAvg ? (typeof avg === 'number' ? avg.toFixed(1) : '—') : ''}</td>
                                </tr>
                            );
                        })}</tbody>
                    </table>
                    {shotAvg && <p className="mt-2 text-[11px] text-slate-500">綠／紅＝高於／低於賽前季均（出手少於 {MIN_N} 次不標色）</p>}
                </div>
            </div>
        </UI.Section>
    );

    // ── 比賽資訊 ──
    const info = box && (box.arena || (box.officials || []).length > 0) && (
        <UI.Section title="比賽資訊" en="Game Info" accent="silver">
            <dl className="grid grid-cols-2 border-l border-t border-white/[0.08] sm:grid-cols-4">
                {[['場館', box.arena], ['觀眾', box.attendance ? box.attendance.toLocaleString() : ''], ['比賽時間', box.duration], ['裁判', (box.officials || []).join(' · ')]].filter(([, v]) => v).map(([k, v]) => (
                    <div key={k} className="border-b border-r border-white/[0.08] px-3 py-2.5">
                        <dt className="font-mono text-[10px] tracking-[0.12em] text-slate-500">{k}</dt><dd className="mt-1 text-[13px] text-slate-200">{v}</dd>
                    </div>
                ))}
            </dl>
        </UI.Section>
    );

    return (
        <div className="space-y-10">
            <div>
                {strip}
                {board}
            </div>
            {leaders}
            {boxSection}
            {noBoxPlayers}
            {cmpSection}
            {vsSection}
            {shotSection}
            {info}
            <p className="text-[11px] leading-relaxed text-slate-500">
                資料：NBA.com Stats（boxscoretraditionalv3／boxscoresummaryv3、leaguedash 單日 Tracking／Hustle、shotchartdetail）。
                {meta.partial ? ' 這場部分來源抓取不完整，之後的每日補抓會再補齊。' : ''}
            </p>
        </div>
    );
};

window.GamePage = GamePage;


// ---------- Highlights.js ----------
// 近期異動（找題材用）：近 N 場 vs 全季（皆截至 untilDate），列出變化最明顯的指標
// 排序依據 = |近 N 場平均 − 全季平均| ÷ (逐場標準差 ÷ √N)
//   用意：平常就波動很大的指標（如正負值）要變很多才算明顯；這是「描述性」的尺度，不是統計檢定
// 命中率類以 Σ命中 ÷ Σ出手 計算，且近 N 場出手數需達門檻（MIN_ATT），否則不列入
// 要調整指標或門檻 → 改下方 METRICS
const Highlights = ({ games, untilDate }) => {
    const { useState } = React;
    const UI = window.UI;
    const GA = window.GameAgg;
    const [n, setN] = useState(5);

    const METRICS = [
        { key: 'PTS', label: '得分', en: 'PTS' },
        { key: 'REB', label: '籃板', en: 'REB' },
        { key: 'AST', label: '助攻', en: 'AST' },
        { key: 'STL', label: '抄截', en: 'STL' },
        { key: 'BLK', label: '阻攻', en: 'BLK' },
        { key: 'TOV', label: '失誤', en: 'TOV', lowerIsBetter: true },
        { key: 'PLUS_MINUS', label: '正負值', en: '+/-' },
        { key: 'FG_PCT', label: '命中率', en: 'FG%', pct: ['FGM', 'FGA'], MIN_ATT: 25 },
        { key: 'FG3_PCT', label: '三分命中率', en: '3P%', pct: ['FG3M', 'FG3A'], MIN_ATT: 10 },
        { key: 'FT_PCT', label: '罰球命中率', en: 'FT%', pct: ['FTM', 'FTA'], MIN_ATT: 8 },
    ];

    if (!games || !games.length) return null;
    const pool = untilDate ? games.filter(g => !g.date || g.date <= untilDate) : games;
    const sorted = pool.slice().sort((a, b) => (a.date < b.date ? -1 : 1));
    if (sorted.length < n + 5) return null;   // 全季場數太少，比較沒有意義
    const recent = sorted.slice(-n);

    const num = (v) => (typeof v === 'number' ? v : null);
    const sum = (arr, k) => arr.reduce((a, g) => a + (num(g.stats?.[k]) || 0), 0);
    const rows = [];
    const skipped = [];
    for (const m of METRICS) {
        let season, rec, perGame, recAtt = null;
        if (m.pct) {
            const [mk, ak] = m.pct;
            const sA = sum(sorted, ak), rA = sum(recent, ak);
            if (!sA) continue;
            season = 100 * sum(sorted, mk) / sA;
            recAtt = rA;
            if (rA < m.MIN_ATT) { skipped.push(`${m.label}（近 ${n} 場僅 ${rA} 次出手，門檻 ${m.MIN_ATT}）`); continue; }
            rec = 100 * sum(recent, mk) / rA;
            perGame = sorted.filter(g => num(g.stats?.[ak])).map(g => 100 * (num(g.stats[mk]) || 0) / g.stats[ak]);
        } else {
            perGame = sorted.map(g => num(g.stats?.[m.key])).filter(v => v != null);
            if (perGame.length < n + 5) continue;
            season = perGame.reduce((a, b) => a + b, 0) / perGame.length;
            const r = recent.map(g => num(g.stats?.[m.key])).filter(v => v != null);
            if (!r.length) continue;
            rec = r.reduce((a, b) => a + b, 0) / r.length;
        }
        const mean = perGame.reduce((a, b) => a + b, 0) / perGame.length;
        const sd = Math.sqrt(perGame.reduce((a, b) => a + (b - mean) ** 2, 0) / Math.max(1, perGame.length - 1));
        const diff = rec - season;
        const score = sd > 0 ? Math.abs(diff) / (sd / Math.sqrt(n)) : 0;
        rows.push({ ...m, season, rec, diff, score, recAtt });
    }
    const top = rows.sort((a, b) => b.score - a.score).slice(0, 4).filter(r => r.score >= 1);

    const fmt = (v, m) => (m.pct ? v.toFixed(1) + '%' : (m.key === 'PLUS_MINUS' && v > 0 ? '+' : '') + v.toFixed(1));
    const good = (r) => (r.diff > 0) !== !!r.lowerIsBetter;

    return (
        <UI.Section title="近期異動" en="Recent Trends" accent="silver"
            sub={`近 ${n} 場 vs 全季${untilDate ? `（皆截至 ${untilDate}）` : ''} · 依「變化量相對於逐場波動」排序，描述性比較、非統計檢定 · 命中率需達最低出手數`}
            right={<UI.Seg ariaLabel="近幾場" size="sm" value={n} onChange={setN}
                options={[{ value: 5, label: '近 5 場' }, { value: 10, label: '近 10 場' }]} />}>
            {top.length === 0 ? (
                <UI.Note>近 {n} 場沒有明顯偏離全季水準的指標</UI.Note>
            ) : (
                <ul className="grid gap-x-10 md:grid-cols-2">
                    {top.map(r => {
                        const text = UI.citeLine({ label: r.label, en: r.en, value: fmt(r.rec, r), gkey: r.key, asOf: 'agg',
                            note: `近 ${n} 場（全季 ${fmt(r.season, r)}，差 ${r.diff > 0 ? '+' : ''}${r.diff.toFixed(1)}${r.pct ? ' 個百分點' : ''}）` });
                        return (
                            <li key={r.key} className="group/cell grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-4 border-b border-white/[0.08] py-2.5">
                                <div className="min-w-0">
                                    <div className="flex items-center text-[13px] text-slate-100">
                                        {r.label}<span className="ml-1.5 font-mono text-[10px] text-slate-500">{r.en}</span>
                                        <UI.Info k={r.key} />
                                    </div>
                                    <div className="mt-0.5 font-mono text-[11px] tabular-nums text-slate-400">
                                        全季 {fmt(r.season, r)} → 近 {n} 場 <span className="text-slate-100">{fmt(r.rec, r)}</span>
                                        {r.recAtt != null && <span className="text-slate-500"> · 出手 {r.recAtt}</span>}
                                    </div>
                                </div>
                                <div className="flex items-center gap-1">
                                    <span className={`font-display text-[22px] font-semibold tabular-nums ${good(r) ? 'text-[#12A150]' : 'text-[#EF4444]'}`}>
                                        <span className="mr-1 align-[3px] text-[11px]">{r.diff > 0 ? '▲' : '▼'}</span>{Math.abs(r.diff).toFixed(1)}
                                    </span>
                                    <UI.CopyBtn text={text} />
                                </div>
                            </li>
                        );
                    })}
                </ul>
            )}
            {skipped.length > 0 && <p className="mt-2 text-[11px] text-slate-500">未列入：{skipped.join('、')}</p>}
        </UI.Section>
    );
};

window.Highlights = Highlights;


// ---------- OverviewTab.js ----------
// 總覽章節：季平均（扣掉身分列已顯示的 4 項）＋ Playtype 強弱項 ＋ 雷達 ＋ On/Off（球員）＋ Clutch ＋ Lineups（球隊）＋ 單場面板
// games：逐場 bundle（每場 {stats}）；untilDate：截至日期；base：快照 base（bundle 缺時退回，如更早無 games 的歷史季）
// stats：該實體的 Synergy 陣列（強弱項用）；radarSlot：App 組好的雷達＋疊加比較
const OverviewTab = ({ viewMode, selectedPlayer, games, untilDate, base, snapshotClutch, snapshotOnoff, lineups, gamesIndex, seasonLabel, onoffNA = null, viewSide = 'offensive', radarSlot = null, stats = [] }) => {
    const GA = window.GameAgg;
    const UI = window.UI;
    const clutchDefs = window.clutchDefs || [];
    const SingleGamePanel = window.SingleGamePanel;

    // 季平均欄位（NBA.com traditional 主體）。身分列已顯示的不重複列出：
    //   球隊身分列 = PTS/REB/AST/+-；球員身分列 = PTS/REB/AST/FG%（見 IdentityBar.js 的 FIELDS）
    const SUMMARY = [
        { key: 'PTS', label: '得分', en: 'PTS' },
        { key: 'REB', label: '籃板', en: 'REB' },
        { key: 'AST', label: '助攻', en: 'AST' },
        { key: 'STL', label: '抄截', en: 'STL' },
        { key: 'BLK', label: '阻攻', en: 'BLK' },
        { key: 'FG_PCT', label: '命中率', en: 'FG%', pct: true },
        { key: 'FG3_PCT', label: '三分命中率', en: '3P%', pct: true },
        { key: 'FT_PCT', label: '罰球命中率', en: 'FT%', pct: true },
        { key: 'TOV', label: '失誤', en: 'TOV' },
        { key: 'PLUS_MINUS', label: '正負值', en: '+/-', plus: true },
    ];
    // 期間切換：全季／近 5 場／近 10 場（截至同一天）。專欄最常查「最近幾場」，不必再跳到 Splits。
    // 近 N 場時身分列（全季數字）不再重複，故顯示完整 10 項
    const [range, setRange] = React.useState('all');
    const IN_IDENTITY = viewMode === 'TEAM' ? ['PTS', 'REB', 'AST', 'PLUS_MINUS'] : ['PTS', 'REB', 'AST', 'FG_PCT'];

    // 優先用 bundle 逐場算（截至該日，任何日期皆穩定）；bundle 未載入或無資料則退回快照 base（沒有逐場就不能切近 N 場）
    const gamesUntil = (games && games.length) ? games.filter(g => !untilDate || g.date <= untilDate) : null;
    const bundleAgg = gamesUntil ? GA.aggregate(range === 'all' ? gamesUntil : GA.lastN(gamesUntil, Number(range)), null, 'TEAM') : null;
    const baseAgg = (base && typeof base.GP === 'number' && base.GP > 0) ? base : null;
    const agg = (bundleAgg && bundleAgg.GP > 0) ? bundleAgg : baseAgg;
    const canRange = !!(bundleAgg && bundleAgg.GP > 0);
    const isRecent = canRange && range !== 'all';
    const summary = isRecent ? SUMMARY : SUMMARY.filter(s => !IN_IDENTITY.includes(s.key));
    const rangeLabel = isRecent ? `近 ${range} 場平均` : '季平均';
    const loadingAvg = games === null && !baseAgg;

    const valOf = (v, s) => {
        if (typeof v !== 'number') return null;
        if (s.plus) return (v > 0 ? '+' : '') + v.toFixed(1);
        return v.toFixed(1);
    };

    // Playtype 強弱項（BBall Index 式）：只用 Synergy 百分位（真有聯盟排名的數字）。
    // 攻守兩面百分位皆「越高越好」（已用資料驗證：防守 PPP 越低 → 百分位越高）。
    // 門檻：每場球權 ≥ 1.0（球權太少的類型百分位很極端）；排除 Misc（雜項，不是戰術類型）。
    // 強項只列百分位 ≥ 50、弱項只列 < 50：「排最後三名」不等於弱項，高於中位數的不可標成弱項
    const MIN_POSS_PG = 1.0;
    const ranked = (stats || [])
        .filter(x => (x.side || 'offensive') === viewSide && typeof x.percentile === 'number' && x.playType !== 'Misc')
        .filter(x => typeof x.poss === 'number' && x.poss >= MIN_POSS_PG)
        .sort((a, b) => b.percentile - a.percentile);
    const strengths = ranked.filter(x => x.percentile >= 50).slice(0, 3);
    const weaknesses = ranked.filter(x => x.percentile < 50).slice(-3).reverse();

    // On/Off（球員快照）
    const onoff = viewMode === 'PLAYER' ? (snapshotOnoff || {}) : null;
    const hasOnoff = onoff && typeof onoff.ON_NET_RATING === 'number';

    // Clutch（快照，無資料整段隱藏）
    const clutchEntity = snapshotClutch || {};
    const clutchMetrics = clutchDefs[0] ? clutchDefs[0].metrics : [];
    const hasClutch = clutchMetrics.some(m => clutchEntity[m.key] !== undefined);

    // 陣容名：桌面全名「R. Gobert - J. Randle …」，手機只留姓氏，避免表格被撐高
    const f1 = (v) => typeof v === 'number' ? v.toFixed(1) : '—';   // 表格數字統一一位小數（避免「48」與「48.2」並列）
    const shortLineup = (s) => String(s || '').split(' - ').map(n => n.replace(/^[A-Z]\.\s*/, '')).join(' · ');

    const PtRow = ({ x }) => (
        <li className="grid grid-cols-[minmax(0,1fr)_auto] items-end gap-x-4 border-b border-white/[0.08] py-2.5 last:border-b-0">
            <div className="min-w-0">
                <div className="font-display text-[15px] font-semibold uppercase tracking-wide text-slate-100 truncate">{x.playType}</div>
                <div className="font-mono text-[10px] text-slate-500">{typeof x.ppp === 'number' ? x.ppp.toFixed(2) : '—'} PPP · {x.poss.toFixed(1)} poss/G</div>
            </div>
            <div className="w-28 sm:w-36"><UI.PctBar value={x.percentile} label="PR" /></div>
        </li>
    );

    return (
        <div className="space-y-10">
            {window.Highlights && <window.Highlights games={games} untilDate={untilDate} />}

            <UI.Section title={isRecent ? `近 ${range} 場` : '季平均'} en={isRecent ? `Last ${range} Games` : 'Season Averages'} accent="green"
                right={canRange && <UI.Seg size="sm" ariaLabel="平均期間" value={range} onChange={setRange}
                    options={[{ value: 'all', label: '全季' }, { value: '5', label: '近 5 場' }, { value: '10', label: '近 10 場' }]} />}
                sub={[agg ? `${agg.GP} 場${(agg.W || agg.L) ? ` · ${agg.W} 勝 ${agg.L} 敗` : ''}` : null, seasonLabel, untilDate ? `截至 ${untilDate}` : '整季', '百分比以 Σ命中 ÷ Σ出手 重算'].filter(Boolean).join(' · ')}>
                {!agg ? (
                    <div className={`py-6 text-center text-sm text-slate-500 ${loadingAvg ? 'animate-pulse' : ''}`}>
                        {loadingAvg ? '載入季平均中…' : '此賽季尚無季平均資料'}
                    </div>
                ) : (
                    <UI.Ledger cols={UI.ledgerCols(summary.length)}>
                        {summary.map(s => (
                            <UI.StatCell key={s.key} label={s.label} en={s.en} value={valOf(agg[s.key], s)} unit={s.pct ? '%' : ''}
                                gkey={s.key} citeAsOf="agg" citeNote={rangeLabel} />
                        ))}
                    </UI.Ledger>
                )}
            </UI.Section>

            {ranked.length > 0 && (
                <UI.Section title="Playtype 強弱項" en="Strengths & Weaknesses" accent={viewSide === 'offensive' ? 'green' : 'red'}
                    sub={`${viewSide === 'offensive' ? '進攻' : '防守'}面 · Synergy 聯盟百分位 · 只計每場球權 ≥ ${MIN_POSS_PG} 的類型（球權太少百分位會失真），不含 Misc`}>
                    <div className="grid gap-x-10 gap-y-6 md:grid-cols-2">
                        <div>
                            <h3 className="mb-1 text-[12px] font-medium text-[#12A150]">強項 · 高於聯盟中位數</h3>
                            {strengths.length ? <ul>{strengths.map(x => <PtRow key={x.playType} x={x} />)}</ul>
                                : <p className="py-3 text-[13px] text-slate-500">沒有高於聯盟中位數的類型</p>}
                        </div>
                        <div>
                            <h3 className="mb-1 text-[12px] font-medium text-[#EF4444]">弱項 · 低於聯盟中位數</h3>
                            {weaknesses.length ? <ul>{weaknesses.map(x => <PtRow key={x.playType} x={x} />)}</ul>
                                : <p className="py-3 text-[13px] text-slate-500">沒有低於聯盟中位數的類型</p>}
                        </div>
                    </div>
                </UI.Section>
            )}

            {radarSlot && (
                <UI.Section title="雷達與疊加比較" en="Radar" accent="silver" sub="軸可自選；可疊加歷史賽季或同季隊友">
                    {radarSlot}
                </UI.Section>
            )}

            {/* On/Off 跨隊不適用（新援該季不在灰狼，API 綁 TeamID 抓不到）。
                onoffNA 預設 null → 留隊球員、以及本來就沒抓 onoff 的舊賽季 doc，
                行為與改動前完全相同（整段隱藏）。「舊季沒抓」不可冒充「跨隊不適用」 */}
            {!hasOnoff && onoffNA && (
                <UI.Section title="在場 / 不在場" en="On/Off Court" accent="blue"
                    right={<span className="border border-white/15 px-1.5 py-0.5 text-[10px] text-slate-400">{window.NA_BADGE}</span>}>
                    <UI.Note>{onoffNA}</UI.Note>
                </UI.Section>
            )}

            {hasOnoff && (
                <UI.Section title="在場 / 不在場" en="On/Off Court" accent="blue" sub="球隊在該球員上場 / 下場時的每 100 回合效率（整季快照）">
                    <UI.Ledger cols="grid-cols-1 sm:grid-cols-3">
                        {[
                            { label: '進攻效率', en: 'OffRtg', gk: 'OFF_RATING', on: onoff.ON_OFF_RATING, off: onoff.OFF_OFF_RATING, better: 'high' },
                            { label: '防守效率', en: 'DefRtg', gk: 'DEF_RATING', on: onoff.ON_DEF_RATING, off: onoff.OFF_DEF_RATING, better: 'low' },
                            { label: '淨效率', en: 'NetRtg', gk: 'NET_RATING', on: onoff.ON_NET_RATING, off: onoff.OFF_NET_RATING, better: 'high' },
                        ].map(m => {
                            const diff = (typeof m.on === 'number' && typeof m.off === 'number') ? m.on - m.off : null;
                            const good = diff != null && (m.better === 'high' ? diff > 0 : diff < 0);
                            return (
                                <div key={m.label} className="group/cell relative border-r border-b border-white/[0.08] px-3 pt-2.5 pb-3 min-w-0">
                                    {diff != null && <UI.CopyBtn className="absolute right-1 top-1"
                                        text={() => UI.citeLine({ label: `${m.label}在場 − 離場`, en: m.en, value: (diff > 0 ? '+' : '') + diff.toFixed(1),
                                            gkey: m.gk, note: `On/Off（在場 ${m.on.toFixed(1)}／離場 ${m.off.toFixed(1)}，每 100 回合）` })} />}
                                    <div className="flex items-center text-[11px] leading-tight text-slate-300">{m.label}<UI.Info k={m.gk} /></div>
                                    <div className="font-mono text-[10px] leading-tight text-slate-500">{m.en} · 在場 − 離場</div>
                                    <div className={`mt-2 font-display text-[26px] font-semibold leading-none tabular-nums ${diff == null ? 'text-slate-600' : good ? 'text-[#12A150]' : 'text-[#EF4444]'}`}>
                                        {diff == null ? '—' : (diff > 0 ? '+' : '') + diff.toFixed(1)}
                                    </div>
                                    <div className="mt-1.5 font-mono text-[11px] tabular-nums text-slate-400">
                                        在場 {typeof m.on === 'number' ? m.on.toFixed(1) : '—'}<span className="mx-1.5 text-slate-600">/</span>離場 {typeof m.off === 'number' ? m.off.toFixed(1) : '—'}
                                    </div>
                                </div>
                            );
                        })}
                    </UI.Ledger>
                </UI.Section>
            )}

            {hasClutch && (
                <UI.Section title="Clutch" en="Per Game" accent="amber" sub="第四節或延長賽最後 5 分鐘、分差 5 分內（NBA 定義）· 整季快照 · 場均">
                    <UI.Ledger cols={UI.ledgerCols(clutchMetrics.length)}>
                        {clutchMetrics.map(m => (
                            <UI.StatCell key={m.key} label={m.label} en={m.englishLabel} value={clutchEntity[m.key]} unit={m.unit}
                                gkey={m.key} citeNote="Clutch（第四節或延長賽最後 5 分鐘、分差 5 分內，場均）" />
                        ))}
                    </UI.Ledger>
                </UI.Section>
            )}

            {viewMode === 'TEAM' && lineups && lineups.length > 0 && (
                <UI.Section title="五人陣容" en="Lineups" accent="blue" sub="預設依總上場分鐘排序，點欄位標題可改排序（效率值為每 100 回合，整季快照）">
                    <UI.DataTable caption="五人陣容進階數據" rows={lineups} exportTitle="五人陣容"
                        initialSort={{ key: 'MIN', dir: 'desc' }} rowKey={(r) => r.players}
                        columns={[
                            { key: 'players', label: '陣容', align: 'left',
                                render: (r) => (<><span className="hidden sm:inline">{r.players}</span><span className="sm:hidden">{shortLineup(r.players)}</span></>) },
                            { key: 'GP', label: '場次', en: 'GP' },
                            { key: 'MIN', label: '總分鐘', en: 'MIN' },
                            { key: 'OFF_RATING', label: '進攻效率', en: 'OffRtg', render: (r) => f1(r.OFF_RATING) },
                            { key: 'DEF_RATING', label: '防守效率', en: 'DefRtg', render: (r) => f1(r.DEF_RATING) },
                            { key: 'NET_RATING', label: '淨效率', en: 'NetRtg',
                                render: (r) => typeof r.NET_RATING !== 'number' ? '—' : (
                                    <span className={r.NET_RATING > 0 ? 'text-[#12A150]' : r.NET_RATING < 0 ? 'text-[#EF4444]' : 'text-slate-200'}>
                                        {r.NET_RATING > 0 ? '+' : ''}{r.NET_RATING.toFixed(1)}
                                    </span>) },
                            { key: 'TS_PCT', label: '真實命中率', en: 'TS%', render: (r) => typeof r.TS_PCT === 'number' ? r.TS_PCT.toFixed(1) + '%' : '—' },
                        ]} />
                </UI.Section>
            )}

            {/* 單場面板（當季，有比賽索引才顯示） */}
            {SingleGamePanel && gamesIndex && gamesIndex.length > 0 && (
                <SingleGamePanel viewMode={viewMode} playerName={selectedPlayer} viewSide={viewSide} gamesIndex={gamesIndex} />
            )}
        </div>
    );
};

window.OverviewTab = OverviewTab;


// ---------- SplitsTab.js ----------
// Splits 分頁：頂部期間篩選 + 欄位組卡片牆（該期間 vs 全季，綠/紅漲跌）+ 點卡片展開趨勢折線
// games：該季逐場 bundle（每場 {date,matchup,wl,stats}）；一律以 game.stats 為實體（GameAgg 'TEAM' 語意）
// focusMetric / highlightDate：網址 m= / hl=（從單場頁點指標過來）→ 自動切到該指標所屬欄位組、打開逐場走勢、圈出那一場
// onFocusChange(metricKey|null)：走勢開關或換指標時回報，讓網址跟著記住（可分享）
// onGameClick(date)：逐場走勢上點某一場（→ 單場頁）；未傳則點不可點
const SplitsTab = ({ games, seasonLabel, isPlayoffs, focusMetric, highlightDate, onFocusChange, onGameClick }) => {
    const { useState, useEffect } = React;
    const GA = window.GameAgg;
    const TrackingCardRow = window.TrackingCardRow;
    const trackingDefs = window.trackingDefs || [];
    const shootingDefs = window.shootingDefs || [];
    const defenseDefs = window.defenseDefs || [];

    const [period, setPeriod] = useState('all');
    const [monthKey, setMonthKey] = useState('');
    const [seriesIdx, setSeriesIdx] = useState(0);
    const [rangeStart, setRangeStart] = useState('');
    const [rangeEnd, setRangeEnd] = useState('');
    const [group, setGroup] = useState('base');
    const [openGroup, setOpenGroup] = useState(null);
    const [trendMetric, setTrendMetric] = useState(null);
    const [gran, setGran] = useState('game');
    const ledgerRef = React.useRef(null);
    const trendRef = React.useRef(null);
    const pendingScrollRef = React.useRef(false);   // 從網址聚焦後，等走勢出現再捲過去

    const BASE_DEF = window.SPLITS_BASE_DEF;
    const ZONES_DEF = shootingDefs.find(d => d.id === 'ShotZones');
    // 單場有的防守資料：最近防守者（僅球員）＋ Hustle。DefenseBox（防守效率等）沒有單場值
    const DEF_DEFS = defenseDefs.filter(d => d.id === 'MatchupDefense' || d.id === 'Hustle');
    const GROUP_DEFS = { base: [BASE_DEF], tracking: trackingDefs, zones: ZONES_DEF ? [ZONES_DEF] : [], defense: DEF_DEFS };

    // 網址帶指標 → 找所屬欄位組與群組（由 defs 反查，不另建對照表；新增指標自動適用）
    useEffect(() => {
        // 自己開走勢時也會回報 m → 已經開著同一個指標就不重設、不捲動
        if (!focusMetric || (openGroup && trendMetric === focusMetric)) return;
        for (const [g, defs] of Object.entries(GROUP_DEFS)) {
            const def = defs.find(d => d.metrics.some(m => m.key === focusMetric));
            if (def) {
                setGroup(g); setOpenGroup(def); setTrendMetric(focusMetric);
                if (highlightDate) setGran('game');
                pendingScrollRef.current = true;   // 走勢渲染出來後再捲過去（見下一個 effect）
                return;
            }
        }
    }, [focusMetric, highlightDate, !!games]);
    // 每次渲染後檢查：從網址聚焦且走勢已出現 → 捲到畫面中央（只做一次）。
    // 不能在設定狀態時就捲：當下欄位組還沒切換、版面高度還會變
    useEffect(() => {
        if (!pendingScrollRef.current || !trendRef.current) return;
        pendingScrollRef.current = false;
        trendRef.current.scrollIntoView({ block: 'center' });   // effect 在 DOM 更新後執行，版面已就緒
    });

    if (!games) return <div className="py-10 text-center text-sm text-slate-500 animate-pulse">載入單場資料中…</div>;
    if (!games.length) return <window.UI.Note>此賽季尚無單場資料（Splits 需要逐場資料）</window.UI.Note>;

    const months = GA.splitByMonth(games).map(g => g.label);
    const series = isPlayoffs ? GA.splitBySeries(games) : [];

    // 期間子集
    let periodGames = games, periodLabel = '全季';
    if (period === 'W') { periodGames = games.filter(g => g.wl === 'W'); periodLabel = '勝場'; }
    else if (period === 'L') { periodGames = games.filter(g => g.wl === 'L'); periodLabel = '敗場'; }
    else if (period === 'home') { periodGames = games.filter(g => (g.matchup || '').includes('vs.')); periodLabel = '主場'; }
    else if (period === 'away') { periodGames = games.filter(g => (g.matchup || '').includes('@')); periodLabel = '客場'; }
    else if (period === 'last5') { periodGames = GA.lastN(games, 5); periodLabel = '近 5 場'; }
    else if (period === 'last10') { periodGames = GA.lastN(games, 10); periodLabel = '近 10 場'; }
    else if (period === 'month') { periodGames = games.filter(g => (g.date || '').slice(0, 7) === monthKey); periodLabel = monthKey; }
    else if (period === 'range') { periodGames = GA.byDateRange(games, rangeStart, rangeEnd); periodLabel = `${rangeStart || '起'}~${rangeEnd || '訖'}`; }
    else if (period === 'series') { periodGames = (series[seriesIdx] || {}).games || []; periodLabel = (series[seriesIdx] || {}).label || '系列'; }

    const seasonAgg = GA.aggregate(games, null, 'TEAM');
    const periodAgg = GA.aggregate(periodGames, null, 'TEAM');

    // 只列出這個實體有資料的群組（球隊沒有最近防守者；舊場次可能沒有 Hustle）
    const hasData = def => def.metrics.some(m => typeof seasonAgg[m.key] === 'number');
    const defs = (GROUP_DEFS[group] || []).filter(hasData);

    const openTrend = (def) => {
        const closing = def.id === (openGroup && openGroup.id);
        setOpenGroup(closing ? null : def);
        setTrendMetric(def.metrics[0].key);
        if (onFocusChange) onFocusChange(closing ? null : def.metrics[0].key);
    };
    const pickTrendMetric = (k) => { setTrendMetric(k); if (onFocusChange) onFocusChange(k); };

    // 趨勢資料（整季，依粒度）
    const trendPts = (openGroup && trendMetric) ? GA.trendSeries(games, null, 'TEAM', trendMetric, gran) : [];
    const trendBaseline = (openGroup && trendMetric) ? seasonAgg[trendMetric] : null;

    const UI = window.UI;
    const GROUPS = [['base', '基本', 'Traditional'], ['tracking', '進階', 'Tracking'], ['zones', '投籃分區', 'Shot Zones'], ['defense', '防守', 'Defense']]
        .filter(([g]) => (GROUP_DEFS[g] || []).some(hasData));

    return (
        <div className="space-y-8">
            {/* 期間篩選列 */}
            <div className="space-y-2.5">
                <div className="flex flex-wrap items-center gap-1.5">
                    <span className="mr-1 text-[11px] text-slate-500">期間</span>
                    <UI.Chip active={period === 'all'} onClick={() => setPeriod('all')}>全季</UI.Chip>
                    <UI.Chip active={period === 'W'} onClick={() => setPeriod('W')}>勝場</UI.Chip>
                    <UI.Chip active={period === 'L'} onClick={() => setPeriod('L')}>敗場</UI.Chip>
                    <UI.Chip active={period === 'home'} onClick={() => setPeriod('home')}>主場</UI.Chip>
                    <UI.Chip active={period === 'away'} onClick={() => setPeriod('away')}>客場</UI.Chip>
                    <UI.Chip active={period === 'last5'} onClick={() => setPeriod('last5')}>近 5 場</UI.Chip>
                    <UI.Chip active={period === 'last10'} onClick={() => setPeriod('last10')}>近 10 場</UI.Chip>
                    <label className="sr-only" htmlFor="splits-month">選擇月份</label>
                    <select id="splits-month" value={period === 'month' ? monthKey : ''} onChange={e => { setPeriod('month'); setMonthKey(e.target.value); }}
                        className={UI.selectClass(period === 'month')}>
                        <option value="">每月</option>
                        {months.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                    {isPlayoffs && series.length > 0 && (<>
                        <label className="sr-only" htmlFor="splits-series">選擇系列賽</label>
                        <select id="splits-series" value={period === 'series' ? seriesIdx : ''} onChange={e => { setPeriod('series'); setSeriesIdx(Number(e.target.value)); }}
                            className={UI.selectClass(period === 'series')}>
                            <option value="">系列賽</option>
                            {series.map((s, i) => <option key={i} value={i}>{s.label}</option>)}
                        </select>
                    </>)}
                    <UI.Chip active={period === 'range'} onClick={() => setPeriod('range')}>自訂區間</UI.Chip>
                </div>
                {period === 'range' && (
                    <div className="flex items-center gap-2 text-xs text-slate-400">
                        <input type="date" aria-label="起始日" value={rangeStart} onChange={e => setRangeStart(e.target.value)} className={UI.selectClass(!!rangeStart)} />
                        <span>~</span>
                        <input type="date" aria-label="結束日" value={rangeEnd} onChange={e => setRangeEnd(e.target.value)} className={UI.selectClass(!!rangeEnd)} />
                    </div>
                )}
            </div>

            <UI.Section title={periodLabel} en="Splits" accent="green"
                sub={`${periodAgg.GP} 場，vs 全季 ${seasonAgg.GP} 場 · 箭頭＝此期間 vs 全季平均 · 百分比以 Σ命中 ÷ Σ出手 重算 · 點群組看趨勢`}
                right={<>
                    <UI.ExportMenu title={`Splits：${periodLabel}（${periodAgg.GP} 場）vs 全季`} getNode={() => ledgerRef.current}
                        csv={() => ({ header: ['群組', '指標', '原文', periodLabel, '全季', '差'], rows: defs.flatMap(d => d.metrics.map(m => {
                            const a = periodAgg[m.key], b = seasonAgg[m.key];
                            return [d.title, m.label, m.englishLabel || '', a == null ? '' : a, b == null ? '' : b, (typeof a === 'number' && typeof b === 'number') ? +(a - b).toFixed(1) : ''];
                        })) })} />
                    <UI.Seg ariaLabel="欄位組" size="sm" value={group} onChange={(g) => { setGroup(g); setOpenGroup(null); if (onFocusChange) onFocusChange(null); }}
                        options={GROUPS.map(([v, l]) => ({ value: v, label: l }))} />
                </>}>
                <div ref={ledgerRef}>
                {periodAgg.GP === 0 ? (
                    <UI.Note>此期間沒有比賽</UI.Note>
                ) : defs.map(def => (
                    <div key={def.id}>
                        <TrackingCardRow title={def.title} actionLabel="點看趨勢" category={def.id} metrics={def.metrics}
                            current={periodAgg} prev={seasonAgg} onClick={() => openTrend(def)} source="stats"
                            citeAsOf="none" citeNote={`Splits：${periodLabel}（${periodAgg.GP} 場）`} />
                        {openGroup && openGroup.id === def.id && (
                            <div ref={trendRef} className="-mt-3 mb-6 border border-white/10 p-4">
                                <div className="mb-3 flex flex-wrap items-center gap-3">
                                    <label className="sr-only" htmlFor={`trend-metric-${def.id}`}>趨勢指標</label>
                                    <select id={`trend-metric-${def.id}`} value={trendMetric || ''} onChange={e => pickTrendMetric(e.target.value)}
                                        className={UI.selectClass(true)}>
                                        {def.metrics.map(m => <option key={m.key} value={m.key}>{m.label}</option>)}
                                    </select>
                                    <UI.Seg ariaLabel="趨勢粒度" size="sm" value={gran} onChange={setGran}
                                        options={[{ value: 'game', label: '逐場' }, { value: 'week', label: '每週' }, { value: 'month', label: '每月' }]} />
                                </div>
                                <TrendChart points={trendPts} baseline={trendBaseline}
                                    highlight={gran === 'game' ? highlightDate : null}
                                    onPointClick={gran === 'game' && onGameClick ? (p) => onGameClick(p.label) : null}
                                    unit={(def.metrics.find(m => m.key === trendMetric) || {}).unit === '%' ? '%' : ''}
                                    title={`${(def.metrics.find(m => m.key === trendMetric) || {}).label || ''}趨勢（${gran === 'game' ? '逐場' : gran === 'week' ? '每週' : '每月'}）`} />
                            </div>
                        )}
                    </div>
                ))}
                </div>
            </UI.Section>
        </div>
    );
};

// 簡易 SVG 折線：逐點值 + 全季均線；hover 顯示精確值、上方圖例、虛線右端標基準值
// unit：純文字複製時接在數值後（'%'）；citeSeason：純文字標題的賽季，預設取 CiteCtx.season，跨季比較傳 false 省略
// 點若帶 wl（逐場）→ 底下鋪勝負色帶（綠勝紅敗）
// highlight：要圈出的點 label（逐場＝日期）；窄螢幕需橫捲時自動捲到該點
// onPointClick(point)：點擊某點（逐場 → 單場頁）；未傳則不可點
const TrendChart = ({ points, baseline, title, unit = '', citeSeason, highlight, onPointClick }) => {
    const UI = window.UI;
    const chartRef = React.useRef(null);
    const scrollRef = React.useRef(null);
    const W = 640, H = 160, padL = 34, padR = 46, padT = 12, padB = 22; // padR 加大留基準標籤空間
    const n = points ? points.length : 0;
    const x = i => padL + (n === 1 ? (W - padL - padR) / 2 : i * (W - padL - padR) / (n - 1));
    const hlIdx = highlight && points ? points.findIndex(p => p.label === highlight) : -1;
    React.useEffect(() => {
        const el = scrollRef.current;
        if (!el || hlIdx < 0 || el.scrollWidth <= el.clientWidth) return;
        el.scrollLeft = el.scrollWidth * x(hlIdx) / W - el.clientWidth / 2;
    }, [hlIdx, n]);
    // X 軸：日期標籤去掉年份（2025-01-15 → 01-15、2025-01 → 01）；其他標籤（跨季的「24-25例」）原樣顯示
    const axisLabel = (l) => /^\d{4}-\d{2}(-\d{2})?$/.test(String(l)) ? String(l).slice(5) : String(l);
    // 臉書用純文字：點少（≤6，如跨季）寫成一行箭頭，點多（逐場）一行一點
    const fbText = () => {
        const c = window.CiteCtx || {};
        const subject = c.subject === 'Minnesota Timberwolves' ? '灰狼全隊' : c.subject;
        const season = citeSeason === undefined ? c.season : citeSeason;
        const v = (x) => `${x}${unit}`;
        const body = points.length <= 6
            ? [points.map(p => `${p.label} ${v(p.value)}`).join(' → ')]
            : points.map(p => `${p.label}｜${v(p.value)}${p.wl ? ` ${p.wl}` : ''}`);
        return [
            `【${[subject, season, title].filter(Boolean).join('｜')}】`,
            '',
            ...body,
            ...(baseline != null ? ['', `全季平均 ${v(baseline)}`] : []),
            '',
            '資料：NBA.com Stats',
            `${location.origin}${location.pathname}${location.hash}`,
        ].join('\n');
    };
    if (!points || points.length < 1) return <div className="py-8 text-center text-xs text-slate-500">資料不足，無法繪製趨勢</div>;
    const vals = points.map(p => p.value);
    let lo = Math.min(...vals, baseline != null ? baseline : Infinity);
    let hi = Math.max(...vals, baseline != null ? baseline : -Infinity);
    if (lo === hi) { lo -= 1; hi += 1; }
    const pad = (hi - lo) * 0.1; lo -= pad; hi += pad;
    const y = v => padT + (H - padT - padB) * (1 - (v - lo) / (hi - lo));
    const line = points.map((p, i) => `${i === 0 ? 'M' : 'L'}${x(i).toFixed(1)},${y(p.value).toFixed(1)}`).join(' ');
    const MONO = "'JetBrains Mono', monospace";
    const hasWL = points.some(p => p.wl === 'W' || p.wl === 'L');
    const step = n > 1 ? (W - padL - padR) / (n - 1) : (W - padL - padR);
    const hl = hlIdx >= 0 ? points[hlIdx] : null;
    return (
        <div ref={chartRef}>
            {/* 圖例 */}
            <div className="mb-1 flex flex-wrap items-center gap-x-4 gap-y-1 text-[11px] text-slate-400">
                <span className="flex items-center gap-1.5"><svg width="18" height="6" aria-hidden="true"><line x1="0" y1="3" x2="18" y2="3" stroke="#12A150" strokeWidth="2" /></svg>逐點值</span>
                {baseline != null && <span className="flex items-center gap-1.5"><svg width="18" height="6" aria-hidden="true"><line x1="0" y1="3" x2="18" y2="3" stroke="#C4CED2" strokeWidth="1.5" strokeDasharray="4 3" /></svg>全季平均 {baseline}</span>}
                {hasWL && <span className="flex items-center gap-1.5">
                    <span className="inline-block h-2.5 w-2.5 bg-[#12A150]/25" aria-hidden="true"></span>勝
                    <span className="ml-1 inline-block h-2.5 w-2.5 bg-[#EF4444]/25" aria-hidden="true"></span>敗（底色）
                </span>}
                {hl && <span className="flex items-center gap-1.5 text-amber-300"><svg width="10" height="10" aria-hidden="true"><circle cx="5" cy="5" r="4" fill="none" stroke="#FBBF24" strokeWidth="1.5" /></svg>本場 {axisLabel(hl.label)}</span>}
                <span className="text-slate-500" data-export-hide>{onPointClick ? '滑鼠移到點看數值，點擊看該場' : '滑鼠移到點看數值'}</span>
                {title && <span className="ml-auto"><UI.ExportMenu title={title} getNode={() => chartRef.current}
                    csv={() => ({ header: ['期間', '數值', '全季平均', ...(hasWL ? ['勝負'] : [])], rows: points.map(p => [p.label, p.value, baseline == null ? '' : baseline, ...(hasWL ? [p.wl || ''] : [])]) })}
                    text={fbText} /></span>}
            </div>
            <div ref={scrollRef} className="overflow-x-auto">
                <svg viewBox={`0 0 ${W} ${H}`} className="w-full" style={{ minWidth: 480 }} role="img" aria-label="趨勢折線圖">
                    {hasWL && points.map((p, i) => (p.wl === 'W' || p.wl === 'L') && (
                        <rect key={'wl' + i} x={x(i) - step / 2} y={padT} width={step} height={H - padT - padB}
                            fill={p.wl === 'W' ? '#12A150' : '#EF4444'} fillOpacity="0.09" />
                    ))}
                    {[0, 0.5, 1].map(f => { const v = lo + (hi - lo) * (1 - f); return (
                        <g key={f}><line x1={padL} x2={W - padR} y1={padT + f * (H - padT - padB)} y2={padT + f * (H - padT - padB)} stroke="rgba(255, 255, 255, 0.07)" />
                            <text x={4} y={padT + f * (H - padT - padB) + 3} fill="#64748b" fontSize="9" fontFamily={MONO}>{v.toFixed(1)}</text></g>); })}
                    {baseline != null && (<g>
                        <line x1={padL} x2={W - padR} y1={y(baseline)} y2={y(baseline)} stroke="#C4CED2" strokeOpacity="0.6" strokeDasharray="4 3" strokeWidth="1" />
                        <text x={W - padR + 4} y={y(baseline) + 3} fill="#C4CED2" fontSize="9" fontFamily={MONO}>{baseline}</text>
                    </g>)}
                    <path d={line} fill="none" stroke="#12A150" strokeWidth="2" />
                    {hl && (<g>
                        <circle cx={x(hlIdx)} cy={y(hl.value)} r="7" fill="none" stroke="#FBBF24" strokeWidth="2" />
                        <text x={x(hlIdx)} y={y(hl.value) - 11} fill="#FBBF24" fontSize="10" textAnchor="middle" fontFamily={MONO}>本場 {hl.value}{unit}</text>
                    </g>)}
                    {points.map((p, i) => (
                        <g key={i}>
                            <circle cx={x(i)} cy={y(p.value)} r="2.5" fill={i === hlIdx ? '#FBBF24' : '#12A150'} />
                            <circle cx={x(i)} cy={y(p.value)} r="10" fill="transparent" style={{ cursor: 'pointer' }}
                                onClick={onPointClick ? () => onPointClick(p) : undefined}>
                                <title>{p.label}{p.wl ? `（${p.wl === 'W' ? '勝' : '敗'}）` : ''}：{p.value}{unit}{onPointClick ? '　點擊看這場' : ''}</title>
                            </circle>
                            {(points.length <= 16 || i === hlIdx) && <text x={x(i)} y={H - 8} fill={i === hlIdx ? '#FBBF24' : '#64748b'} fontSize="8" textAnchor="middle" fontFamily={MONO}>{axisLabel(p.label)}</text>}
                        </g>
                    ))}
                </svg>
            </div>
        </div>
    );
};

window.SplitsTab = SplitsTab;
window.TrendChart = TrendChart;


// ---------- ShootingTab.js ----------
// 投籃分頁：讀 shotchart 逐球資料 → 距離區間/分區/出手方式卡片牆（期間 vs 全季）
//   + 受助攻卡（全季快照）+ 篩選熱圖 + 點卡片展開趨勢折線
// gameMeta：{date:{wl,matchup}}，供勝敗/主客篩選（出手本身只帶 gdate）
const ShootingTab = ({ playerId, teamMode, season, typeKey, playerName, seasonLabel, gameMeta }) => {
    const { useState, useEffect } = React;
    const TrendChart = window.TrendChart;
    const ShotChart = window.ShotChart;

    const [doc, setDoc] = useState(undefined); // undefined=載入中, null=無, {shots,assisted}
    const [period, setPeriod] = useState('all');
    const [monthKey, setMonthKey] = useState('');
    const [rangeStart, setRangeStart] = useState('');
    const [rangeEnd, setRangeEnd] = useState('');
    const [group, setGroup] = useState('dist');
    const [openKey, setOpenKey] = useState(null);
    const [gran, setGran] = useState('game');
    const shootLedgerRef = React.useRef(null);   // 匯出命中率格用（hook 須在提早 return 之前）

    const idPart = teamMode ? 'TEAM' : playerId;

    useEffect(() => {
        if ((!playerId && !teamMode) || !season || !typeKey || !window.db || !window.firebaseModules) return;
        let cancelled = false;
        setDoc(undefined);
        (async () => {
            const cache = (window.__shootTabCache = window.__shootTabCache || {});
            const docId = `${idPart}_${season}_${typeKey}`;
            if (cache[docId] !== undefined) { if (!cancelled) setDoc(cache[docId]); return; }
            const { doc: docFn, getDoc } = window.firebaseModules;
            try {
                const snap = await getDoc(docFn(window.db, 'wolves_shotcharts', docId));
                let v = null;
                if (snap.exists()) {
                    const d = snap.data();
                    const at = d.actionTypes || [], gd = d.gameDates || [];
                    v = {
                        shots: (d.shots || []).map(s => ({ x: s.x, y: s.y, made: s.made, dist: s.dist, zone: s.zone, action: at[s.a], gdate: gd[s.g] })),
                        assisted: d.assisted || {},
                    };
                }
                cache[docId] = v;
                if (!cancelled) setDoc(v);
            } catch (e) { console.error('shooting doc fail', docId, e); if (!cancelled) setDoc(null); }
        })();
        return () => { cancelled = true; };
    }, [idPart, season, typeKey]);

    const UI = window.UI;
    if (doc === undefined) return <div className="py-10 text-center text-sm text-slate-500 animate-pulse">載入投籃資料中…</div>;
    if (doc === null || !doc.shots.length) return <UI.Note>此賽季尚無逐球投籃資料（每週更新，且僅近幾季有）</UI.Note>;

    const allShots = doc.shots;
    const dates = [...new Set(allShots.map(s => s.gdate))].sort();
    const months = [...new Set(dates.map(d => d.slice(0, 7)))].sort();
    const meta = gameMeta || {};

    // 期間篩選
    let periodShots = allShots, periodLabel = '全季';
    if (period === 'month' && monthKey) { periodShots = allShots.filter(s => (s.gdate || '').slice(0, 7) === monthKey); periodLabel = monthKey; }
    else if (period === 'last5' || period === 'last10') { const n = period === 'last5' ? 5 : 10; const set = new Set(dates.slice(-n)); periodShots = allShots.filter(s => set.has(s.gdate)); periodLabel = `近 ${n} 場`; }
    else if (period === 'range') { periodShots = allShots.filter(s => (!rangeStart || s.gdate >= rangeStart) && (!rangeEnd || s.gdate <= rangeEnd)); periodLabel = `${rangeStart || '起'}~${rangeEnd || '訖'}`; }
    else if (period === 'W' || period === 'L') { periodShots = allShots.filter(s => (meta[s.gdate] || {}).wl === period); periodLabel = period === 'W' ? '勝場' : '敗場'; }
    else if (period === 'home') { periodShots = allShots.filter(s => ((meta[s.gdate] || {}).matchup || '').includes('vs.')); periodLabel = '主場'; }
    else if (period === 'away') { periodShots = allShots.filter(s => ((meta[s.gdate] || {}).matchup || '').includes('@')); periodLabel = '客場'; }

    // 分組定義
    const DIST_BINS = [[0, 4, '0-4 呎'], [5, 9, '5-9 呎'], [10, 14, '10-14 呎'], [15, 19, '15-19 呎'], [20, 24, '20-24 呎'], [25, 29, '25-29 呎'], [30, 999, '30 呎+']];
    const ZONE_DEFS = [
        ['RA', '合理衝撞區', z => z === 'Restricted Area', 'Restricted Area'],
        ['PAINT', '禁區（非 RA）', z => z === 'In The Paint (Non-RA)', 'In The Paint (Non-RA)'],
        ['MID', '中距離', z => z === 'Mid-Range', 'Mid-Range'],
        ['C3', '底角三分', z => z === 'Left Corner 3' || z === 'Right Corner 3', 'Corner 3'],
        ['AB3', '非底角三分', z => z === 'Above the Break 3', 'Above the Break 3'],
    ];
    const topTypes = (() => {
        const cnt = {};
        allShots.forEach(s => { if (s.action) cnt[s.action] = (cnt[s.action] || 0) + 1; });
        return Object.keys(cnt).sort((a, b) => cnt[b] - cnt[a]).slice(0, 8);
    })();

    // FG% 計算：filterFn 套用於一組 shots
    const calc = (shots, fn) => { const f = shots.filter(fn); const m = f.filter(s => s.made === 1).length; return { fga: f.length, pct: f.length ? +(100 * m / f.length).toFixed(1) : null }; };

    // 目前分組的項目清單 [{key,label,fn}]
    const items = group === 'dist'
        ? DIST_BINS.map(([lo, hi, l]) => ({ key: `d${lo}`, label: l, fn: s => s.dist >= lo && s.dist <= hi }))
        : group === 'zone'
            ? ZONE_DEFS.map(([k, l, fn, en]) => ({ key: k, label: l, en, fn: s => fn(s.zone) }))
            : topTypes.map(t => ({ key: t, label: t, fn: s => s.action === t }));

    const periodTotal = periodShots.length;

    // 趨勢：某項目 FG% 依粒度（逐場/每週/每月）over 全季
    const weekKey = d => { const dt = new Date(d + 'T00:00:00'); const day = (dt.getDay() + 6) % 7; dt.setDate(dt.getDate() - day); return dt.toISOString().slice(0, 10); };
    const trendFor = (fn) => {
        const groups = {};
        allShots.filter(fn).forEach(s => {
            const k = gran === 'week' ? weekKey(s.gdate) : gran === 'month' ? (s.gdate || '').slice(0, 7) : s.gdate;
            (groups[k] = groups[k] || []).push(s);
        });
        // 逐場的點帶 wl（gameMeta）→ 走勢鋪勝負底色
        return Object.keys(groups).sort().map(k => { const g = groups[k]; const m = g.filter(s => s.made === 1).length; const wl = gran === 'game' ? (meta[k] || {}).wl : null;
            return { label: k, value: g.length ? +(100 * m / g.length).toFixed(1) : 0, ...(wl ? { wl } : {}) }; });
    };
    const openItem = items.find(it => it.key === openKey);
    const trendPts = openItem ? trendFor(openItem.fn) : [];
    const trendBaseline = openItem ? calc(allShots, openItem.fn).pct : null;

    const assisted = doc.assisted || {};
    const GROUPS = [['dist', '距離區間', 'Distance'], ['zone', '分區', 'Zone'], ['type', '出手方式', 'Shot Type']];
    const groupInfo = GROUPS.find(g => g[0] === group) || GROUPS[0];

    return (
        <div className="space-y-10">
            {/* 篩選列：期間（影響命中率格與熱圖；受助攻為全季快照不受影響） */}
            <div className="space-y-2.5">
                <div className="flex flex-wrap items-center gap-1.5">
                    <span className="mr-1 text-[11px] text-slate-500">期間</span>
                    <UI.Chip active={period === 'all'} onClick={() => setPeriod('all')}>全季</UI.Chip>
                    <UI.Chip active={period === 'W'} onClick={() => setPeriod('W')}>勝場</UI.Chip>
                    <UI.Chip active={period === 'L'} onClick={() => setPeriod('L')}>敗場</UI.Chip>
                    <UI.Chip active={period === 'home'} onClick={() => setPeriod('home')}>主場</UI.Chip>
                    <UI.Chip active={period === 'away'} onClick={() => setPeriod('away')}>客場</UI.Chip>
                    <UI.Chip active={period === 'last5'} onClick={() => setPeriod('last5')}>近 5 場</UI.Chip>
                    <UI.Chip active={period === 'last10'} onClick={() => setPeriod('last10')}>近 10 場</UI.Chip>
                    <label className="sr-only" htmlFor="shoot-month">選擇月份</label>
                    <select id="shoot-month" value={period === 'month' ? monthKey : ''} onChange={e => { setPeriod('month'); setMonthKey(e.target.value); }}
                        className={UI.selectClass(period === 'month')}>
                        <option value="">每月</option>
                        {months.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                    <UI.Chip active={period === 'range'} onClick={() => setPeriod('range')}>自訂區間</UI.Chip>
                </div>
                {period === 'range' && (
                    <div className="flex items-center gap-2 text-xs text-slate-400">
                        <input type="date" aria-label="起始日" value={rangeStart} onChange={e => setRangeStart(e.target.value)} className={UI.selectClass(!!rangeStart)} />
                        <span>~</span>
                        <input type="date" aria-label="結束日" value={rangeEnd} onChange={e => setRangeEnd(e.target.value)} className={UI.selectClass(!!rangeEnd)} />
                    </div>
                )}
            </div>

            <UI.Section title={`${groupInfo[1]}命中率`} en={`FG% by ${groupInfo[2]}`} accent="green"
                sub={`${periodLabel}（${periodTotal} 出手，vs 全季 ${allShots.length}）· 大字＝命中率，箭頭為 vs 全季 · 小字＝出手數／佔比 · 點格子看趨勢`}
                right={<>
                    <UI.ExportMenu title={`${groupInfo[1]}命中率（${periodLabel}）`} getNode={() => shootLedgerRef.current}
                        csv={() => ({ header: [groupInfo[1], '原文', `${periodLabel}命中率%`, `${periodLabel}出手`, '全季命中率%', '全季出手'],
                            rows: items.map(it => { const p = calc(periodShots, it.fn), a = calc(allShots, it.fn); return [it.label, it.en || '', p.pct == null ? '' : p.pct, p.fga, a.pct == null ? '' : a.pct, a.fga]; }) })} />
                    <UI.Seg ariaLabel="分組" size="sm" value={group} onChange={(g) => { setGroup(g); setOpenKey(null); }}
                        options={GROUPS.map(([v, l]) => ({ value: v, label: l }))} />
                </>}>
                <div ref={shootLedgerRef}>
                <UI.Ledger cols={UI.ledgerCols(items.length)}>
                    {items.map(it => {
                        const p = calc(periodShots, it.fn), a = calc(allShots, it.fn);
                        const freq = periodTotal ? Math.round(100 * p.fga / periodTotal) : 0;
                        const open = openKey === it.key;
                        return (
                            <button key={it.key} type="button" aria-pressed={open} onClick={() => setOpenKey(open ? null : it.key)}
                                className={`border-r border-b border-white/[0.08] px-3 pt-2.5 pb-3 min-w-0 text-left transition-colors ${open ? 'bg-[#12A150]/[0.08] shadow-[inset_0_-2px_0_#12A150]' : 'hover:bg-white/[0.03]'}`}>
                                <div className="text-[11px] leading-tight text-slate-300 truncate" title={it.en ? `${it.label} · ${it.en}` : it.label}>{it.label}</div>
                                {it.en && <div className="font-mono text-[10px] leading-tight text-slate-500 truncate">{it.en}</div>}
                                <div className="mt-2 flex items-baseline gap-1.5 min-w-0">
                                    <span className={`font-display text-[26px] font-semibold leading-none tabular-nums ${p.pct != null ? 'text-slate-50' : 'text-slate-600'}`}>
                                        {p.pct != null ? p.pct : '—'}{p.pct != null && <span className="ml-0.5 text-[15px] font-medium text-slate-400">%</span>}
                                    </span>
                                    {period !== 'all' && <span className="ml-auto"><UI.Delta value={p.pct} prevValue={a.pct} /></span>}
                                </div>
                                <div className="mt-1.5 font-mono text-[10px] text-slate-500">{p.fga} 出手 · 佔 {freq}%</div>
                            </button>
                        );
                    })}
                </UI.Ledger>
                </div>

                {/* 趨勢折線 */}
                {openItem && TrendChart && (
                    <div className="mt-4 border border-white/10 p-4">
                        <div className="mb-3 flex flex-wrap items-center gap-3">
                            <span className="text-[13px] font-medium text-slate-100">{openItem.label} 命中率趨勢</span>
                            <UI.Seg ariaLabel="趨勢粒度" size="sm" value={gran} onChange={setGran}
                                options={[{ value: 'game', label: '逐場' }, { value: 'week', label: '每週' }, { value: 'month', label: '每月' }]} />
                        </div>
                        <TrendChart points={trendPts} baseline={trendBaseline} unit="%"
                            title={`${openItem.label}命中率趨勢（${gran === 'game' ? '逐場' : gran === 'week' ? '每週' : '每月'}）`} />
                    </div>
                )}
            </UI.Section>

            {/* 受助攻（全季快照，不隨篩選） */}
            {Object.keys(assisted).length > 0 && (
                <UI.Section title="受助攻比例" en="Assisted FGM%" accent="blue" sub="命中球中由隊友助攻的比例 · 全季快照，不受上方期間篩選影響">
                    <UI.Ledger cols="grid-cols-3">
                        {[['整體受助攻', 'All FGM', 'PCT_AST_FGM'], ['兩分受助攻', '2PM', 'PCT_AST_2PM'], ['三分受助攻', '3PM', 'PCT_AST_3PM']].map(([l, en, k]) => (
                            <UI.StatCell key={k} label={l} en={en} value={typeof assisted[k] === 'number' ? assisted[k] : null} unit="%"
                                gkey={k} citeAsOf="none" citeNote="全季（每週更新）" />
                        ))}
                    </UI.Ledger>
                </UI.Section>
            )}

            {/* 篩選後熱圖 */}
            {ShotChart && (
                <ShotChart playerId={playerId} teamMode={teamMode} playerName={playerName} externalShots={periodShots} periodLabel={periodLabel} />
            )}
        </div>
    );
};

window.ShootingTab = ShootingTab;


// ---------- SeasonPaceChart.js ----------
// 疊圖元件（跨季章節用）
//   LineOverlay：通用多序列 SVG 折線（十字線提示、末端標籤、他隊季別空心點＋虛線）
//   SeasonPaceChart：賽季軌跡疊圖——各季逐場 bundle 以「出賽第 N 場」對齊，看今年同期 vs 往年
//
// LineOverlay props：
//   xs        X 軸標籤（陣列）
//   series    [{ key, label, color, values:[number|null], dashed?, width?, hollow?:[bool], tags?:[string] }]
//             hollow/tags 為逐點：他隊季別畫空心點、點上方標 @隊名，相鄰任一端為他隊的線段改虛線
//   unit      '%' 時數值後接 %；fmt 自訂數值格式
//   marker    { index, label } 垂直參考線（如「今年第 34 場」）
//   mini      小圖並排用：不畫 Y 軸刻度、末端標籤只標數值
//   xEvery    X 軸每幾個標一次（預設依點數自動）
const LineOverlay = ({ xs, series, unit = '', fmt, marker, mini = false, height, xEvery, ariaLabel = '疊圖折線' }) => {
    const { useState, useRef } = React;
    const [hover, setHover] = useState(null);
    const svgRef = useRef(null);
    const W = mini ? 300 : 960, H = height || (mini ? 120 : 320);
    const pL = mini ? 8 : 44, pR = mini ? 10 : 96, pT = mini ? 12 : 18, pB = mini ? 18 : 28;
    const n = xs.length;
    const all = series.flatMap(s => s.values).filter(v => typeof v === 'number');
    if (!n || !all.length) return <div className="py-8 text-center text-xs text-slate-500">資料不足，無法繪製</div>;
    let lo = Math.min(...all), hi = Math.max(...all);
    if (lo === hi) { lo -= 1; hi += 1; }
    const pad = (hi - lo) * 0.1; lo -= pad; hi += pad;
    const x = i => pL + (n === 1 ? (W - pL - pR) / 2 : i * (W - pL - pR) / (n - 1));
    const y = v => pT + (H - pT - pB) * (1 - (v - lo) / (hi - lo));
    const f = v => (fmt ? fmt(v) : (Number.isInteger(v) ? String(v) : v.toFixed(1))) + unit;
    const MONO = "'JetBrains Mono', monospace";
    const every = xEvery || (n <= 8 ? 1 : n <= 20 ? 2 : 10);
    const onMove = (e) => {
        const r = svgRef.current.getBoundingClientRect();
        const sx = (e.clientX - r.left) * W / r.width;
        setHover({ i: Math.max(0, Math.min(n - 1, Math.round((sx - pL) / ((W - pL - pR) / Math.max(1, n - 1))))), px: e.clientX - r.left, w: r.width });
    };
    // 末端標籤：各序列最後一個有值的點，依 y 排開避免重疊
    const ends = series.map(s => { let i = s.values.length - 1; while (i >= 0 && typeof s.values[i] !== 'number') i--; return i >= 0 ? { s, i, yy: y(s.values[i]) } : null; }).filter(Boolean)
        .sort((a, b) => a.yy - b.yy);
    for (let k = 1; k < ends.length; k++) if (ends[k].yy - ends[k - 1].yy < 12) ends[k].yy = ends[k - 1].yy + 12;
    return (
        <div className="relative">
            <div className="overflow-x-auto">
                <svg ref={svgRef} viewBox={`0 0 ${W} ${H}`} className="w-full" style={{ minWidth: mini ? 0 : 560 }} role="img" aria-label={ariaLabel}
                    onMouseMove={mini ? undefined : onMove} onMouseLeave={() => setHover(null)}>
                    {!mini && [0, 0.25, 0.5, 0.75, 1].map(t => { const v = lo + (hi - lo) * (1 - t), yy = pT + t * (H - pT - pB); return (
                        <g key={t}><line x1={pL} x2={W - pR} y1={yy} y2={yy} stroke="rgba(255,255,255,0.07)" />
                            <text x={pL - 6} y={yy + 3} fill="#7C8B9C" fontSize="10" textAnchor="end" fontFamily={MONO}>{v.toFixed(1)}</text></g>); })}
                    {xs.map((l, i) => (i % every === 0 || i === n - 1) && (
                        <text key={i} x={x(i)} y={H - (mini ? 4 : 9)} fill="#7C8B9C" fontSize={mini ? 9 : 10} textAnchor="middle" fontFamily={MONO}>{l}</text>
                    ))}
                    {marker && marker.index >= 0 && marker.index < n && (<g>
                        <line x1={x(marker.index)} x2={x(marker.index)} y1={pT} y2={H - pB} stroke="rgba(18,161,80,0.4)" />
                        {!mini && <text x={x(marker.index) + 4} y={pT + 10} fill="#12A150" fontSize="10" fontFamily={MONO}>{marker.label}</text>}
                    </g>)}
                    {/* 舊序列先畫、第一個（主角）最後畫在最上層 */}
                    {series.slice().reverse().map(s => {
                        const segs = [];
                        for (let i = 1; i < s.values.length; i++) {
                            const a = s.values[i - 1], b = s.values[i];
                            if (typeof a !== 'number' || typeof b !== 'number') continue;
                            const other = (s.hollow || [])[i - 1] || (s.hollow || [])[i];
                            segs.push(<line key={i} x1={x(i - 1)} y1={y(a)} x2={x(i)} y2={y(b)} stroke={s.color} strokeWidth={s.width || 2}
                                strokeDasharray={s.dashed || other ? '5 4' : undefined} strokeOpacity={other ? 0.6 : (s.opacity || 1)} strokeLinecap="round" />);
                        }
                        const dots = n <= 30 ? s.values.map((v, i) => typeof v === 'number' && (
                            <g key={'d' + i}>
                                <circle cx={x(i)} cy={y(v)} r={mini ? 2.5 : 3.5} fill={(s.hollow || [])[i] ? '#0A1626' : s.color} stroke={s.color} strokeWidth="1.5" />
                                {!mini && (s.tags || [])[i] && <text x={x(i)} y={y(v) - 8} fill="#FBBF24" fillOpacity="0.85" fontSize="9" textAnchor="middle" fontFamily={MONO}>{s.tags[i]}</text>}
                            </g>)) : null;
                        return <g key={s.key}>{segs}{dots}</g>;
                    })}
                    {ends.map(({ s, i, yy }) => (
                        <text key={'e' + s.key} x={mini ? x(i) - 4 : W - pR + 6} y={(mini ? y(s.values[i]) - 6 : yy + 3)} fill={s.color} fontSize="10"
                            textAnchor={mini ? 'end' : 'start'} fontFamily={MONO}>{mini ? f(s.values[i]) : `${s.label} ${f(s.values[i])}`}</text>
                    ))}
                    {hover && (<g pointerEvents="none">
                        <line x1={x(hover.i)} x2={x(hover.i)} y1={pT} y2={H - pB} stroke="rgba(232,237,240,0.45)" />
                        {series.map(s => typeof s.values[hover.i] === 'number' && <circle key={s.key} cx={x(hover.i)} cy={y(s.values[hover.i])} r="4" fill={s.color} />)}
                    </g>)}
                </svg>
            </div>
            {hover && (
                <div className="pointer-events-none absolute top-3 z-10 min-w-[150px] border border-white/20 bg-[#0E1D33]/95 px-2.5 py-2 text-[12px]"
                    style={{ left: hover.px > hover.w - 200 ? Math.max(0, hover.px - 180) : hover.px + 14 }}>
                    <div className="mb-1 font-mono text-[10px] text-slate-500">{xs[hover.i]}</div>
                    {series.map(s => (
                        <div key={s.key} className="flex justify-between gap-4 font-mono">
                            <span className="flex items-center gap-1.5 text-slate-300"><i className="inline-block h-[3px] w-2.5" style={{ background: s.color }}></i>{s.label}</span>
                            <span className="text-slate-100">{typeof s.values[hover.i] === 'number' ? f(s.values[hover.i]) : '—'}{(s.tags || [])[hover.i] ? ` ${s.tags[hover.i]}` : ''}</span>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

// ── 賽季軌跡疊圖 ──
// 各季逐場 bundle 依日期排序後，第 i 場＝該員（或球隊）該季第 i+1 場出賽；球員是「出賽場次」不是球隊場次
const PACE_COLORS = ['#12A150', '#C4CED2', '#5B9BD5', '#F59E0B', '#A78BFA'];
const SeasonPaceChart = ({ viewMode, playerId, playerName }) => {
    const { useState, useEffect, useMemo, useRef } = React;
    const UI = window.UI, GA = window.GameAgg;
    const phase = window.getSeasonPhase ? window.getSeasonPhase() : { inSeason: false, type: 'regular' };
    const [type, setType] = useState(phase.inSeason && phase.type === 'playoffs' ? 'playoffs' : 'regular');
    const [metric, setMetric] = useState('PTS');
    const [mode, setMode] = useState('cum');
    const [off, setOff] = useState([]);          // 使用者關掉的賽季
    const [data, setData] = useState({});        // { season: games[] }
    const [loading, setLoading] = useState(true);
    const chartRef = useRef(null);

    const seasons = useMemo(() => [...new Set([window.CURRENT_SEASON, ...(window.HISTORY_SEASONS || [])])].sort().reverse(), []);
    const isTeam = viewMode === 'TEAM';

    useEffect(() => {
        if (!window.loadSeasonGames || (!isTeam && !playerId)) { setData({}); setLoading(false); return; }
        let cancelled = false;
        setLoading(true);
        Promise.all(seasons.map(s => window.loadSeasonGames(s, type, viewMode, isTeam ? null : playerId)
            .then(({ games }) => [s, (games || []).slice().sort((a, b) => (a.date < b.date ? -1 : 1))])))
            .then(pairs => { if (!cancelled) { setData(Object.fromEntries(pairs)); setLoading(false); } });
        return () => { cancelled = true; };
    }, [type, viewMode, playerId]);

    // 指標選單：沿用 defs（Playtype／On-Off 沒有逐場資料，不列）
    const GROUPS = [
        ['基本', [window.SPLITS_BASE_DEF]],
        ['進階', window.trackingDefs || []],
        ['投籃分區', (window.shootingDefs || []).filter(d => d.id === 'ShotZones')],
        ['防守', (window.defenseDefs || []).filter(d => d.id === 'MatchupDefense' || d.id === 'Hustle')],
    ];
    const allMetrics = GROUPS.flatMap(([, defs]) => defs.filter(Boolean).flatMap(d => d.metrics));
    const m = allMetrics.find(x => x.key === metric) || allMetrics[0];
    const pct = m.unit === '%';

    const withData = seasons.filter(s => (data[s] || []).length);
    const shown = withData.filter(s => !off.includes(s));
    const colorOf = s => PACE_COLORS[seasons.indexOf(s) % PACE_COLORS.length];
    const valuesOf = (games) => games.map((_, i) => {
        if (mode === 'game') return GA.metricOf([games[i]], null, 'TEAM', metric);
        if (mode === 'roll') return i < 9 ? null : GA.metricOf(games.slice(i - 9, i + 1), null, 'TEAM', metric);
        return GA.metricOf(games.slice(0, i + 1), null, 'TEAM', metric);
    });
    const series = useMemo(() => shown.map(s => ({
        key: s, label: s.slice(2), color: colorOf(s), values: valuesOf(data[s]),
        width: s === shown[0] ? 2.6 : 1.5, opacity: mode === 'game' && s !== shown[0] ? 0.5 : 0.85,
    })), [data, shown.join(), metric, mode]);
    const maxN = Math.max(0, ...shown.map(s => data[s].length));
    const xs = Array.from({ length: maxN }, (_, i) => String(i + 1));

    // 同期：以最新一季（有資料者）已出賽場數為 N
    const ref = withData[0];
    const N = ref ? data[ref].length : 0;
    const inProgress = ref === window.CURRENT_SEASON && phase.inSeason;
    const cumAt = (s, k) => GA.metricOf(data[s].slice(0, k), null, 'TEAM', metric);
    const rows = withData.map(s => {
        const g = data[s], k = Math.min(N, g.length);
        const w = g.slice(0, k).filter(x => x.wl === 'W').length;
        return { s, v: cumAt(s, k), final: cumAt(s, g.length), rec: `${w}-${k - w}`, n: k, total: g.length };
    });
    const refV = rows.length ? rows[0].v : null;
    const fv = v => typeof v === 'number' ? v.toFixed(1) + (pct ? '%' : '') : '—';
    const modeLabel = { cum: '累積季平均', roll: '近 10 場移動平均', game: '逐場' }[mode];
    const typeLabel = type === 'playoffs' ? '季後賽' : '例行賽';
    const subject = isTeam ? '灰狼全隊' : playerName;

    const fbText = () => [
        `【${subject}｜${typeLabel}前 ${N} 場${m.label}・跨季同期比較】`,
        '',
        ...rows.map(r => `${r.s}｜前 ${r.n} 場 ${fv(r.v)}${r.s === ref ? '（最新）' : ''}｜${r.s === ref ? '' : `全季 ${fv(r.final)}｜`}戰績 ${r.rec}`),
        '',
        `${m.label}${m.englishLabel ? `（${m.englishLabel}）` : ''}以 Σ 加權重算；${isTeam ? '球隊場次' : '球員出賽場次'}對齊`,
        '資料：NBA.com Stats 逐場',
        `${location.origin}${location.pathname}${location.hash}`,
    ].join('\n');
    const csv = () => ({ header: [isTeam ? '球隊第N場' : '出賽第N場', ...series.map(s => s.key)], rows: xs.map((x, i) => [x, ...series.map(s => s.values[i] == null ? '' : s.values[i])]) });

    return (
        <UI.Section title="賽季軌跡疊圖" en="Season Pace" accent="green"
            sub={`各季以「${isTeam ? '球隊第 N 場' : '出賽第 N 場'}」對齊，看今年打到這裡和往年同期比 · 百分比以 Σ命中 ÷ Σ出手 重算 · 只列有逐場資料的賽季`}
            right={<UI.ExportMenu title={`賽季軌跡：${subject} ${m.label}（${typeLabel}・${modeLabel}）`} getNode={() => chartRef.current} csv={csv} text={fbText} />}>
            <div className="mb-3 flex flex-wrap items-center gap-x-4 gap-y-2">
                <label className="sr-only" htmlFor="pace-metric">指標</label>
                <select id="pace-metric" value={metric} onChange={e => setMetric(e.target.value)} className={UI.selectClass(true)}>
                    {GROUPS.map(([g, defs]) => (
                        <optgroup key={g} label={g}>
                            {defs.filter(Boolean).flatMap(d => d.metrics).map(x => <option key={x.key} value={x.key}>{x.label}{x.englishLabel ? ` · ${x.englishLabel}` : ''}</option>)}
                        </optgroup>
                    ))}
                </select>
                <UI.Seg ariaLabel="算法" size="sm" value={mode} onChange={setMode}
                    options={[{ value: 'cum', label: '累積季平均' }, { value: 'roll', label: '近 10 場' }, { value: 'game', label: '逐場' }]} />
                <UI.Seg ariaLabel="賽別" size="sm" value={type} onChange={setType}
                    options={[{ value: 'regular', label: '例行賽' }, { value: 'playoffs', label: '季後賽' }]} />
            </div>
            <div className="mb-3 flex flex-wrap items-center gap-1.5">
                <span className="mr-1 text-[11px] text-slate-500">賽季</span>
                {seasons.map(s => {
                    const has = (data[s] || []).length > 0, on = has && !off.includes(s);
                    return (
                        <button key={s} type="button" disabled={!has} aria-pressed={on}
                            title={has ? `${data[s].length} 場` : '這一季沒有逐場資料（尚未回補）'}
                            onClick={() => setOff(o => o.includes(s) ? o.filter(x => x !== s) : (shown.length > 1 ? [...o, s] : o))}
                            className={`inline-flex min-h-[24px] items-center gap-1.5 rounded-full border px-3 py-1 text-xs ${!has ? 'border-white/10 text-slate-600 cursor-not-allowed' : on ? 'bg-white/[0.04] text-slate-100' : 'border-white/15 text-slate-500'}`}
                            style={on ? { borderColor: colorOf(s) } : undefined}>
                            <i className="inline-block h-[3px] w-3.5" style={{ background: has ? colorOf(s) : '#475569', opacity: on ? 1 : 0.35 }}></i>
                            {s}{s === window.CURRENT_SEASON && phase.inSeason ? '（進行中）' : ''}{!has ? ' · 無資料' : ''}
                        </button>
                    );
                })}
            </div>
            {loading ? <div className="py-10 text-center text-sm text-slate-500 animate-pulse">載入各季逐場資料中…</div>
                : !shown.length ? <UI.Note>{isTeam ? '' : `${playerName} `}這個賽別沒有任何一季的逐場資料</UI.Note>
                : (
                    <div ref={chartRef}>
                        <LineOverlay xs={xs} series={series} unit={pct ? '%' : ''} ariaLabel={`${m.label} 賽季軌跡疊圖`}
                            marker={inProgress && N < maxN ? { index: N - 1, label: `今年第 ${N} 場` } : null} />
                        <div className="mt-4 overflow-x-auto border-t border-white/[0.08]">
                            <table className="w-full border-collapse text-[13px]">
                                <caption className="sr-only">同期比較</caption>
                                <thead><tr className="border-b border-white/15">
                                    {['賽季', `前 ${N} 場${m.label}`, `與 ${ref ? ref.slice(2) : ''} 差`, '全季終值', `前 ${N} 場戰績`].map((h, i) => (
                                        <th key={i} scope="col" className={`px-3 py-2 font-mono text-[10px] font-normal text-slate-500 whitespace-nowrap ${i ? 'text-right' : 'text-left'}`}>{h}</th>
                                    ))}
                                </tr></thead>
                                <tbody>{rows.map(r => {
                                    const d = r.s === ref || typeof r.v !== 'number' || typeof refV !== 'number' ? null : refV - r.v;
                                    const better = d == null ? null : (d >= 0) === (m.betterIsLarger !== false);
                                    return (
                                        <tr key={r.s} className="border-b border-white/[0.06]">
                                            <th scope="row" className="px-3 py-2 text-left font-normal whitespace-nowrap">
                                                <i className="mr-2 inline-block h-[3px] w-3 align-middle" style={{ background: colorOf(r.s) }}></i>{r.s}
                                                {r.n < N && <span className="ml-1.5 font-mono text-[10px] text-slate-500">（該季只有 {r.n} 場）</span>}
                                            </th>
                                            <td className="px-3 py-2 text-right font-mono tabular-nums">{fv(r.v)}</td>
                                            <td className={`px-3 py-2 text-right font-mono tabular-nums ${d == null || m.neutral ? 'text-slate-500' : better ? 'text-[#12A150]' : 'text-[#EF4444]'}`}>
                                                {d == null ? '—' : `${ref.slice(2)} ${d >= 0 ? '+' : ''}${d.toFixed(1)}`}
                                            </td>
                                            <td className="px-3 py-2 text-right font-mono tabular-nums">{r.s === ref && inProgress ? <span className="text-slate-500">進行中</span> : fv(r.final)}</td>
                                            <td className="px-3 py-2 text-right font-mono tabular-nums">{r.rec}</td>
                                        </tr>
                                    );
                                })}</tbody>
                            </table>
                        </div>
                        <p className="mt-2 text-[11px] text-slate-500">
                            滑鼠移到圖上看各季同一場次的數值 · 「差」以最新一季為基準，綠＝最新一季較好（依指標方向；次數類不標色）
                            {!isTeam && ' · 球員以「出賽第 N 場」對齊，缺席的比賽不算'}
                        </p>
                    </div>
                )}
        </UI.Section>
    );
};

window.LineOverlay = LineOverlay;
window.SeasonPaceChart = SeasonPaceChart;


// ---------- ComparisonTab.js ----------
// 跨季比較分頁：賽季軌跡疊圖（逐場對齊）＋ 多選賽季 × 數據類別 → 並列各季終點值表格 + 點指標畫逐季折線
// seasons：可選賽季清單 [{key,label,short,order}]；loadSeason(key)→{team,player}（normalized）
// 逐季折線：單一指標可疊加其他球員／全隊（他隊季別空心點＋@隊名）；多選指標改小圖並排或指數化疊圖
const ComparisonTab = ({ viewMode, selectedPlayer, playerId, seasons, loadSeason }) => {
    const { useState, useEffect } = React;
    const trackingDefs = window.trackingDefs || [];
    const shootingDefs = window.shootingDefs || [];
    const defenseDefs = window.defenseDefs || [];
    const PLAY = window.PlayTypesList || [];
    const LineOverlay = window.LineOverlay;

    const [selected, setSelected] = useState([]);
    const [data, setData] = useState({});
    const [cat, setCat] = useState('base');
    const [openKeys, setOpenKeys] = useState([]);      // 點選的指標 key（可多選，最多 MAX_OPEN）
    const [extras, setExtras] = useState([]);          // 疊加比較的其他球員名；'__TEAM__'＝全隊
    const [multiMode, setMultiMode] = useState('small'); // 多指標：small 小圖並排／index 指數化疊圖
    const chartRef = React.useRef(null);
    const MAX_OPEN = 8, MAX_EXTRAS = 3, TEAM = '__TEAM__';
    const tableRef = React.useRef(null);

    // 預設選最近兩季
    useEffect(() => {
        if (!selected.length && seasons.length) setSelected(seasons.slice(0, 2).map(s => s.key));
    }, [seasons]);

    // 載入選取賽季資料
    useEffect(() => {
        let cancelled = false;
        selected.forEach(async k => {
            if (data[k]) return;
            // loadSeason 會往上拋錯（呼叫端需區分「載入失敗」與「查無資料」），
            // 這裡必須接住，否則網路異常會變成 unhandled rejection 讓分頁卡在載入中。
            // 失敗時刻意「不寫入 data」：寫進去會讓 `if (data[k]) return` 永久命中，
            // 使用者再也不會重試，整欄卡在「—」直到重整頁面
            let v;
            try { v = await loadSeason(k); }
            catch (e) { console.error('comparison season load fail', k, e); return; }
            if (!cancelled) setData(prev => prev[k] ? prev : { ...prev, [k]: v || { team: null, player: null } });
        });
        return () => { cancelled = true; };
    }, [selected]);

    const flat = defs => defs.reduce((a, d) => a.concat(d.metrics.map(m => ({ k: m.key, l: m.label, e: m.englishLabel, pct: m.unit === '%' }))), []);
    const CATS = {
        base: { label: '基本', metrics: [
            { k: 'PTS', l: '得分', e: 'PTS' }, { k: 'REB', l: '籃板', e: 'REB' }, { k: 'AST', l: '助攻', e: 'AST' },
            { k: 'FG_PCT', l: '命中率', e: 'FG%', pct: true }, { k: 'FG3_PCT', l: '三分命中率', e: '3P%', pct: true }, { k: 'FT_PCT', l: '罰球命中率', e: 'FT%', pct: true },
            { k: 'STL', l: '抄截', e: 'STL' }, { k: 'BLK', l: '阻攻', e: 'BLK' }, { k: 'TOV', l: '失誤', e: 'TOV' }, { k: 'PLUS_MINUS', l: '正負值', e: '+/-' },
        ] },
        playtype: { label: 'Playtype', metrics: PLAY.map(t => ({ k: t, l: t, e: '進攻 PPP', playtype: true })) },
        tracking: { label: '進階', metrics: flat(trackingDefs) },
        shooting: { label: '投籃', metrics: ((shootingDefs.find(d => d.id === 'ShotZones') || {}).metrics || []).map(m => ({ k: m.key, l: m.label, e: m.englishLabel, pct: true })) },
        defense: { label: '防守', metrics: flat(defenseDefs) },
        onoff: { label: 'On/Off', playerOnly: true, metrics: [
            { k: 'ON_NET_RATING', l: '在場淨效率', e: 'On NetRtg' }, { k: 'OFF_NET_RATING', l: '不在場淨效率', e: 'Off NetRtg' },
            { k: 'ON_OFF_RATING', l: '在場進攻效率', e: 'On OffRtg' }, { k: 'ON_DEF_RATING', l: '在場防守效率', e: 'On DefRtg' },
        ] },
    };
    const catKeys = Object.keys(CATS).filter(c => !(CATS[c].playerOnly && viewMode === 'TEAM'));
    const activeCat = catKeys.includes(cat) ? cat : 'base';
    const metrics = CATS[activeCat].metrics;

    // 選取的賽季（依 order 排序，供折線 X 軸）
    const cols = seasons.filter(s => selected.includes(s.key)).sort((a, b) => a.order - b.order);

    // who：省略＝頁面主角（全隊或 selectedPlayer）；TEAM＝全隊；其他字串＝該球員
    const getVal = (key, m, who) => {
        const sd = data[key];
        if (!sd) return null;
        const isTeam = who === TEAM || (!who && viewMode === 'TEAM');
        const pname = who && who !== TEAM ? who : selectedPlayer;
        if (m.playtype) {
            const arr = isTeam ? (sd.team && sd.team.stats) : (sd.player && sd.player.stats && sd.player.stats[pname]);
            const it = (arr || []).find(s => s.playType === m.k && (s.side || 'offensive') === 'offensive');
            return it ? it.ppp : null;
        }
        const dict = isTeam
            ? (sd.team && sd.team[activeCat])
            : (sd.player && sd.player[activeCat] && sd.player[activeCat][pname]);
        const v = dict && dict[m.k];
        return typeof v === 'number' ? v : null;
    };

    // 基本數據與百分比統一一位小數（避免同列出現「1」與「0.7」）；Playtype PPP 兩位；Tracking 等保留原始精度（如 PTS/Touch 0.338）
    const fmt = (v, m) => v == null ? '—'
        : m.pct ? v.toFixed(1) + '%'
        : m.playtype ? v.toFixed(2)
        : activeCat === 'base' || activeCat === 'onoff' ? v.toFixed(1) : v;

    // 該欄（賽季）此球員的 metadata：球隊標示與「跨隊不適用」共用同一份來源
    const metaOf = (key, who) => (who === TEAM || (!who && viewMode !== 'PLAYER')) ? null : (data[key]?.player?.meta?.[who || selectedPlayer] || null);
    // 對位防守的指標 key 集合：同屬 defense 類別，但只有這一組綁 TeamID。
    // Hustle / DefenseBox 走 leaguedash，跨隊拿得到值，不可一併標成不適用
    const MATCHUP_KEYS = new Set(((defenseDefs.find(d => d.id === 'MatchupDefense') || {}).metrics || []).map(m => m.key));
    // 只在「值真的是 null」時才問是不是不適用；有數字一律照常顯示（含真的是 0）
    const naOf = (key, m) => {
        const meta = metaOf(key);
        if (!meta || !meta.isNewcomer) return null;
        if (activeCat === 'onoff' || (activeCat === 'defense' && MATCHUP_KEYS.has(m.k))) return window.NA_REASON.CROSS_TEAM;
        return null;
    };
    const toggle = k => setSelected(prev => prev.includes(k) ? prev.filter(x => x !== k) : [...prev, k]);

    // 臉書用純文字：臉書不吃表格、字是比例字寬對不齊，改成「指標｜各季值」一行一項，第一行是賽季表頭。
    // 數字格式與畫面上的表格相同（fmt）；全部同賽別時表頭只寫年份、賽別放第一格，混選才用「24-25例」並附圖例
    const fbText = () => {
        if (cols.some(c => !data[c.key])) { UI.toast('資料還在載入，請稍候再複製'); return null; }
        const TYPE_LABEL = { regular: '例行賽', playoffs: '季後賽' };
        const sameType = cols.every(c => c.type === cols[0].type) && TYPE_LABEL[cols[0].type];
        const tags = cols.map(c => window.tagOfMeta(metaOf(c.key)));
        const head = cols.map((c, i) => (sameType && c.season ? c.season.slice(2) : (c.short || c.label)) + tags[i]);
        // Playtype 表格只有英文 key，臉書讀者看不懂 → 取 glossary 定義冒號前的中文名（去掉括號補充）放前面
        const ptName = k => (((window.GLOSSARY || {})[`PT_${k}`] || {}).def || '').split('：')[0].replace(/（.*?）/g, '');
        const rows = metrics.map(m => {
            const vals = cols.map(c => fmt(getVal(c.key, m), m));
            const name = m.playtype ? [ptName(m.k), m.k].filter(Boolean).join(' ')
                : `${m.l}${m.e && m.e !== m.l ? ` ${m.e}` : ''}`;
            return { line: `${name}｜${vals.join('｜')}`, hasNull: vals.includes('—') };
        });
        const notes = [
            !sameType && '例＝例行賽、季＝季後賽',
            tags.some(Boolean) && '@隊名＝該季效力他隊',
            rows.some(r => r.hasNull) && '—＝該季無此項資料',
        ].filter(Boolean);
        const subject = viewMode === 'PLAYER' ? selectedPlayer : '灰狼全隊';
        return [
            `【${subject}｜跨季比較・${CATS[activeCat].label}${activeCat === 'playtype' ? '（進攻 PPP）' : ''}】`,
            `${sameType || '賽季'}｜${head.join('｜')}`,
            '',
            ...rows.map(r => r.line),
            '',
            ...(notes.length ? [notes.join('；')] : []),
            `資料：NBA.com Stats${activeCat === 'playtype' ? '／Synergy' : ''}，各季期末快照`,
            `${location.origin}${location.pathname}${location.hash}`,
        ].join('\n');
    };

    // ── 逐季折線（疊圖）──
    const openMetrics = metrics.filter(m => openKeys.includes(m.k));
    const toggleMetric = (m) => setOpenKeys(prev => prev.includes(m.k) ? prev.filter(k => k !== m.k) : (prev.length >= MAX_OPEN ? prev : [...prev, m.k]));
    // 可加入比較的球員：已載入各季資料裡出現過的名字（不含主角）
    const playerPool = viewMode !== 'PLAYER' ? [] : [...new Set(cols.flatMap(c => Object.keys(data[c.key]?.player?.meta || {})))]
        .filter(n => n !== selectedPlayer).sort();
    const SERIES_COLORS = ['#12A150', '#5B9BD5', '#F59E0B', '#A78BFA'];
    const INDEX_COLORS = ['#12A150', '#5B9BD5', '#F59E0B', '#A78BFA', '#C4CED2', '#2DD4BF', '#F472B6', '#FBBF24'];
    const nameOf = who => who === TEAM || (!who && viewMode === 'TEAM') ? '全隊' : (who || selectedPlayer);
    // 圖上標籤用姓（Jr. 之類連同前一個字）
    const shortName = n => { if (n === '全隊') return n; const w = n.split(' '); return /^(Jr\.?|Sr\.?|II|III|IV)$/.test(w[w.length - 1]) ? w.slice(-2).join(' ') : w[w.length - 1]; };
    const xsOf = () => cols.map(c => c.short || c.label);
    const seriesFor = (m) => [null, ...extras].map((who, i) => {
        const tags = cols.map(c => window.tagOfMeta(metaOf(c.key, who)) || '');
        return {
            key: who || 'main', label: shortName(nameOf(who)), color: who === TEAM ? '#C4CED2' : SERIES_COLORS[i % SERIES_COLORS.length],
            dashed: who === TEAM, values: cols.map(c => getVal(c.key, m, who)), hollow: tags.map(Boolean), tags,
        };
    });
    const fmtOf = m => v => m.playtype ? v.toFixed(2) : m.pct ? v.toFixed(1) : (Number.isInteger(v) ? String(v) : v.toFixed(1));
    // 指數化：每項以「第一個有值的季」＝100，不同單位才能放同一把尺看成長幅度
    const indexSeries = () => openMetrics.map((m, i) => {
        const vals = cols.map(c => getVal(c.key, m));
        const base = vals.find(v => typeof v === 'number' && v !== 0);
        return { key: m.k, label: m.l, color: INDEX_COLORS[i % INDEX_COLORS.length], values: vals.map(v => typeof v === 'number' && base ? +(v / base * 100).toFixed(1) : null) };
    });

    const UI = window.UI;
    const catSub = {
        base: '傳統數據，各季終點快照',
        playtype: 'Synergy 進攻面 PPP（每球權得分），各季終點快照',
        tracking: 'NBA Tracking，各季終點快照',
        shooting: '分區命中率，各季終點快照',
        defense: '最近防守者／Hustle／防守 box，各季終點快照',
        onoff: '球隊在該球員上場／下場時的每 100 回合效率',
    }[activeCat];

    return (
        <div className="space-y-8">
            {window.SeasonPaceChart && <window.SeasonPaceChart viewMode={viewMode} playerId={playerId} playerName={selectedPlayer} />}

            {/* 賽季多選 + 類別 */}
            <div className="space-y-2.5">
                <div className="flex flex-wrap items-center gap-1.5">
                    <span className="mr-1 text-[11px] text-slate-500">比較賽季</span>
                    {seasons.map(s => (
                        <UI.Chip key={s.key} active={selected.includes(s.key)} onClick={() => toggle(s.key)}>{s.label}</UI.Chip>
                    ))}
                </div>
            </div>

            <UI.Section title={viewMode === 'PLAYER' ? selectedPlayer : '全隊'} en="Season by Season" accent="blue"
                sub={`${catSub} · 點指標列看逐季折線（可多選，同一指標可疊加其他球員）· 「—」表示該季無此類別資料`}
                right={<UI.Seg ariaLabel="比較類別" size="sm" value={activeCat} onChange={(c) => { setCat(c); setOpenKeys([]); }}
                    options={catKeys.map(c => ({ value: c, label: CATS[c].label }))} />}>
                {cols.length === 0 ? (
                    <UI.Note>請至少選一個賽季</UI.Note>
                ) : (
                    <div className="space-y-4">
                        {/* 逐季折線（點指標列展開；可多選、可疊加球員） */}
                        {openMetrics.length > 0 && LineOverlay && (
                            <div ref={chartRef} className="border border-white/10 p-4">
                                <div className="mb-3 flex flex-wrap items-center gap-x-3 gap-y-2">
                                    <span className="text-[13px] font-medium text-slate-100">
                                        {openMetrics.length === 1 ? `${openMetrics[0].l} 逐季變化` : `${openMetrics.length} 項指標逐季變化`}
                                    </span>
                                    {openMetrics.length > 1 && (
                                        <UI.Seg ariaLabel="多指標呈現" size="sm" value={multiMode} onChange={setMultiMode}
                                            options={[{ value: 'small', label: '小圖並排' }, { value: 'index', label: '指數化疊圖（首季＝100）' }]} />
                                    )}
                                    <span className="ml-auto flex items-center gap-2">
                                        <button type="button" onClick={() => setOpenKeys([])} className="min-h-[24px] text-[12px] text-slate-400 hover:text-slate-100">✕ 收合</button>
                                        <UI.ExportMenu title={`跨季折線（${openMetrics.map(m => m.l).join('、')}）`} getNode={() => chartRef.current}
                                            csv={() => ({ header: ['指標', '對象', ...cols.map(c => c.label)],
                                                rows: openMetrics.flatMap(m => [null, ...extras].map(who => [m.l, nameOf(who), ...cols.map(c => { const v = getVal(c.key, m, who); return v == null ? '' : v; })])) })} />
                                    </span>
                                </div>
                                {/* 疊加球員（球員模式；多指標指數化時只畫主角） */}
                                {viewMode === 'PLAYER' && !(openMetrics.length > 1 && multiMode === 'index') && (
                                    <div className="mb-3 flex flex-wrap items-center gap-1.5">
                                        <span className="mr-1 text-[11px] text-slate-500">疊加比較</span>
                                        <span className="inline-flex items-center gap-1.5 rounded-full border border-[#12A150] px-3 py-1 text-xs text-slate-100">
                                            <i className="inline-block h-[3px] w-3 bg-[#12A150]"></i>{selectedPlayer}
                                        </span>
                                        {extras.map((who, i) => (
                                            <button key={who} type="button" onClick={() => setExtras(x => x.filter(y => y !== who))} title="移除"
                                                className="inline-flex min-h-[24px] items-center gap-1.5 rounded-full border border-white/20 px-3 py-1 text-xs text-slate-200 hover:border-white/40">
                                                <i className="inline-block h-[3px] w-3" style={{ background: who === TEAM ? '#C4CED2' : SERIES_COLORS[(i + 1) % SERIES_COLORS.length] }}></i>
                                                {nameOf(who)} ✕
                                            </button>
                                        ))}
                                        {extras.length < MAX_EXTRAS && (<>
                                            <label className="sr-only" htmlFor="cmp-add">加入比較</label>
                                            <select id="cmp-add" value="" onChange={e => { const v = e.target.value; if (v) setExtras(x => x.includes(v) ? x : [...x, v]); }}
                                                className={UI.selectClass(false)}>
                                                <option value="">＋加入比較</option>
                                                {!extras.includes(TEAM) && <option value={TEAM}>全隊</option>}
                                                {playerPool.filter(n => !extras.includes(n)).map(n => <option key={n} value={n}>{n}</option>)}
                                            </select>
                                        </>)}
                                    </div>
                                )}
                                {openMetrics.length === 1 ? (
                                    <LineOverlay xs={xsOf()} series={seriesFor(openMetrics[0])} unit={openMetrics[0].pct ? '%' : ''} fmt={fmtOf(openMetrics[0])}
                                        height={260} ariaLabel={`${openMetrics[0].l} 逐季折線`} />
                                ) : multiMode === 'index' ? (
                                    <LineOverlay xs={xsOf()} series={indexSeries()} height={280} ariaLabel="指數化疊圖" />
                                ) : (
                                    <div className="grid grid-cols-1 border-l border-t border-white/[0.08] sm:grid-cols-2 lg:grid-cols-4">
                                        {openMetrics.map(m => (
                                            <div key={m.k} className="border-b border-r border-white/[0.08] px-3 pb-2 pt-2.5">
                                                <div className="mb-1 flex justify-between gap-2 text-[12px] text-slate-300"><span>{m.l}</span>{m.e && <span className="truncate font-mono text-[10px] text-slate-500">{m.e}</span>}</div>
                                                <LineOverlay mini xs={xsOf()} series={seriesFor(m)} unit={m.pct ? '%' : ''} fmt={fmtOf(m)} ariaLabel={`${m.l} 逐季小圖`} />
                                            </div>
                                        ))}
                                    </div>
                                )}
                                <p className="mt-2 text-[11px] text-slate-500">
                                    {openMetrics.length > 1 && multiMode === 'index'
                                        ? '每項以第一個有值的賽季＝100：看各面向成長幅度，不比絕對高低'
                                        : openMetrics.length > 1 ? '各小圖 Y 軸獨立：看形狀，不比高度' : '空心點＋虛線＝該季效力他隊（@隊名）'}
                                    {extras.includes(TEAM) && ' · 銀色虛線＝全隊'}
                                </p>
                            </div>
                        )}
                        {/* 比較表：列＝指標、欄＝賽季（依時間排序） */}
                        <div className="flex justify-end">
                            <UI.ExportMenu title={`跨季比較（${CATS[activeCat].label}）`} getNode={() => tableRef.current}
                                csv={() => ({ header: ['指標', '原文', ...cols.map(c => c.label)], rows: metrics.map(m => [m.l, m.e || '', ...cols.map(c => { const v = getVal(c.key, m); return v == null ? '' : v; })]) })}
                                text={fbText} />
                        </div>
                        <div ref={tableRef} className="overflow-x-auto border-t border-white/[0.08]">
                            <table className="w-full text-sm border-collapse">
                                <caption className="sr-only">跨季比較表</caption>
                                <thead>
                                    <tr className="border-b border-white/15">
                                        <th scope="col" className="px-3 py-2 text-left text-[11px] font-normal text-slate-400 max-sm:sticky max-sm:left-0 max-sm:bg-[#0A1626]">指標</th>
                                        {cols.map(c => {
                                            const tag = window.tagOfMeta(metaOf(c.key));
                                            return (
                                                <th key={c.key} scope="col" className="px-3 py-2 text-right text-[11px] font-normal whitespace-nowrap text-slate-400">
                                                    {c.short || c.label}
                                                    {tag && <span className="ml-1 font-mono text-[10px] text-amber-400/80">{tag}</span>}
                                                </th>
                                            );
                                        })}
                                    </tr>
                                </thead>
                                <tbody>
                                    {metrics.map(m => {
                                        const open = openKeys.includes(m.k);
                                        return (
                                            <tr key={m.k} onClick={() => toggleMetric(m)} aria-selected={open}
                                                className={`cursor-pointer border-b border-white/[0.06] transition-colors ${open ? 'bg-[#12A150]/[0.08]' : 'odd:bg-white/[0.015] hover:bg-white/[0.04]'}`}>
                                                <th scope="row" className="px-3 py-2 text-left font-normal max-sm:sticky max-sm:left-0 max-sm:bg-[#0A1626]">
                                                    <span className="text-slate-200">{m.l}</span>
                                                    {m.e && <span className="ml-1.5 font-mono text-[10px] text-slate-500">{m.e}</span>}
                                                </th>
                                                {cols.map(c => {
                                                    const v = getVal(c.key, m);
                                                    const na = v == null ? naOf(c.key, m) : null;
                                                    return (
                                                        <td key={c.key} title={na || undefined}
                                                            className={`px-3 py-2 text-right font-mono tabular-nums ${v == null ? 'text-slate-600' : 'text-slate-200'} ${na ? 'cursor-help' : ''}`}>
                                                            {fmt(v, m)}
                                                        </td>
                                                    );
                                                })}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                        <p className="text-[11px] leading-relaxed text-slate-500">
                            欄頭有 <span className="font-mono text-amber-400/80">@隊名</span> 者為該季在別隊，
                            其最近防守者（Defense Dashboard）與 On/Off 為跨隊不適用（滑過「—」可看說明）。
                        </p>
                    </div>
                )}
            </UI.Section>
        </div>
    );
};

window.ComparisonTab = ComparisonTab;


// ---------- RadarPanel.js ----------
// 雷達圖面板：軸可自選（Playtype percentile + Tracking 百分比，皆 0-100）
// 兩種尺度語意不同（PR=聯盟百分位、%=原始數值），軸名一律帶 scale 標示，避免讀者把形狀當同一把尺+ 疊加多序列 + 自選指標比較表
// series：[{key,label,color,stats(synergy array),tracking(dict)}]；第一個為主序列
const RadarPanel = ({ series, viewSide }) => {
    const { useState } = React;
    const R = window.Recharts || {};
    const { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer, Tooltip } = R;
    const PLAY = window.PlayTypesList || [];
    const loadPref = (k, f) => { try { const v = localStorage.getItem(k); return v == null ? f : JSON.parse(v); } catch (e) { return f; } };
    const savePref = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) { } };

    // 指標目錄（依攻守）
    const CATALOG = viewSide === 'offensive' ? [
        ...PLAY.map(pt => ({ key: 'pt_' + pt, label: pt, scale: 'PR', pt, side: 'offensive' })),
        { key: 'DRIVE_PTS_PCT', label: '每百次切入得分', scale: '', tk: 'DRIVE_PTS_PCT' },  // 切入得分 ÷ 切入次數 × 100，不是百分比
        { key: 'DRIVE_FG_PCT', label: '切入命中率', scale: '%', tk: 'DRIVE_FG_PCT' },
        { key: 'CATCH_SHOOT_EFG_PCT', label: '接球跳投 eFG', scale: '%', tk: 'CATCH_SHOOT_EFG_PCT' },
        { key: 'CATCH_SHOOT_FG3_PCT', label: '接球跳投三分', scale: '%', tk: 'CATCH_SHOOT_FG3_PCT' },
        { key: 'PULL_UP_EFG_PCT', label: '急停跳投 eFG', scale: '%', tk: 'PULL_UP_EFG_PCT' },
        { key: 'REB_COL_PCT', label: '籃板機會轉換率', scale: '%', tk: 'REB_COL_PCT' },
    ] : [
        ...PLAY.filter(pt => pt !== 'Cut' && pt !== 'Misc').map(pt => ({ key: 'pt_' + pt, label: pt + ' 防守', scale: 'PR', pt, side: 'defensive' })),
        { key: 'REB_CONTEST_PCT', label: '競爭籃板率', scale: '%', tk: 'REB_CONTEST_PCT' },
    ];
    const catMap = Object.fromEntries(CATALOG.map(c => [c.key, c]));
    const axisName = c => c ? [c.label, c.scale].filter(Boolean).join(' ') : '';
    const DEFAULTS = viewSide === 'offensive'
        ? ['pt_Isolation', 'DRIVE_PTS_PCT', 'CATCH_SHOOT_EFG_PCT', 'pt_Transition', 'pt_PRBallHandler']
        : ['pt_Isolation', 'pt_Spotup', 'pt_PRBallHandler', 'REB_CONTEST_PCT'];

    const prefKey = `wt_radar_axes_${viewSide}`;
    const [axes, setAxes] = useState(() => {
        const saved = loadPref(prefKey, null);
        const valid = (saved || []).filter(k => catMap[k]);
        return valid.length >= 3 ? valid : DEFAULTS.filter(k => catMap[k]);
    });
    const [editing, setEditing] = useState(false);
    const chartRef = React.useRef(null);

    const getVal = (c, s) => {
        if (!c) return null;
        if (c.pt) { const it = (s.stats || []).find(x => x.playType === c.pt && (x.side || 'offensive') === c.side); return it ? it.percentile : null; }
        const v = (s.tracking || {})[c.tk]; return typeof v === 'number' ? v : null;
    };

    const toggleAxis = k => {
        setAxes(prev => {
            let next;
            if (prev.includes(k)) { if (prev.length <= 3) return prev; next = prev.filter(x => x !== k); }
            else { if (prev.length >= 6) return prev; next = [...prev, k]; }
            savePref(prefKey, next);
            return next;
        });
    };
    const resetAxes = () => { setAxes(DEFAULTS.filter(k => catMap[k])); savePref(prefKey, DEFAULTS); };

    const radarData = axes.map(k => {
        const c = catMap[k];
        const row = { subject: c ? axisName(c) : k, fullMark: 100 };
        series.forEach(s => { row[s.label] = getVal(c, s) || 0; });
        return row;
    });

    return (
        <div className="flex flex-col items-center border border-white/10 p-3">
            <div className="w-full flex justify-between items-center px-2 mt-1">
                <h3 className="text-[13px] font-medium text-slate-200">{viewSide === 'offensive' ? '進攻雷達網' : '防守雷達網'}</h3>
                <span className="flex items-center gap-2">
                <window.UI.ExportMenu title={viewSide === 'offensive' ? '進攻雷達' : '防守雷達'} getNode={() => chartRef.current}
                    csv={() => ({ header: ['軸', ...series.map(s => s.label)], rows: axes.map(k => { const c = catMap[k]; return [c ? axisName(c) : k, ...series.map(s => { const v = getVal(c, s); return v == null ? '' : v; })]; }) })} />
                <button onClick={() => setEditing(e => !e)} className="rounded-full border border-white/15 px-2.5 py-1 text-[11px] text-slate-400 hover:text-slate-100">自訂軸</button>
                </span>
            </div>

            {editing && (
                <div className="mb-1 w-full border border-white/10 p-2">
                    <div className="flex justify-between items-center mb-1">
                        <span className="text-[10px] text-slate-500">勾選 3~6 個軸（{axes.length}/6）</span>
                        <button onClick={resetAxes} className="text-[10px] text-[#C4CED2] underline-offset-2 hover:underline">恢復預設</button>
                    </div>
                    <div className="flex flex-wrap gap-1 max-h-[140px] overflow-y-auto">
                        {CATALOG.map(c => {
                            const on = axes.includes(c.key);
                            return <button key={c.key} onClick={() => toggleAxis(c.key)}
                                className={`rounded-full border px-2.5 py-0.5 text-[11px] ${on ? 'border-[#12A150] bg-[#12A150]/10 text-slate-50' : 'border-white/15 text-slate-400 hover:border-white/30'}`}>{axisName(c)}</button>;
                        })}
                    </div>
                </div>
            )}

            <div ref={chartRef} className="w-full">
            {RadarChart && ResponsiveContainer ? (
                <div className="w-full h-[240px] sm:h-[280px]">
                    <ResponsiveContainer width="100%" height="100%">
                        <RadarChart cx="50%" cy="50%" outerRadius="60%" data={radarData} margin={{ top: 18, right: 30, bottom: 18, left: 30 }}>
                            <PolarGrid stroke="rgba(196, 206, 210, 0.16)" />
                            <PolarAngleAxis dataKey="subject" tick={{ fill: '#C4CED2', fontSize: 11 }} />
                            <PolarRadiusAxis angle={30} domain={[0, 100]} tick={false} axisLine={false} />
                            {series.map((s, i) => (
                                <Radar key={s.key} name={s.label} dataKey={s.label} stroke={s.color} fill={s.color} isAnimationActive={false}
                                    fillOpacity={i === 0 ? 0.35 : 0.15} strokeWidth={i === 0 ? 2 : 1.5} />
                            ))}
                            <Tooltip contentStyle={{ backgroundColor: '#0C1A2E', borderColor: 'rgba(255,255,255,0.15)', borderRadius: 0 }} itemStyle={{ color: '#F8FAFC' }} />
                        </RadarChart>
                    </ResponsiveContainer>
                </div>
            ) : <div className="w-full h-[240px] flex items-center justify-center text-slate-500 text-xs">雷達圖模組載入中...</div>}

            <p className="w-full px-2 pb-1 text-[10px] leading-relaxed text-slate-500">
                PR＝Synergy 聯盟百分位（0–100）；%＝原始百分比；未標示者為原始數值（如每百次切入得分）。不同尺度共用 0–100 軸，形狀只代表各軸相對位置，不同尺度的軸不能直接互比。
            </p>

            {series.length > 1 && (
                <div className="flex flex-wrap gap-x-3 gap-y-1 px-2 pb-1 justify-center">
                    {series.map(s => (
                        <div key={s.key} className="flex items-center gap-1 text-[10px] text-slate-300">
                            <span className="w-2.5 h-2.5 rounded-sm inline-block" style={{ backgroundColor: s.color }}></span>{s.label}
                        </div>
                    ))}
                </div>
            )}

            </div>

            {/* 自選指標比較表（數值精確） */}
            {series.length > 1 && (
                <div className="w-full mt-1 overflow-x-auto">
                    <table className="w-full text-[11px]">
                        <thead className="text-slate-500">
                            <tr><th className="text-left px-2 py-1">指標</th>
                                {/* shortLabel：呼叫端已備好的縮寫（如 24例@CHA）。截斷會吃掉 @XXX 球隊標示，故優先採用 */}
                                {series.map(s => <th key={s.key} className="text-right px-2 py-1" style={{ color: s.color }}>{s.shortLabel || (s.label.length > 6 ? s.label.slice(0, 6) : s.label)}</th>)}</tr>
                        </thead>
                        <tbody>
                            {axes.map(k => { const c = catMap[k]; return (
                                <tr key={k} className="border-t border-white/[0.08]">
                                    <td className="text-left px-2 py-1 text-slate-400">{c ? axisName(c) : k}</td>
                                    {series.map(s => { const v = getVal(c, s); return <td key={s.key} className="text-right px-2 py-1 font-mono text-slate-200">{v == null ? '—' : v}</td>; })}
                                </tr>
                            ); })}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
};

window.RadarPanel = RadarPanel;


// ---------- HistoryModal.js ----------
// 卡片走勢 Modal。從 App.js 抽出來的原因不只是檔案太大：
// 原本它定義在 App 元件「內部」，每次 App re-render 都會產生一個新的元件型別，
// React 會把整棵子樹卸載重掛，使用者選的指標與日期區間因此被丟掉。
//
// 相依一律走 props / window，不在檔案頂層宣告任何東西——bundle 是單一 script scope，
// 與 App.js 頂層的 `const { useState, useEffect, useMemo } = React` 重複宣告會讓整包 SyntaxError。
const HistoryModal = ({ cardInfo, onClose, viewMode, viewSide, selectedPlayer, isHistoryMode, history, playerTag = '', seasonTypeView }) => {
    const { useState, useMemo, useEffect } = React;
    const Icons = window.Icons;
    const { SimpleLineChart, MultiLineChart } = window;
    const trackingDefs = window.trackingDefs || [];
    const shootingDefs = window.shootingDefs || [];
    const clutchDefs = window.clutchDefs || [];
    const defenseDefs = window.defenseDefs || [];
    const oppZonesDefs = window.oppZonesDefs || [];
    const [chartMetrics, setChartMetrics] = useState([]); // array
    const [filterMode, setFilterMode] = useState('recent');
    const [recentCount, setRecentCount] = useState(10);
    const [dateStart, setDateStart] = useState('');
    const [dateEnd, setDateEnd] = useState('');
    // 歷史模式 'all'；當季沿用刊頭選的賽別（舊版用今天日期判斷，休賽期會誤設成例行賽）
    const [seasonTypeFilter, setSeasonTypeFilter] = useState(() => {
        if (isHistoryMode) return 'all';
        if (seasonTypeView) return seasonTypeView === 'playoffs' ? '季後賽' : '例行賽';
        const phase = window.getSeasonPhase ? window.getSeasonPhase() : { type: 'regular' };
        return phase.type === 'playoffs' ? '季後賽' : '例行賽';
    });
    // Esc 關閉
    useEffect(() => {
        const onKey = (e) => { if (e.key === 'Escape') onClose(); };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [onClose]);

    const targetHistory = history || [];
    // tracking 類卡片的資料來源欄位（'tracking' | 'shooting' | 'clutch'）
    const srcKey = cardInfo.source || 'tracking';

    const baseStats = useMemo(() => {
        return targetHistory.map(entry => {
            let stat, trackingDat;
            if (viewMode === 'TEAM') {
                if (cardInfo.type === 'playtype') stat = entry.stats?.find(s => s.playType === cardInfo.id && s.side === viewSide);
                else trackingDat = entry[srcKey] || {};
            } else {
                if (cardInfo.type === 'playtype') stat = entry.stats?.[selectedPlayer]?.find(s => s.playType === cardInfo.id && s.side === viewSide);
                else trackingDat = entry[srcKey]?.[selectedPlayer] || {};
            }
            return { date: entry.date, seasonType: entry.seasonType, stat, tracking: trackingDat };
        }).filter(item => (cardInfo.type === 'playtype' ? item.stat : Object.keys(item.tracking || {}).length > 0));
    }, [targetHistory, viewMode, selectedPlayer, cardInfo, viewSide]);

    const displayedStats = useMemo(() => {
        let filtered = [...baseStats];
        if (seasonTypeFilter !== 'all') {
            filtered = filtered.filter(item => item.seasonType === seasonTypeFilter);
        }
        if (filterMode === 'recent') {
            if (recentCount !== 'ALL') filtered = filtered.slice(0, recentCount);
        } else {
            if (dateStart) filtered = filtered.filter(item => item.date >= dateStart);
            if (dateEnd) filtered = filtered.filter(item => item.date <= dateEnd);
        }
        return filtered;
    }, [baseStats, filterMode, recentCount, dateStart, dateEnd, seasonTypeFilter]);

    const chartData = [...displayedStats].reverse();
    const toggleChart = (metric) => setChartMetrics(prev => prev.includes(metric) ? prev.filter(m => m !== metric) : [...prev, metric]);

    let title = "", cols = [];
    if (cardInfo.type === 'playtype') {
        title = `${cardInfo.id}（${viewSide === 'offensive' ? '進攻' : '防守'}） (Synergy Playtype)`;
        cols = [{ k: 'ppp', l: 'PPP', e: 'PPP' }, { k: 'fgPct', l: '命中率', e: 'FG%' }, { k: 'percentile', l: '聯盟百分位', e: 'Percentile' }, { k: 'poss', l: '每場球權', e: 'Poss/G' }];
    } else {
        const def = [...trackingDefs, ...shootingDefs, ...clutchDefs, ...defenseDefs, ...oppZonesDefs].find(t => t.id === cardInfo.id);
        title = def?.title || cardInfo.id;
        cols = def ? def.metrics.map(m => ({ k: m.key, l: m.label, e: m.englishLabel })) : [];
    }

    const UI = window.UI;
    const [zh, en] = UI.splitTitle(title);
    const subject = viewMode === 'PLAYER' ? selectedPlayer + playerTag : '全隊';

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-2 sm:p-4" onMouseDown={onClose}>
            <div role="dialog" aria-modal="true" aria-labelledby="history-modal-title" onMouseDown={e => e.stopPropagation()}
                className="flex max-h-[95vh] w-full max-w-full flex-col overflow-hidden border border-white/15 bg-[#0C1A2E] shadow-2xl sm:max-h-[90vh] sm:max-w-3xl">
                <div className="flex shrink-0 items-start justify-between gap-4 border-b border-white/10 px-5 py-4">
                    <div className="min-w-0">
                        <p className="font-mono text-[11px] text-slate-500">{subject} · 當季走勢</p>
                        <h3 id="history-modal-title" className="mt-0.5 flex items-baseline gap-2 text-[18px] font-bold text-slate-50">
                            {zh}{en && <span className="font-mono text-[11px] font-normal text-slate-500">{en}</span>}
                        </h3>
                    </div>
                    <button type="button" onClick={onClose} aria-label="關閉" className="shrink-0 text-slate-400 hover:text-white"><Icons.X /></button>
                </div>

                <div className="flex shrink-0 flex-wrap items-center gap-2 border-b border-white/10 px-5 py-3">
                    <UI.Seg ariaLabel="近幾場" size="sm" value={filterMode === 'recent' ? String(recentCount) : ''}
                        onChange={(v) => { setFilterMode('recent'); setRecentCount(v === 'ALL' ? 'ALL' : Number(v)); setDateStart(''); setDateEnd(''); }}
                        options={[5, 10, 20, 'ALL'].map(c => ({ value: String(c), label: c === 'ALL' ? '全部' : `近 ${c} 筆` }))} />
                    {!isHistoryMode && (
                        <UI.Seg ariaLabel="賽別" size="sm" value={seasonTypeFilter} onChange={setSeasonTypeFilter}
                            options={[{ value: '例行賽', label: '例行賽' }, { value: '季後賽', label: '季後賽' }]} />
                    )}
                    <span className="flex items-center gap-2 text-xs text-slate-500">
                        <input type="date" aria-label="起始日" value={dateStart} onChange={(e) => { setDateStart(e.target.value); setFilterMode('range'); }} className={UI.selectClass(!!dateStart)} />
                        ~
                        <input type="date" aria-label="結束日" value={dateEnd} onChange={(e) => { setDateEnd(e.target.value); setFilterMode('range'); }} className={UI.selectClass(!!dateEnd)} />
                    </span>
                </div>

                <div className="shrink-0 border-b border-white/10 px-5 py-3">
                    <p className="mb-2 text-[12px] text-slate-400">點下方表格欄位標題切換折線圖（可多選疊加）· 每筆為一份快照（截至該日的累計數據）</p>
                    {chartMetrics.length === 1 && (<SimpleLineChart data={chartData} dataKey={chartMetrics[0]} color="#12A150" />)}
                    {chartMetrics.length >= 2 && (<MultiLineChart data={chartData} metrics={cols.filter(c => chartMetrics.includes(c.k)).map(c => ({ key: c.k, label: c.l }))} />)}
                </div>

                <div className="overflow-auto">
                    <table className="w-full border-collapse text-sm">
                        <caption className="sr-only">{zh} 各快照數值</caption>
                        <thead className="sticky top-0 bg-[#0C1A2E]">
                            <tr className="border-b border-white/15">
                                <th scope="col" className="px-5 py-2 text-left text-[11px] font-normal text-slate-400">日期</th>
                                {cols.map(c => {
                                    const on = chartMetrics.includes(c.k);
                                    return (
                                        <th key={c.k} scope="col" className="px-3 py-2 text-right font-normal">
                                            <button type="button" aria-pressed={on} onClick={() => toggleChart(c.k)}
                                                className={`inline-flex flex-col items-end gap-0.5 border-b-2 pb-0.5 ${on ? 'border-[#12A150] text-slate-50' : 'border-transparent text-slate-400 hover:text-slate-100'}`}>
                                                <span className="text-[11px] whitespace-nowrap">{c.l}</span>
                                                {c.e && <span className="font-mono text-[10px] text-slate-500 whitespace-nowrap">{c.e}</span>}
                                            </button>
                                        </th>
                                    );
                                })}
                            </tr>
                        </thead>
                        <tbody>
                            {displayedStats.length === 0 && (
                                <tr><td colSpan={cols.length + 1} className="px-5 py-8 text-center text-sm text-slate-500">此篩選條件下沒有快照</td></tr>
                            )}
                            {displayedStats.map(item => (
                                <tr key={item.date} className="border-b border-white/[0.06] odd:bg-white/[0.015] hover:bg-white/[0.04]">
                                    <td className="px-5 py-2 font-mono text-[13px] text-slate-300">{item.date}</td>
                                    {cols.map(c => {
                                        const val = cardInfo.type === 'playtype' ? item.stat?.[c.k] : item.tracking?.[c.k];
                                        return <td key={c.k} className={`px-3 py-2 text-right font-mono tabular-nums ${val == null ? 'text-slate-600' : 'text-slate-200'}`}>{val ?? '—'}</td>;
                                    })}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                <div className="shrink-0 border-t border-white/10 px-5 py-2 text-[11px] text-slate-500">跨賽季比較請用「跨季」章節 · Esc 關閉</div>
            </div>
        </div>
    );
};
window.HistoryModal = HistoryModal;


// ---------- urlState.js ----------
// 網址狀態：把目前畫面寫進網址 hash，貼到筆記裡下次一點就回到同一個畫面。
// 用 hash 而非 query：GitHub Pages 是靜態站，hash 不會送到伺服器、也不需要路由設定。
// 格式（只寫非預設值，網址保持短）：
//   #v=player&p=Jaden%20McDaniels&tab=shooting&s=2024-25_playoffs&t=playoffs&d=2026-06-15&side=def
//   v    球隊 team / 球員 player
//   p    球員名（每日快照以 playerName 為 key，所以用名字而非 ID）
//   tab  overview / splits / shooting / defense / playtype / comparison
//   s    賽季 key（current 省略；其餘同 SEASON_OPTIONS.key = 歷史 docId）
//   t    當季賽別 regular / playoffs（僅當季）
//   d    當季「截至日期」YYYY-MM-DD（僅當季，空=最新）
//   side off / def
//   m    Splits 打開逐場走勢的指標 key（如 D_FG_PCT；僅 tab=splits）
//   hl   Splits 走勢上圈出的那一場 YYYY-MM-DD（從單場頁點指標過來時帶；僅 tab=splits）
// 單場比賽頁（另一種畫面，沒有 v=）：
//   #game=2026-04-10&p=Rudy%20Gobert
//   game 比賽日期；p 展開進階的灰狼球員（可省略）
window.UrlState = (function () {
    const TABS = ['overview', 'splits', 'shooting', 'defense', 'playtype', 'comparison'];
    const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
    const METRIC_RE = /^[A-Z0-9_]+$/;

    const parse = (hash) => {
        const out = {};
        const q = new URLSearchParams(String(hash || '').replace(/^#/, ''));
        // 單場頁：有 game 且沒有 v。p 在這裡是「展開的球員」，不可改動主畫面的 selectedPlayer
        if (DATE_RE.test(q.get('game') || '') && !q.get('v')) {
            out.gameDate = q.get('game');
            out.gamePlayer = q.get('p') || '';
            return out;
        }
        const v = q.get('v');
        if (v === 'team') out.viewMode = 'TEAM';
        if (v === 'player') out.viewMode = 'PLAYER';
        if (q.get('p')) out.selectedPlayer = q.get('p');
        if (TABS.includes(q.get('tab'))) out.activeTab = q.get('tab');
        const s = q.get('s');
        if (s && (s === 'current' || (window.SEASON_OPTIONS || []).some(o => o.key === s))) out.selectedSeasonKey = s;
        if (q.get('t') === 'regular' || q.get('t') === 'playoffs') out.seasonTypeView = q.get('t');
        if (DATE_RE.test(q.get('d') || '')) out.selectedDate = q.get('d');
        if (q.get('side') === 'off') out.viewSide = 'offensive';
        if (q.get('side') === 'def') out.viewSide = 'defensive';
        if (out.activeTab === 'splits') {
            if (METRIC_RE.test(q.get('m') || '')) out.focusMetric = q.get('m');
            if (out.focusMetric && DATE_RE.test(q.get('hl') || '')) out.highlightDate = q.get('hl');
        }
        // 有 v= 代表這是本站產生的完整連結：沒寫的項目一律是預設值（serialize 只寫非預設值），
        // 不可退回瀏覽器偏好——否則同一條連結會因為「這台電腦上次看過什麼」而開出不同畫面
        if (out.viewMode) {
            if (!out.activeTab) out.activeTab = 'overview';
            if (!out.selectedSeasonKey) out.selectedSeasonKey = 'current';
            if (!out.viewSide) out.viewSide = 'offensive';
        }
        return out;
    };

    // URLSearchParams 會把空白編成 +，換成 %20 讓網址在筆記軟體裡比較好讀、也不會被誤判
    const toStr = (q) => q.toString().replace(/\+/g, '%20');

    const serialize = (st) => {
        const q = new URLSearchParams();
        if (st.gameDate) {
            q.set('game', st.gameDate);
            if (st.gamePlayer) q.set('p', st.gamePlayer);
            return toStr(q);
        }
        q.set('v', st.viewMode === 'PLAYER' ? 'player' : 'team');
        if (st.viewMode === 'PLAYER' && st.selectedPlayer) q.set('p', st.selectedPlayer);
        if (st.activeTab && st.activeTab !== 'overview') q.set('tab', st.activeTab);
        const isCurrent = !st.selectedSeasonKey || st.selectedSeasonKey === 'current';
        if (!isCurrent) q.set('s', st.selectedSeasonKey);
        if (isCurrent && st.seasonTypeView) q.set('t', st.seasonTypeView);
        if (isCurrent && st.selectedDate) q.set('d', st.selectedDate);
        if (st.viewSide === 'defensive') q.set('side', 'def');
        if (st.activeTab === 'splits' && st.focusMetric) {
            q.set('m', st.focusMetric);
            if (st.highlightDate) q.set('hl', st.highlightDate);
        }
        return toStr(q);
    };

    // 給連結用的 href（一般 <a href>：會產生瀏覽紀錄，返回鍵可回上一頁）
    const gameHref = (date, player) => '#' + serialize({ gameDate: date, gamePlayer: player || '' });

    return { parse, serialize, gameHref, TABS };
})();


// ---------- Masthead.js ----------
// 刊頭：Logo + 「Wolves Ledger」字標 + 期別行（賽季·賽別·截至日期·連線狀態）＋ 右側控制項
